window.COURSE = {"version":"0787520d26","units":[{"id":1,"title":"Neu in der Gemeinde","subtitle":"Sich bei der Einwohnerkontrolle anmelden","level":"A2","theme":"Behörden","focus":"Perfekt mit haben und sein","goals":[{"de":"Ich kann mich bei der Gemeinde anmelden und Fragen zu meiner Person beantworten.","en":"I can register with the municipality and answer questions about myself."},{"de":"Ich kann erzählen, was ich letzte Woche gemacht habe.","en":"I can say what I did last week."},{"de":"Ich kann nachfragen, wenn ich etwas nicht verstehe.","en":"I can ask when I don't understand something."}],"vocab":[{"id":"1-0","de":"die Einwohnerkontrolle","forms":"-n","en":"residents' registration office (CH)","ex":"Ich muss mich bei der Einwohnerkontrolle anmelden.","exEn":"I have to register at the residents' office.","aw":"54ab7aa3fc0f","ae":"cf5c77c20b0c"},{"id":"1-1","de":"sich anmelden","forms":"hat sich angemeldet","en":"to register","ex":"Ich habe mich gestern angemeldet.","exEn":"I registered yesterday.","aw":"652bb141a34f","ae":"9d0ece2a4582"},{"id":"1-2","de":"umziehen","forms":"ist umgezogen","en":"to move (house)","ex":"Wir sind im August nach Winterthur umgezogen.","exEn":"We moved to Winterthur in August.","aw":"c209995e1e57","ae":"60db82422d80"},{"id":"1-3","de":"der Umzug","forms":"Umzüge","en":"move, relocation","ex":"Der Umzug war sehr anstrengend.","exEn":"The move was very tiring.","aw":"c77e788b36f7","ae":"8ea8759b57e3"},{"id":"1-4","de":"der Wohnsitz","forms":"-e","en":"place of residence","ex":"Mein neuer Wohnsitz ist in Winterthur.","exEn":"My new residence is in Winterthur.","aw":"d1e6c14b0e91","ae":"8d870709d833"},{"id":"1-5","de":"der Mietvertrag","forms":"Mietverträge","en":"rental contract","ex":"Bitte bringen Sie den Mietvertrag mit.","exEn":"Please bring the rental contract.","aw":"765889a06069","ae":"0a92b8648f14"},{"id":"1-6","de":"der Ausweis","forms":"-e","en":"ID card, permit card","ex":"Haben Sie einen Ausweis dabei?","exEn":"Do you have ID with you?","aw":"62348c4e78cd","ae":"037dd0dcb173"},{"id":"1-7","de":"der Pass","forms":"Pässe","en":"passport","ex":"Mein Pass ist noch zwei Jahre gültig.","exEn":"My passport is valid for two more years.","aw":"5dfc6b607e0b","ae":"747bf73acb27"},{"id":"1-8","de":"das Formular","forms":"-e","en":"form","ex":"Füllen Sie bitte dieses Formular aus.","exEn":"Please fill in this form.","aw":"646882abc1e7","ae":"56cbeb77d61c"},{"id":"1-9","de":"ausfüllen","forms":"hat ausgefüllt","en":"to fill in","ex":"Ich habe das Formular zu Hause ausgefüllt.","exEn":"I filled in the form at home.","aw":"4916027928be","ae":"6bef193869c8"},{"id":"1-10","de":"unterschreiben","forms":"hat unterschrieben","en":"to sign","ex":"Unterschreiben Sie bitte hier unten.","exEn":"Please sign down here.","aw":"098f898484c6","ae":"7402f01958f6"},{"id":"1-11","de":"die Unterschrift","forms":"-en","en":"signature","ex":"Hier fehlt noch Ihre Unterschrift.","exEn":"Your signature is still missing here.","aw":"ca5b1df3fab9","ae":"d228daf229ce"},{"id":"1-12","de":"der Familienstand","forms":"–","en":"marital status","ex":"Was ist Ihr Familienstand?","exEn":"What is your marital status?","aw":"eeaf0534b50f","ae":"653f011071ec"},{"id":"1-13","de":"ledig","forms":"–","en":"single (not married)","ex":"Ich bin ledig.","exEn":"I am single.","aw":"0d64e195782a","ae":"d2d0e03c4999"},{"id":"1-14","de":"verheiratet","forms":"–","en":"married","ex":"Sind Sie verheiratet?","exEn":"Are you married?","aw":"ca0b72686167","ae":"80ac433ed6dd"},{"id":"1-15","de":"die Gebühr","forms":"-en","en":"fee","ex":"Die Gebühr beträgt vierzig Franken.","exEn":"The fee is forty francs.","aw":"577ea3cd1b70","ae":"f7f17b5c8135"},{"id":"1-16","de":"der Schalter","forms":"-","en":"counter (service desk)","ex":"Gehen Sie bitte zu Schalter drei.","exEn":"Please go to counter three.","aw":"1d2033354e9d","ae":"4fa77def2ae7"},{"id":"1-17","de":"die Krankenkasse","forms":"-n","en":"health insurance (CH)","ex":"In der Schweiz braucht jede Person eine Krankenkasse.","exEn":"In Switzerland every person needs health insurance.","aw":"10102c412dbd","ae":"e591f930f1bd"},{"id":"1-18","de":"die Bestätigung","forms":"-en","en":"confirmation","ex":"Die Bestätigung bekommen Sie per Post.","exEn":"You will receive the confirmation by post.","aw":"85eb5036a01a","ae":"ba8cdaf581da"},{"id":"1-19","de":"zuständig","forms":"–","en":"responsible, in charge","ex":"Wer ist hier für die Anmeldung zuständig?","exEn":"Who is in charge of registration here?","aw":"a1f77cc52a15","ae":"4f170c4ebb13"}],"swiss":[{"ch":"Grüezi","std":"Guten Tag","en":"hello (formal greeting in German-speaking Switzerland)"},{"ch":"die Einwohnerkontrolle","std":"das Einwohnermeldeamt","en":"residents' registration office"},{"ch":"der Franken","std":"–","en":"Swiss franc (CHF)"}],"dialogue":{"title":"Am Schalter der Einwohnerkontrolle","intro":"Carla kommt aus Porto. Sie ist neu in Winterthur und meldet sich bei der Gemeinde an.","speakers":{"F":"Carla","M":"Herr Meier"},"lines":[{"s":"M","de":"Guten Tag. Was kann ich für Sie tun?","en":"Good day. What can I do for you?","audio":"6e1a0b2645b1"},{"s":"F","de":"Guten Tag. Ich möchte mich anmelden. Ich bin letzte Woche nach Winterthur umgezogen.","en":"Good day. I would like to register. I moved to Winterthur last week.","audio":"1ef4034acae3"},{"s":"M","de":"Herzlich willkommen! Woher sind Sie gekommen?","en":"Welcome! Where did you come from?","audio":"f93b6a747ced"},{"s":"F","de":"Aus Porto, in Portugal. Ich habe hier eine Stelle bei einer Logistikfirma gefunden.","en":"From Porto, in Portugal. I found a job at a logistics company here.","audio":"04e43ae3cadc"},{"s":"M","de":"Schön. Haben Sie Ihren Pass und den Mietvertrag mitgebracht?","en":"Nice. Did you bring your passport and the rental contract?","audio":"3ddef44c83c7"},{"s":"F","de":"Ja, hier sind beide. Den Arbeitsvertrag habe ich auch dabei.","en":"Yes, here are both. I have the employment contract with me too.","audio":"2d4ea5522949"},{"s":"M","de":"Sehr gut. Haben Sie das Formular schon ausgefüllt?","en":"Very good. Have you already filled in the form?","audio":"03da35cf77a3"},{"s":"F","de":"Ja, gestern Abend. Aber beim Familienstand war ich nicht sicher.","en":"Yes, yesterday evening. But I wasn't sure about the marital status.","audio":"47dd6a7c4d0d"},{"s":"M","de":"Sind Sie verheiratet?","en":"Are you married?","audio":"80ac433ed6dd"},{"s":"F","de":"Nein, ich bin ledig.","en":"No, I'm single.","audio":"c23459763ff9"},{"s":"M","de":"Dann schreiben Sie hier einfach „ledig\". Haben Sie schon eine Krankenkasse?","en":"Then simply write \"single\" here. Do you already have health insurance?","audio":"3c1790c2d82a"},{"s":"F","de":"Noch nicht. Ich habe mich aber schon im Internet informiert.","en":"Not yet. But I have already looked into it online.","audio":"8fd4d3326f25"},{"s":"M","de":"Sie müssen sich innerhalb von drei Monaten versichern. Das ist in der Schweiz Pflicht.","en":"You must get insured within three months. That's compulsory in Switzerland.","audio":"19d481709e9a"},{"s":"F","de":"Entschuldigung, können Sie das bitte wiederholen?","en":"Sorry, could you please repeat that?","audio":"15cfb9db0e00"},{"s":"M","de":"Natürlich. Die Krankenkasse ist Pflicht. Sie haben drei Monate Zeit.","en":"Of course. Health insurance is compulsory. You have three months.","audio":"76b0149449e6"},{"s":"F","de":"Alles klar, danke. Was kostet die Anmeldung?","en":"All right, thanks. What does registration cost?","audio":"1a23edcb6b23"},{"s":"M","de":"Die Gebühr beträgt vierzig Franken. Sie können bar oder mit Karte bezahlen.","en":"The fee is forty francs. You can pay in cash or by card.","audio":"e8c96d07e5f3"},{"s":"F","de":"Mit Karte, bitte. Vielen Dank für Ihre Hilfe!","en":"By card, please. Thank you very much for your help!","audio":"b4bfe3fa9301"},{"s":"M","de":"Gern geschehen. Einen schönen Tag noch!","en":"You're welcome. Have a nice day!","audio":"b8619718cb97"}],"questions":[{"type":"tf","q":"Carla ist vor einem Monat umgezogen.","a":false,"why":"Sie ist letzte Woche umgezogen.","qEn":"Carla moved a month ago.","whyEn":"She moved last week."},{"type":"tf","q":"Carla hat das Formular schon ausgefüllt.","a":true,"why":"Sie hat es gestern Abend ausgefüllt.","qEn":"Carla has already filled in the form.","whyEn":"She filled it in yesterday evening."},{"type":"mc","q":"Was hat Carla noch nicht?","options":["eine Wohnung","eine Krankenkasse","einen Pass"],"a":1,"qEn":"What doesn't Carla have yet?","optionsEn":["a flat","health insurance","a passport"]},{"type":"mc","q":"Wie viel Zeit hat Carla für die Krankenkasse?","options":["drei Wochen","drei Monate","ein Jahr"],"a":1,"qEn":"How much time does Carla have for the health insurance?","optionsEn":["three weeks","three months","one year"]},{"type":"mc","q":"Wie bezahlt Carla die Gebühr?","options":["bar","mit Karte","per Rechnung"],"a":1,"qEn":"How does Carla pay the fee?","optionsEn":["in cash","by card","by invoice"]}],"titleEn":"At the counter of the residents' office","introS":[["Carla kommt aus Porto.","Carla is from Porto.",0],["Sie ist neu in Winterthur und meldet sich bei der Gemeinde an.","She is new in Winterthur and is registering with the municipality.",0]]},"grammar":{"title":"Das Perfekt – haben oder sein?","summary":"Im Gespräch erzählt man Vergangenes meistens im Perfekt.","sections":[{"h":"So funktioniert das Perfekt","text":"Das Perfekt hat zwei Teile: **haben** oder **sein** (konjugiert, Position 2) und das **Partizip II** (am Satzende). Zusammen bilden sie eine Klammer.","examples":[{"de":"Ich ==habe== gestern ein Formular ==ausgefüllt==.","en":"I filled in a form yesterday.","audio":"a87fd155b659"},{"de":"Carla ==ist== nach Winterthur ==umgezogen==.","en":"Carla moved to Winterthur.","audio":"62f3e9b21b53"},{"de":"==Haben== Sie den Pass ==mitgebracht==?","en":"Did you bring the passport?","audio":"0b6fe0e5ccbb"}],"hEn":"How the perfect tense works","textP":[[["Das Perfekt hat zwei Teile: **haben** oder **sein** (konjugiert, Position 2) und das **Partizip II** (am Satzende).","The perfect tense has two parts: haben or sein (conjugated, position 2) and the past participle (at the end of the sentence).",0],["Zusammen bilden sie eine Klammer.","Together they form a bracket.",0]]]},{"h":"Das Partizip II bilden","text":"Kein **ge-** bei Verben mit untrennbarer Vorsilbe (**be-, ver-, er-, ent-, emp-, zer-, unter-**) und bei Verben auf **-ieren**.","table":[["Typ","Infinitiv","Partizip II"],["regelmässig","machen, kaufen, arbeiten","ge·mach·t, ge·kauf·t, ge·arbeit·et"],["unregelmässig","finden, schreiben, kommen","ge·fund·en, ge·schrieb·en, ge·komm·en"],["trennbar","ausfüllen, mitbringen, umziehen","aus·ge·füllt, mit·ge·bracht, um·ge·zogen"],["ohne ge-","bezahlen, verstehen, unterschreiben","bezahlt, verstanden, unterschrieben"],["auf -ieren","informieren, studieren","informiert, studiert"]],"hEn":"Forming the past participle","textP":[[["Kein **ge-** bei Verben mit untrennbarer Vorsilbe (**be-, ver-, er-, ent-, emp-, zer-, unter-**) und bei Verben auf **-ieren**.","No ge- with verbs that have an inseparable prefix (be-, ver-, er-, ent-, emp-, zer-, unter-) or with verbs ending in -ieren.",0]]]},{"h":"haben oder sein?","text":"Mit **sein**: Bewegung von A nach B (*gehen, fahren, fliegen, kommen, umziehen*), Veränderung des Zustands (*aufstehen, einschlafen, werden*) und die Verben *sein, bleiben, passieren*.\nMit **haben**: fast alle anderen Verben – auch alle reflexiven Verben (*ich habe mich angemeldet*).","examples":[{"de":"Wir ==sind== mit dem Zug nach Zürich ==gefahren==.","en":"We went to Zurich by train.","audio":"01919c922e69"},{"de":"Ich ==bin== um sechs Uhr ==aufgestanden==.","en":"I got up at six o'clock.","audio":"99b3d17a91e7"},{"de":"Er ==hat== sich gestern ==angemeldet==.","en":"He registered yesterday.","audio":"20dd86c0a835"}],"hEn":"haben or sein?","textP":[[["Mit **sein**: Bewegung von A nach B (*gehen, fahren, fliegen, kommen, umziehen*), Veränderung des Zustands (*aufstehen, einschlafen, werden*) und die Verben *sein, bleiben, passieren*.","With sein: movement from A to B (gehen, fahren, fliegen, kommen, umziehen), a change of state (aufstehen, einschlafen, werden) and the verbs sein, bleiben, passieren.",0],["Mit **haben**: fast alle anderen Verben – auch alle reflexiven Verben (*ich habe mich angemeldet*).","With haben: almost all other verbs – including all reflexive verbs (ich habe mich angemeldet).",1]]]},{"h":"Präteritum von sein und haben","text":"Bei **sein** und **haben** benutzt man auch im Gespräch fast immer das Präteritum: *Ich war beim Arzt. Ich hatte keine Zeit.*","table":[["Person","sein","haben"],["ich","war","hatte"],["du","warst","hattest"],["er/sie/es","war","hatte"],["wir","waren","hatten"],["ihr","wart","hattet"],["sie/Sie","waren","hatten"]],"hEn":"Simple past of sein and haben","textP":[[["Bei **sein** und **haben** benutzt man auch im Gespräch fast immer das Präteritum: *Ich war beim Arzt.*","With sein and haben, people almost always use the simple past, even in conversation: I was at the doctor's.",0],["*Ich hatte keine Zeit.*","I didn't have time.",0]]]}],"tip":"Achtung bei trennbaren Verben – das „ge\" steht in der Mitte: an·ge·meldet, aus·ge·füllt, um·ge·zogen.","titleEn":"The perfect tense – haben or sein?","summaryS":[["Im Gespräch erzählt man Vergangenes meistens im Perfekt.","In conversation, people usually talk about the past in the perfect tense.",0]],"tipP":[[["Achtung bei trennbaren Verben – das „ge\" steht in der Mitte: an·ge·meldet, aus·ge·füllt, um·ge·zogen.","Watch out with separable verbs – the \"ge\" goes in the middle: an·ge·meldet, aus·ge·füllt, um·ge·zogen.",0]]]},"exercises":[{"type":"choice","title":"haben oder sein?","items":[{"q":"Ich ___ letzte Woche umgezogen.","options":["bin","habe"],"a":0,"full":"Ich bin letzte Woche umgezogen.","audio":"ebd2098dd77e","en":"I moved last week."},{"q":"Wir ___ das Formular zusammen ausgefüllt.","options":["haben","sind"],"a":0,"full":"Wir haben das Formular zusammen ausgefüllt.","audio":"1c99bd6b3e73","en":"We filled in the form together."},{"q":"Carla ___ mit dem Zug nach Zürich gefahren.","options":["ist","hat"],"a":0,"full":"Carla ist mit dem Zug nach Zürich gefahren.","audio":"befa366478b2","en":"Carla went to Zurich by train."},{"q":"___ du dich schon angemeldet?","options":["Hast","Bist"],"a":0,"full":"Hast du dich schon angemeldet?","audio":"b1e909b1d0ee","en":"Have you registered yet?"},{"q":"Der Mann am Schalter ___ sehr freundlich gewesen.","options":["ist","hat"],"a":0,"full":"Der Mann am Schalter ist sehr freundlich gewesen.","audio":"2c31735803ed","en":"The man at the counter was very friendly."},{"q":"Wann ___ ihr heute aufgestanden?","options":["seid","habt"],"a":0,"full":"Wann seid ihr heute aufgestanden?","audio":"00de5388c47b","en":"When did you (all) get up today?"},{"q":"Ich ___ lange auf meinen Termin gewartet.","options":["habe","bin"],"a":0,"full":"Ich habe lange auf meinen Termin gewartet.","audio":"2dfe772feb9a","en":"I waited a long time for my appointment."},{"q":"Was ___ denn passiert?","options":["ist","hat"],"a":0,"full":"Was ist denn passiert?","audio":"58e3e67693cd","en":"What happened?"}],"titleEn":"haben or sein?"},{"type":"gap","title":"Partizip II – schreiben Sie die richtige Form","items":[{"q":"Hast du den Mietvertrag ___? (mitbringen)","a":["mitgebracht"],"full":"Hast du den Mietvertrag mitgebracht?","audio":"940936435ea8","en":"Did you bring the rental contract?"},{"q":"Ich habe das Formular schon ___. (ausfüllen)","a":["ausgefüllt"],"full":"Ich habe das Formular schon ausgefüllt.","audio":"b62e0d5ad448","en":"I've already filled in the form."},{"q":"Carla hat eine neue Stelle ___. (finden)","a":["gefunden"],"full":"Carla hat eine neue Stelle gefunden.","audio":"3d0adae044f3","en":"Carla has found a new job."},{"q":"Wir haben die Gebühr mit Karte ___. (bezahlen)","a":["bezahlt"],"full":"Wir haben die Gebühr mit Karte bezahlt.","audio":"8a0865461573","en":"We paid the fee by card."},{"q":"Haben Sie hier schon ___? (unterschreiben)","a":["unterschrieben"],"full":"Haben Sie hier schon unterschrieben?","audio":"862e8f5e6de7","en":"Have you already signed here?"},{"q":"Ich habe mich im Internet ___. (informieren)","a":["informiert"],"full":"Ich habe mich im Internet informiert.","audio":"4fe55ecbb194","en":"I looked into it online."},{"q":"Sie ist im August nach Winterthur ___. (umziehen)","a":["umgezogen"],"full":"Sie ist im August nach Winterthur umgezogen.","audio":"a6b024edf875","en":"She moved to Winterthur in August."},{"q":"Wir sind am Sonntag zu Hause ___. (bleiben)","a":["geblieben"],"full":"Wir sind am Sonntag zu Hause geblieben.","audio":"0a5d17dcde14","en":"We stayed at home on Sunday."}],"titleEn":"Past participle – write the correct form"},{"type":"order","title":"Bilden Sie Sätze","items":[{"a":["Ich habe mich gestern bei der Gemeinde angemeldet.","Gestern habe ich mich bei der Gemeinde angemeldet."],"tokens":["Ich","habe","mich","gestern","bei","der","Gemeinde","angemeldet."],"audio":"3e6dadf69250","en":"I registered with the municipality yesterday."},{"a":["Carla ist im September in die Schweiz gekommen.","Im September ist Carla in die Schweiz gekommen."],"tokens":["Carla","ist","im","September","in","die","Schweiz","gekommen."],"audio":"29668d2af0b6","en":"Carla came to Switzerland in September."},{"a":["Haben Sie das Formular schon unterschrieben?"],"tokens":["Haben","Sie","das","Formular","schon","unterschrieben?"],"audio":"0b30c748ef6a","en":"Have you signed the form yet?"},{"a":["Wir sind mit dem Bus zur Einwohnerkontrolle gefahren.","Mit dem Bus sind wir zur Einwohnerkontrolle gefahren."],"tokens":["Wir","sind","mit","dem","Bus","zur","Einwohnerkontrolle","gefahren."],"audio":"f7de7a2a2fd8","en":"We took the bus to the residents' office."},{"a":["Was hast du am Wochenende gemacht?"],"tokens":["Was","hast","du","am","Wochenende","gemacht?"],"audio":"3391533e2d04","en":"What did you do at the weekend?"}],"titleEn":"Make sentences"},{"type":"match","title":"Infinitiv und Partizip II","items":[{"l":"gehen","r":"gegangen"},{"l":"schreiben","r":"geschrieben"},{"l":"bringen","r":"gebracht"},{"l":"verstehen","r":"verstanden"},{"l":"anrufen","r":"angerufen"},{"l":"studieren","r":"studiert"},{"l":"fahren","r":"gefahren"},{"l":"bleiben","r":"geblieben"}],"titleEn":"Infinitive and past participle"},{"type":"dictation","title":"Diktat – hören und schreiben","items":[{"a":"Ich bin letzte Woche umgezogen.","audio":"9b1f2d312796","en":"I moved last week."},{"a":"Haben Sie Ihren Pass mitgebracht?","audio":"c610f6dcdfb0","en":"Did you bring your passport?"},{"a":"Wir haben das Formular zusammen ausgefüllt.","audio":"c31ce4c2c360","en":"We filled in the form together."},{"a":"Können Sie das bitte wiederholen?","audio":"73fd48a708ee","en":"Could you please repeat that?"}],"titleEn":"Dictation – listen and write"}],"reading":{"title":"Meine erste Woche in Winterthur","kind":"E-Mail","paras":[{"t":"Liebe Sofia","audio":"f247c2b3f1d1","s":[["Liebe Sofia","Dear Sofia",0]]},{"t":"Wie geht es dir? Ich bin jetzt schon eine Woche in Winterthur! Die ersten Tage waren sehr intensiv. Am Montag bin ich mit zwei grossen Koffern am Flughafen Zürich angekommen. Von dort bin ich mit dem Zug nach Winterthur gefahren – das hat nur zwanzig Minuten gedauert.","audio":"309c2134a32a","s":[["Wie geht es dir?","How are you?",0],["Ich bin jetzt schon eine Woche in Winterthur!","I've already been in Winterthur for a week!",0],["Die ersten Tage waren sehr intensiv.","The first few days were very intense.",0],["Am Montag bin ich mit zwei grossen Koffern am Flughafen Zürich angekommen.","On Monday I arrived at Zurich Airport with two big suitcases.",0],["Von dort bin ich mit dem Zug nach Winterthur gefahren – das hat nur zwanzig Minuten gedauert.","From there I took the train to Winterthur – it only took twenty minutes.",0]]},{"t":"Meine Wohnung ist klein, aber hell und ruhig. Am Dienstag habe ich ein Bett und einen Tisch gekauft, und am Mittwoch hat mir ein Kollege beim Aufbauen geholfen.","audio":"3c71e8e7e277","s":[["Meine Wohnung ist klein, aber hell und ruhig.","My flat is small, but bright and quiet.",0],["Am Dienstag habe ich ein Bett und einen Tisch gekauft, und am Mittwoch hat mir ein Kollege beim Aufbauen geholfen.","On Tuesday I bought a bed and a table, and on Wednesday a colleague helped me put them together.",0]]},{"t":"Gestern war ich bei der Einwohnerkontrolle. Ich habe mich angemeldet und viele Fragen beantwortet. Der Mann am Schalter hat langsam gesprochen, deshalb habe ich fast alles verstanden. Jetzt muss ich noch eine Krankenkasse suchen – das ist hier Pflicht.","audio":"4a7f1b20c66c","s":[["Gestern war ich bei der Einwohnerkontrolle.","Yesterday I was at the residents' office.",0],["Ich habe mich angemeldet und viele Fragen beantwortet.","I registered and answered a lot of questions.",0],["Der Mann am Schalter hat langsam gesprochen, deshalb habe ich fast alles verstanden.","The man at the counter spoke slowly, so I understood almost everything.",0],["Jetzt muss ich noch eine Krankenkasse suchen – das ist hier Pflicht.","Now I still have to find health insurance – it's compulsory here.",0]]},{"t":"Am Samstag habe ich die Altstadt besucht. Es hat geregnet, aber ich habe ein schönes Café gefunden und dort einen Kuchen gegessen. Die Leute sind sehr freundlich. Manchmal sprechen sie Schweizerdeutsch, und dann verstehe ich fast nichts! Zum Glück sprechen alle auch Hochdeutsch, wenn ich frage.","audio":"8c95bd446902","s":[["Am Samstag habe ich die Altstadt besucht.","On Saturday I visited the old town.",0],["Es hat geregnet, aber ich habe ein schönes Café gefunden und dort einen Kuchen gegessen.","It was raining, but I found a nice café and had a piece of cake there.",0],["Die Leute sind sehr freundlich.","People are very friendly.",0],["Manchmal sprechen sie Schweizerdeutsch, und dann verstehe ich fast nichts!","Sometimes they speak Swiss German, and then I understand almost nothing!",0],["Zum Glück sprechen alle auch Hochdeutsch, wenn ich frage.","Luckily everyone also speaks Standard German when I ask.",0]]},{"t":"Wann besuchst du mich? Ich habe jetzt ein Sofa für Gäste!","audio":"7e17cc7c4171","s":[["Wann besuchst du mich?","When are you coming to visit me?",0],["Ich habe jetzt ein Sofa für Gäste!","I now have a sofa for guests!",0]]},{"t":"Liebe Grüsse\nCarla","audio":"dc1f336eeb07","s":[["Liebe Grüsse","Love",0],["Carla","Carla",1]]}],"glossary":[{"de":"intensiv","en":"intense"},{"de":"der Koffer","en":"suitcase"},{"de":"ankommen (ist angekommen)","en":"to arrive"},{"de":"aufbauen","en":"to assemble, set up"},{"de":"deshalb","en":"that's why, therefore"},{"de":"zum Glück","en":"luckily"}],"questions":[{"type":"tf","q":"Carla ist mit dem Zug vom Flughafen nach Winterthur gefahren.","a":true,"why":"","qEn":"Carla took the train from the airport to Winterthur."},{"type":"tf","q":"Carla hat die Möbel allein aufgebaut.","a":false,"why":"Ein Kollege hat ihr geholfen.","qEn":"Carla assembled the furniture on her own.","whyEn":"A colleague helped her."},{"type":"mc","q":"Warum hat Carla am Schalter fast alles verstanden?","options":["Der Mann hat Englisch gesprochen.","Der Mann hat langsam gesprochen.","Sie hat ein Wörterbuch benutzt."],"a":1,"qEn":"Why did Carla understand almost everything at the counter?","optionsEn":["The man spoke English.","The man spoke slowly.","She used a dictionary."]},{"type":"mc","q":"Was hat Carla am Samstag gemacht?","options":["Sie hat die Altstadt besucht.","Sie ist nach Zürich gefahren.","Sie hat Möbel gekauft."],"a":0,"qEn":"What did Carla do on Saturday?","optionsEn":["She visited the old town.","She went to Zurich.","She bought furniture."]},{"type":"tf","q":"Carla versteht Schweizerdeutsch gut.","a":false,"why":"Sie versteht fast nichts.","qEn":"Carla understands Swiss German well.","whyEn":"She understands almost nothing."}],"titleEn":"My first week in Winterthur"},"writing":{"task":"Sie sind neu in Ihrer Gemeinde. Schreiben Sie eine E-Mail an eine Freundin oder einen Freund (60–80 Wörter).","points":["Wann sind Sie umgezogen?","Was haben Sie in der ersten Woche gemacht?","Was war schwierig?","Laden Sie die Person zu sich ein."],"phrases":[{"de":"Ich bin am … nach … umgezogen.","en":"I moved to … on …"},{"de":"In der ersten Woche habe ich …","en":"In the first week I …"},{"de":"Schwierig war …","en":"What was difficult was …"},{"de":"Hast du Lust, mich zu besuchen?","en":"Would you like to visit me?"}],"model":"Lieber Marco\n\nIch bin am 1. September nach Winterthur umgezogen. In der ersten Woche habe ich viele Dinge gemacht: Ich habe mich bei der Gemeinde angemeldet, ein Bankkonto eröffnet und Möbel gekauft. Schwierig war das Schweizerdeutsch – ich habe am Anfang fast nichts verstanden! Aber die Leute sind sehr hilfsbereit. Hast du im Oktober Zeit? Dann kannst du mich gerne besuchen. Ich zeige dir die Altstadt.\n\nViele Grüsse\nCarla","audio":"ddeca5156e7a","taskS":[["Sie sind neu in Ihrer Gemeinde.","You are new in your municipality.",0],["Schreiben Sie eine E-Mail an eine Freundin oder einen Freund (60–80 Wörter).","Write an email to a friend (60–80 words).",0]],"pointsEn":["When did you move?","What did you do in the first week?","What was difficult?","Invite the person to your place."],"modelP":[[["Lieber Marco","Dear Marco",0]],[["Ich bin am 1. September nach Winterthur umgezogen.","I moved to Winterthur on 1 September.",0],["In der ersten Woche habe ich viele Dinge gemacht: Ich habe mich bei der Gemeinde angemeldet, ein Bankkonto eröffnet und Möbel gekauft.","In the first week I did lots of things: I registered with the municipality, opened a bank account and bought furniture.",0],["Schwierig war das Schweizerdeutsch – ich habe am Anfang fast nichts verstanden!","The difficult thing was Swiss German – at first I understood almost nothing!",0],["Aber die Leute sind sehr hilfsbereit.","But people are very helpful.",0],["Hast du im Oktober Zeit?","Are you free in October?",0],["Dann kannst du mich gerne besuchen.","Then you're welcome to come and visit me.",0],["Ich zeige dir die Altstadt.","I'll show you the old town.",0]],[["Viele Grüsse","Best wishes",0],["Carla","Carla",1]]]},"speaking":{"task":"Am Schalter – beantworten Sie die Fragen zu Ihrer Person. Hören Sie die Frage, antworten Sie laut und vergleichen Sie dann mit dem Beispiel.","phrases":[{"de":"Ich möchte mich anmelden.","en":"I would like to register.","audio":"f33b14644810"},{"de":"Können Sie das bitte wiederholen?","en":"Could you please repeat that?","audio":"c11a494c5657"},{"de":"Können Sie bitte etwas langsamer sprechen?","en":"Could you speak a bit more slowly, please?","audio":"db67013c9fe3"},{"de":"Wie schreibt man das?","en":"How do you spell that?","audio":"e8dc9ea3c6fd"},{"de":"Was muss ich hier eintragen?","en":"What do I have to enter here?","audio":"2085797cfba3"}],"prompts":[{"q":"Wie ist Ihr Name, und woher kommen Sie?","model":"Mein Name ist Carla Ferreira. Ich komme aus Porto, in Portugal.","aq":"a1872c7a06fe","am":"ae2c7968d682","qS":[["Wie ist Ihr Name, und woher kommen Sie?","What's your name, and where are you from?",0]],"modelS":[["Mein Name ist Carla Ferreira.","My name is Carla Ferreira.",0],["Ich komme aus Porto, in Portugal.","I'm from Porto, in Portugal.",0]]},{"q":"Seit wann wohnen Sie in der Schweiz?","model":"Ich wohne seit einer Woche in der Schweiz. Ich bin am ersten September angekommen.","aq":"ab47649be334","am":"e98153c3ab76","qS":[["Seit wann wohnen Sie in der Schweiz?","How long have you been living in Switzerland?",0]],"modelS":[["Ich wohne seit einer Woche in der Schweiz.","I've been living in Switzerland for a week.",0],["Ich bin am ersten September angekommen.","I arrived on the first of September.",0]]},{"q":"Warum sind Sie in die Schweiz gekommen?","model":"Ich habe hier eine Stelle gefunden. Ich arbeite bei einer Logistikfirma.","aq":"20b0aea8af63","am":"78a4b2f6172c","qS":[["Warum sind Sie in die Schweiz gekommen?","Why did you come to Switzerland?",0]],"modelS":[["Ich habe hier eine Stelle gefunden.","I found a job here.",0],["Ich arbeite bei einer Logistikfirma.","I work for a logistics company.",0]]},{"q":"Was haben Sie letztes Wochenende gemacht?","model":"Am Samstag habe ich die Altstadt besucht, und am Sonntag bin ich zu Hause geblieben und habe gekocht.","aq":"3ef6f922468a","am":"7c6aafe8cee9","qS":[["Was haben Sie letztes Wochenende gemacht?","What did you do last weekend?",0]],"modelS":[["Am Samstag habe ich die Altstadt besucht, und am Sonntag bin ich zu Hause geblieben und habe gekocht.","On Saturday I visited the old town, and on Sunday I stayed at home and cooked.",0]]}],"taskS":[["Am Schalter – beantworten Sie die Fragen zu Ihrer Person.","At the counter – answer the questions about yourself.",0],["Hören Sie die Frage, antworten Sie laut und vergleichen Sie dann mit dem Beispiel.","Listen to the question, answer out loud and then compare with the example.",0]]},"en":{"title":"New in the municipality","subtitle":"Registering at the residents' registration office","focus":"Perfect tense with haben and sein"}},{"id":2,"title":"Eine Wohnung finden","subtitle":"Inserate lesen, eine Wohnung besichtigen","level":"A2","theme":"Wohnen","focus":"Nebensätze mit weil, dass und wenn","goals":[{"de":"Ich kann Wohnungsinserate verstehen und vergleichen.","en":"I can understand and compare flat adverts."},{"de":"Ich kann bei einer Besichtigung Fragen stellen und sagen, was ich suche.","en":"I can ask questions at a viewing and say what I'm looking for."},{"de":"Ich kann Gründe nennen und meine Meinung sagen (weil, dass, wenn).","en":"I can give reasons and say my opinion."}],"vocab":[{"id":"2-0","de":"die Wohnungsbesichtigung","forms":"-en","en":"flat viewing","ex":"Die Besichtigung ist am Samstag um zehn Uhr.","exEn":"The viewing is on Saturday at ten.","aw":"8e14bd9fdfcc","ae":"31e3b3aaf1e6"},{"id":"2-1","de":"das Inserat","forms":"-e","en":"advert (CH)","ex":"Ich habe das Inserat im Internet gesehen.","exEn":"I saw the advert online.","aw":"2b672ce196cf","ae":"2e97e3e5787e"},{"id":"2-2","de":"der Mietzins","forms":"-e","en":"rent (CH)","ex":"Der Mietzins ist für Winterthur ziemlich hoch.","exEn":"The rent is quite high for Winterthur.","aw":"6b0348398869","ae":"95387468c7ff"},{"id":"2-3","de":"die Nebenkosten","forms":"(Pl.)","en":"additional costs (heating, water …)","ex":"Sind die Nebenkosten inklusive?","exEn":"Are the additional costs included?","aw":"c3f50ceb66be","ae":"2019256b3748"},{"id":"2-4","de":"das Mietzinsdepot","forms":"-s","en":"rental deposit (CH)","ex":"Das Mietzinsdepot beträgt drei Monatsmieten.","exEn":"The deposit is three months' rent.","aw":"ae46aa695a5f","ae":"fa6be65cb736"},{"id":"2-5","de":"der Vermieter","forms":"-","en":"landlord","ex":"Der Vermieter wohnt im gleichen Haus.","exEn":"The landlord lives in the same building.","aw":"85715249fa57","ae":"8647174b98e6"},{"id":"2-6","de":"die Verwaltung","forms":"-en","en":"property management","ex":"Die Verwaltung hat mir heute geantwortet.","exEn":"The management company replied to me today.","aw":"bd3b64f5077b","ae":"17fb90ea315f"},{"id":"2-7","de":"der Stock","forms":"Stockwerke","en":"floor, storey","ex":"Die Wohnung liegt im dritten Stock.","exEn":"The flat is on the third floor.","aw":"59729ec053bc","ae":"3572d4594bf9"},{"id":"2-8","de":"das Erdgeschoss","forms":"-e","en":"ground floor","ex":"Im Erdgeschoss gibt es einen kleinen Garten.","exEn":"There is a small garden on the ground floor.","aw":"42e907b730be","ae":"c832b6cf9355"},{"id":"2-9","de":"einziehen","forms":"ist eingezogen","en":"to move in","ex":"Wann können wir einziehen?","exEn":"When can we move in?","aw":"ac8475c58156","ae":"3a36fc28a9e0"},{"id":"2-10","de":"ausziehen","forms":"ist ausgezogen","en":"to move out","ex":"Die alte Mieterin ist schon ausgezogen.","exEn":"The previous tenant has already moved out.","aw":"6f3860cb99d3","ae":"6d4a4c991f47"},{"id":"2-11","de":"kündigen","forms":"hat gekündigt","en":"to give notice, to cancel","ex":"Ich muss meine alte Wohnung kündigen.","exEn":"I have to give notice on my old flat.","aw":"82f6c2f53392","ae":"f84fb7d25cf2"},{"id":"2-12","de":"hell","forms":"–","en":"bright, light","ex":"Das Wohnzimmer ist schön hell.","exEn":"The living room is nice and bright.","aw":"49ad11070ae3","ae":"b45af26823e6"},{"id":"2-13","de":"ruhig","forms":"–","en":"quiet","ex":"Die Strasse ist sehr ruhig.","exEn":"The street is very quiet.","aw":"30eac6205130","ae":"52e6b18ab995"},{"id":"2-14","de":"zentral","forms":"–","en":"central","ex":"Die Wohnung liegt zentral, nahe beim Bahnhof.","exEn":"The flat is central, close to the station.","aw":"6edad344aaf1","ae":"dddbdc229256"},{"id":"2-15","de":"möbliert","forms":"–","en":"furnished","ex":"Ich suche eine möblierte Wohnung.","exEn":"I'm looking for a furnished flat.","aw":"352d3c02ece6","ae":"b730e4c6a684"},{"id":"2-16","de":"sich bewerben","forms":"hat sich beworben","en":"to apply","ex":"Ich möchte mich für die Wohnung bewerben.","exEn":"I would like to apply for the flat.","aw":"ecc17dee709a","ae":"9a9a6c75c1ae"},{"id":"2-17","de":"der Betreibungsregisterauszug","forms":"-auszüge","en":"debt register extract (CH)","ex":"Für die Bewerbung brauchen Sie einen Betreibungsregisterauszug.","exEn":"For the application you need a debt register extract.","aw":"46a0a1e29b37","ae":"f37d1a64885e"},{"id":"2-18","de":"das Haustier","forms":"-e","en":"pet","ex":"Sind Haustiere erlaubt?","exEn":"Are pets allowed?","aw":"9633066d9479","ae":"9e00a7b320dc"},{"id":"2-19","de":"erlaubt","forms":"–","en":"allowed","ex":"Rauchen ist in der Wohnung nicht erlaubt.","exEn":"Smoking is not allowed in the flat.","aw":"277a36c10a81","ae":"267f554ed83a"}],"swiss":[{"ch":"das Inserat","std":"die Anzeige","en":"advert"},{"ch":"der Mietzins","std":"die Miete","en":"rent"},{"ch":"das Mietzinsdepot","std":"die Kaution","en":"rental deposit"},{"ch":"die 3½-Zimmer-Wohnung","std":"–","en":"Swiss room count; the ½ usually stands for a large eat-in kitchen or hall"},{"ch":"der Betreibungsregisterauszug","std":"–","en":"proof that you have no unpaid debts; landlords almost always ask for it"}],"dialogue":{"title":"Bei der Wohnungsbesichtigung","intro":"Carla besichtigt eine Wohnung in Winterthur-Veltheim. Herr Baumann von der Verwaltung zeigt ihr die Wohnung.","speakers":{"F":"Carla","M":"Herr Baumann"},"lines":[{"s":"M","de":"Guten Tag, Sie sind sicher Frau Ferreira. Kommen Sie herein.","en":"Hello, you must be Ms Ferreira. Come in.","audio":"30f9ff51f7e2"},{"s":"F","de":"Guten Tag. Danke, dass ich die Wohnung heute anschauen kann.","en":"Hello. Thank you for letting me see the flat today.","audio":"03253065e6b0"},{"s":"M","de":"Gern. Das ist eine 3½-Zimmer-Wohnung im dritten Stock. Sie ist sehr hell, wie Sie sehen.","en":"You're welcome. This is a 3.5-room flat on the third floor. It's very bright, as you can see.","audio":"f36ace0b59bb"},{"s":"F","de":"Ja, wirklich schön. Ich suche eine grössere Wohnung, weil meine jetzige Wohnung nur ein Zimmer hat.","en":"Yes, really nice. I'm looking for a bigger flat because my current flat only has one room.","audio":"8f9a1bb8d626"},{"s":"M","de":"Verstehe. Wohnen Sie allein?","en":"I see. Do you live alone?","audio":"ea8647f5b5aa"},{"s":"F","de":"Im Moment schon. Aber ich hoffe, dass mein Freund im Frühling auch in die Schweiz kommt.","en":"At the moment, yes. But I hope that my boyfriend will come to Switzerland in the spring too.","audio":"35b0c8eae8fe"},{"s":"M","de":"Die Küche ist ganz neu, und hier ist der Balkon.","en":"The kitchen is brand new, and here is the balcony.","audio":"bffb85d3b0d5"},{"s":"F","de":"Toll! Wie hoch ist der Mietzins?","en":"Great! How high is the rent?","audio":"1fed783b30f5"},{"s":"M","de":"Achtzehnhundertfünfzig Franken, plus zweihundertzwanzig Franken Nebenkosten.","en":"One thousand eight hundred and fifty francs, plus two hundred and twenty francs additional costs.","audio":"4b1e13c413db"},{"s":"F","de":"Das ist nicht wenig. Muss man auch ein Mietzinsdepot bezahlen?","en":"That's not cheap. Do you also have to pay a deposit?","audio":"d47318527e78"},{"s":"M","de":"Ja, drei Monatsmieten. Das ist in der Schweiz normal.","en":"Yes, three months' rent. That's normal in Switzerland.","audio":"4bc4a780ae1a"},{"s":"F","de":"Und sind Haustiere erlaubt? Ich habe eine Katze.","en":"And are pets allowed? I have a cat.","audio":"26807625adad"},{"s":"M","de":"Eine Katze ist kein Problem. Für einen Hund braucht man aber eine Erlaubnis.","en":"A cat is no problem. For a dog, however, you need permission.","audio":"afd2523045ce"},{"s":"F","de":"Perfekt. Was muss ich machen, wenn ich mich bewerben möchte?","en":"Perfect. What do I have to do if I want to apply?","audio":"fd6212beed09"},{"s":"M","de":"Sie füllen das Anmeldeformular aus und schicken uns einen Betreibungsregisterauszug.","en":"You fill in the application form and send us a debt register extract.","audio":"aa3725bb57f4"},{"s":"F","de":"Einen Betreibungs… Entschuldigung, was ist das?","en":"A debt… Sorry, what is that?","audio":"1dd853e03a88"},{"s":"M","de":"Das Dokument zeigt, dass Sie keine Schulden haben. Sie können es online bestellen.","en":"The document shows that you have no debts. You can order it online.","audio":"52d5600f211a"},{"s":"F","de":"Ah, verstehe. Dann schicke ich Ihnen alles bis Montag.","en":"Ah, I see. Then I'll send you everything by Monday.","audio":"41a8be06cb7d"},{"s":"M","de":"Sehr gut. Wenn Sie noch Fragen haben, rufen Sie mich einfach an.","en":"Very good. If you have any more questions, just call me.","audio":"a35e74520798"}],"questions":[{"type":"tf","q":"Die Wohnung liegt im dritten Stock.","a":true,"why":"","qEn":"The flat is on the third floor."},{"type":"mc","q":"Warum sucht Carla eine neue Wohnung?","options":["Ihre Wohnung ist zu teuer.","Ihre Wohnung hat nur ein Zimmer.","Sie hat Probleme mit den Nachbarn."],"a":1,"qEn":"Why is Carla looking for a new flat?","optionsEn":["Her flat is too expensive.","Her flat has only one room.","She has problems with the neighbours."]},{"type":"tf","q":"Die Nebenkosten sind im Mietzins inklusive.","a":false,"why":"Man bezahlt 220 Franken extra.","qEn":"The additional costs are included in the rent.","whyEn":"You pay 220 francs extra."},{"type":"mc","q":"Was sagt Herr Baumann über Haustiere?","options":["Alle Haustiere sind verboten.","Eine Katze ist kein Problem.","Hunde sind kein Problem."],"a":1,"qEn":"What does Mr Baumann say about pets?","optionsEn":["All pets are forbidden.","A cat is no problem.","Dogs are no problem."]},{"type":"mc","q":"Was zeigt der Betreibungsregisterauszug?","options":["dass man keine Schulden hat","wie viel man verdient","wo man früher gewohnt hat"],"a":0,"qEn":"What does the debt register extract show?","optionsEn":["that you have no debts","how much you earn","where you used to live"]}],"titleEn":"At the flat viewing","introS":[["Carla besichtigt eine Wohnung in Winterthur-Veltheim.","Carla is viewing a flat in Winterthur-Veltheim.",0],["Herr Baumann von der Verwaltung zeigt ihr die Wohnung.","Mr Baumann from the property management company shows her the flat.",0]]},"grammar":{"title":"Nebensätze mit weil, dass und wenn","summary":"Im Nebensatz steht das konjugierte Verb am Ende.","sections":[{"h":"Das Verb geht ans Ende","text":"Nach **weil**, **dass** und **wenn** beginnt ein Nebensatz. Das konjugierte Verb steht dort ganz am **Ende**. Vor dem Nebensatz steht ein Komma.","examples":[{"de":"Meine Wohnung ==ist== zu klein. → Ich suche eine Wohnung, weil meine Wohnung zu klein ==ist==.","en":"My flat is too small. → I'm looking for a flat because my flat is too small.","audio":"2557eb90028f"},{"de":"Die Wohnung ==ist== noch frei. → Ich hoffe, dass die Wohnung noch frei ==ist==.","en":"I hope that the flat is still available.","audio":"7f9a4f37da2a"},{"de":"Sie ==haben== Fragen. → Wenn Sie Fragen ==haben==, rufen Sie mich an.","en":"If you have questions, call me.","audio":"5eed6c82df96"}],"hEn":"The verb goes to the end","textP":[[["Nach **weil**, **dass** und **wenn** beginnt ein Nebensatz.","A subordinate clause begins after weil, dass and wenn.",0],["Das konjugierte Verb steht dort ganz am **Ende**.","There the conjugated verb goes right at the end.",0],["Vor dem Nebensatz steht ein Komma.","A comma comes before the subordinate clause.",0]]]},{"h":"Wann benutze ich was?","table":[["Konnektor","Funktion","Beispiel"],["weil","Grund (Warum?)","…, weil die Wohnung zentral ist."],["dass","Inhalt nach sagen, denken, hoffen, wissen, finden …","Ich finde, dass die Miete zu hoch ist."],["wenn","Bedingung oder Zeit (immer wenn)","Wenn es regnet, nehme ich den Bus."]],"hEn":"When do I use which?"},{"h":"Nebensatz zuerst – Verb, Verb","text":"Steht der Nebensatz am Anfang, kommt im Hauptsatz **sofort das Verb**. So stehen zwei Verben direkt nebeneinander, getrennt durch ein Komma.","examples":[{"de":"Wenn die Wohnung frei ==ist==, ==ziehe== ich im Mai ein.","en":"If the flat is available, I'll move in in May.","audio":"985c54871a73"},{"de":"Weil sie zentral ==liegt==, ==ist== die Wohnung teuer.","en":"Because it's central, the flat is expensive.","audio":"c73955d14e70"}],"hEn":"Subordinate clause first – verb, verb","textP":[[["Steht der Nebensatz am Anfang, kommt im Hauptsatz **sofort das Verb**.","If the subordinate clause comes first, the verb of the main clause follows immediately.",0],["So stehen zwei Verben direkt nebeneinander, getrennt durch ein Komma.","So two verbs stand right next to each other, separated by a comma.",0]]]},{"h":"Modalverben, Perfekt und trennbare Verben","text":"Auch hier steht das **konjugierte** Verb am Ende. Trennbare Verben sind im Nebensatz wieder zusammen.","examples":[{"de":"Ich rufe an, weil ich die Wohnung besichtigen ==möchte==.","en":"I'm calling because I'd like to view the flat.","audio":"99fc3306eacb"},{"de":"Sie sagt, dass sie schon ausgezogen ==ist==.","en":"She says that she has already moved out.","audio":"7167b26c5ad5"},{"de":"Ich weiss nicht, wann er ==einzieht==.","en":"I don't know when he's moving in.","audio":"ea06221f9bdc"}],"hEn":"Modal verbs, perfect tense and separable verbs","textP":[[["Auch hier steht das **konjugierte** Verb am Ende.","Here too, the conjugated verb goes at the end.",0],["Trennbare Verben sind im Nebensatz wieder zusammen.","Separable verbs join back together in the subordinate clause.",0]]]}],"tip":"weil oder denn? Beide nennen einen Grund. Nach „denn\" bleibt die normale Wortstellung (Verb auf Position 2). Ich suche eine Wohnung, denn meine Wohnung ist zu klein.","titleEn":"Subordinate clauses with weil, dass and wenn","summaryS":[["Im Nebensatz steht das konjugierte Verb am Ende.","In a subordinate clause the conjugated verb goes at the end.",0]],"tipP":[[["weil oder denn?","weil or denn?",0],["Beide nennen einen Grund.","Both give a reason.",0],["Nach „denn\" bleibt die normale Wortstellung (Verb auf Position 2).","After \"denn\" the normal word order stays (verb in position 2).",0],["Ich suche eine Wohnung, denn meine Wohnung ist zu klein.","I'm looking for a flat, because my flat is too small.",0]]]},"exercises":[{"type":"choice","title":"weil, dass oder wenn?","items":[{"q":"Ich hoffe, ___ die Wohnung noch frei ist.","options":["dass","weil","wenn"],"a":0,"full":"Ich hoffe, dass die Wohnung noch frei ist.","audio":"8fab7c82a6e5","en":"I hope that the flat is still available."},{"q":"Carla sucht eine neue Wohnung, ___ ihre Wohnung zu klein ist.","options":["weil","dass","wenn"],"a":0,"full":"Carla sucht eine neue Wohnung, weil ihre Wohnung zu klein ist.","audio":"2e63f9c91598","en":"Carla is looking for a new flat because her flat is too small."},{"q":"___ Sie Fragen haben, rufen Sie mich an.","options":["Wenn","Dass","Weil"],"a":0,"full":"Wenn Sie Fragen haben, rufen Sie mich an.","audio":"0d80e35ac311","en":"If you have any questions, call me."},{"q":"Der Vermieter sagt, ___ Katzen erlaubt sind.","options":["dass","wenn","weil"],"a":0,"full":"Der Vermieter sagt, dass Katzen erlaubt sind.","audio":"a2f52be7e43b","en":"The landlord says that cats are allowed."},{"q":"Wir nehmen die Wohnung, ___ sie zentral und ruhig ist.","options":["weil","dass","wenn"],"a":0,"full":"Wir nehmen die Wohnung, weil sie zentral und ruhig ist.","audio":"b0e001bb3902","en":"We're taking the flat because it's central and quiet."},{"q":"___ es regnet, fahre ich mit dem Bus zur Arbeit.","options":["Wenn","Weil","Dass"],"a":0,"full":"Wenn es regnet, fahre ich mit dem Bus zur Arbeit.","audio":"008324f0e669","en":"When it rains, I take the bus to work."},{"q":"Es ist wichtig, ___ Sie den Mietvertrag genau lesen.","options":["dass","wenn","weil"],"a":0,"full":"Es ist wichtig, dass Sie den Mietvertrag genau lesen.","audio":"a294eb802bb8","en":"It's important that you read the rental contract carefully."},{"q":"Ich kann nicht zur Besichtigung kommen, ___ ich arbeiten muss.","options":["weil","dass","wenn"],"a":0,"full":"Ich kann nicht zur Besichtigung kommen, weil ich arbeiten muss.","audio":"bec632a0a818","en":"I can't come to the viewing because I have to work."}],"titleEn":"weil, dass or wenn?"},{"type":"gap","title":"Wo steht das Verb? Schreiben Sie die richtige Form.","items":[{"q":"Ich nehme die Wohnung, weil sie sehr hell ___. (sein)","a":["ist"],"full":"Ich nehme die Wohnung, weil sie sehr hell ist.","audio":"21dbbfc716f1","en":"I'm taking the flat because it's very bright."},{"q":"Ich hoffe, dass der Vermieter mich bald ___. (anrufen)","a":["anruft"],"full":"Ich hoffe, dass der Vermieter mich bald anruft.","audio":"7f850d9e65f3","en":"I hope the landlord calls me soon."},{"q":"Wenn du Zeit ___, komm doch zur Besichtigung mit. (haben)","a":["hast"],"full":"Wenn du Zeit hast, komm doch zur Besichtigung mit.","audio":"41a22e375e5b","en":"If you have time, come along to the viewing."},{"q":"Sie sagt, dass sie im Juni ___. (einziehen)","a":["einzieht"],"full":"Sie sagt, dass sie im Juni einzieht.","audio":"001eb1f161bc","en":"She says she's moving in in June."},{"q":"Ich bin müde, weil ich den ganzen Tag Kisten getragen ___. (haben)","a":["habe"],"full":"Ich bin müde, weil ich den ganzen Tag Kisten getragen habe.","audio":"15c541696e9c","en":"I'm tired because I carried boxes all day."},{"q":"Weisst du, dass man hier keine Hunde halten ___? (dürfen)","a":["darf"],"full":"Weisst du, dass man hier keine Hunde halten darf?","audio":"0fa599dda64b","en":"Do you know that you're not allowed to keep dogs here?"}],"titleEn":"Where does the verb go? Write the correct form."},{"type":"order","title":"Bilden Sie Sätze","items":[{"a":["Ich suche eine Wohnung, weil ich mehr Platz brauche."],"tokens":["Ich","suche","eine","Wohnung,","weil","ich","mehr","Platz","brauche."],"audio":"6c9ede104ead","en":"I'm looking for a flat because I need more space."},{"a":["Ich glaube, dass die Nebenkosten zu hoch sind."],"tokens":["Ich","glaube,","dass","die","Nebenkosten","zu","hoch","sind."],"audio":"946b3ba84fb0","en":"I think the additional costs are too high."},{"a":["Wenn die Wohnung frei ist, ziehe ich im Mai ein.","Ich ziehe im Mai ein, wenn die Wohnung frei ist."],"tokens":["Wenn","die","Wohnung","frei","ist,","ziehe","ich","im","Mai","ein."],"audio":"985c54871a73","en":"If the flat is available, I'll move in in May."},{"a":["Er sagt, dass Haustiere nicht erlaubt sind."],"tokens":["Er","sagt,","dass","Haustiere","nicht","erlaubt","sind."],"audio":"b77746571009","en":"He says that pets are not allowed."},{"a":["Weil die Wohnung zentral liegt, ist sie teuer."],"tokens":["Weil","die","Wohnung","zentral","liegt,","ist","sie","teuer."],"audio":"587134f85a4f","en":"Because the flat is central, it's expensive."}],"titleEn":"Make sentences"},{"type":"match","title":"Was passt zusammen?","items":[{"l":"Ich rufe die Verwaltung an,","r":"weil die Heizung nicht funktioniert."},{"l":"Wenn du einen Hund hast,","r":"brauchst du eine Erlaubnis."},{"l":"Ich finde es super,","r":"dass die Wohnung einen Balkon hat."},{"l":"Wir suchen eine grössere Wohnung,","r":"weil wir ein Baby bekommen."},{"l":"Wenn die Wohnung möbliert ist,","r":"musst du keine Möbel kaufen."}],"titleEn":"What goes together?"},{"type":"dictation","title":"Diktat – hören und schreiben","items":[{"a":"Ich suche eine Wohnung, weil meine Wohnung zu klein ist.","audio":"2c568c189d28","en":"I'm looking for a flat because my flat is too small."},{"a":"Sind Haustiere in dieser Wohnung erlaubt?","audio":"3a43e9241945","en":"Are pets allowed in this flat?"},{"a":"Wenn Sie Fragen haben, rufen Sie mich an.","audio":"56a581e22a88","en":"If you have any questions, call me."},{"a":"Ich hoffe, dass ich die Wohnung bekomme.","audio":"dedceb9da1ce","en":"I hope I get the flat."}],"titleEn":"Dictation – listen and write"}],"reading":{"title":"Drei Wohnungsinserate","kind":"Inserate","paras":[{"t":"**A – Winterthur-Veltheim**\nSchöne 3½-Zimmer-Wohnung im 2. Stock, 78 m², sonniger Balkon mit Blick ins Grüne. Neue Küche, eigene Waschmaschine und Tumbler. 5 Minuten zur Bushaltestelle. Mietzins CHF 1850.– plus CHF 220.– Nebenkosten. Haustiere auf Anfrage. Frei ab 1. Dezember.","audio":null,"s":[["**A – Winterthur-Veltheim**","A – Winterthur-Veltheim",0],["Schöne 3½-Zimmer-Wohnung im 2. Stock, 78 m², sonniger Balkon mit Blick ins Grüne.","Lovely 3.5-room flat on the 2nd floor, 78 m², sunny balcony with a view of greenery.",1],["Neue Küche, eigene Waschmaschine und Tumbler.","New kitchen, own washing machine and tumble dryer.",0],["5 Minuten zur Bushaltestelle.","5 minutes to the bus stop.",0],["Mietzins CHF 1850.– plus CHF 220.– Nebenkosten.","Rent CHF 1,850 plus CHF 220 additional costs.",0],["Haustiere auf Anfrage.","Pets on request.",0],["Frei ab 1. Dezember.","Available from 1 December.",0]]},{"t":"**B – Winterthur-Zentrum**\nMöblierte 1½-Zimmer-Wohnung, ideal für Studierende oder Wochenaufenthalter. Nur 3 Minuten zum Hauptbahnhof. Mietzins CHF 1290.– inklusive Nebenkosten und Internet. Keine Haustiere. Mindestmietdauer 6 Monate. Frei ab sofort.","audio":null,"s":[["**B – Winterthur-Zentrum**","B – Winterthur centre",0],["Möblierte 1½-Zimmer-Wohnung, ideal für Studierende oder Wochenaufenthalter.","Furnished 1.5-room flat, ideal for students or weekly residents.",1],["Nur 3 Minuten zum Hauptbahnhof.","Only 3 minutes to the main station.",0],["Mietzins CHF 1290.– inklusive Nebenkosten und Internet.","Rent CHF 1,290 including additional costs and internet.",0],["Keine Haustiere.","No pets.",0],["Mindestmietdauer 6 Monate.","Minimum rental period 6 months.",0],["Frei ab sofort.","Available immediately.",0]]},{"t":"**C – Winterthur-Seen**\nRuhige 4½-Zimmer-Wohnung im Erdgeschoss mit kleinem Garten. Ideal für Familien: Kindergarten und Schule ganz in der Nähe. Keine eigene Waschmaschine, Waschküche im Keller. Mietzins CHF 2100.– plus CHF 250.– Nebenkosten. Haustiere willkommen. Frei ab 1. Januar.","audio":null,"s":[["**C – Winterthur-Seen**","C – Winterthur-Seen",0],["Ruhige 4½-Zimmer-Wohnung im Erdgeschoss mit kleinem Garten.","Quiet 4.5-room flat on the ground floor with a small garden.",1],["Ideal für Familien: Kindergarten und Schule ganz in der Nähe.","Ideal for families: nursery school and school very close by.",0],["Keine eigene Waschmaschine, Waschküche im Keller.","No washing machine of your own, laundry room in the basement.",0],["Mietzins CHF 2100.– plus CHF 250.– Nebenkosten.","Rent CHF 2,100 plus CHF 250 additional costs.",0],["Haustiere willkommen.","Pets welcome.",0],["Frei ab 1. Januar.","Available from 1 January.",0]]}],"glossary":[{"de":"der Tumbler (CH)","en":"tumble dryer"},{"de":"der Wochenaufenthalter (CH)","en":"person who stays in a town only during the working week"},{"de":"auf Anfrage","en":"on request"},{"de":"die Mindestmietdauer","en":"minimum rental period"},{"de":"ab sofort","en":"immediately"},{"de":"m² (Quadratmeter)","en":"square metres"}],"questions":[{"type":"mc","q":"Familie Keller hat zwei Kinder und einen Hund. Welche Wohnung passt?","options":["A","B","C"],"a":2,"qEn":"The Keller family has two children and a dog. Which flat is suitable?","optionsEn":["A","B","C"]},{"type":"mc","q":"Luca studiert ein Semester in Winterthur und hat keine Möbel. Welche Wohnung passt?","options":["A","B","C"],"a":1,"qEn":"Luca is studying in Winterthur for a semester and has no furniture. Which flat is suitable?","optionsEn":["A","B","C"]},{"type":"mc","q":"Frau Suter möchte eine eigene Waschmaschine und einen Balkon. Welche Wohnung passt?","options":["A","B","C"],"a":0,"qEn":"Ms Suter would like her own washing machine and a balcony. Which flat is suitable?","optionsEn":["A","B","C"]},{"type":"tf","q":"In Wohnung B sind die Nebenkosten im Mietzins inklusive.","a":true,"why":"","qEn":"In flat B the additional costs are included in the rent."},{"type":"tf","q":"Wohnung C ist ab sofort frei.","a":false,"why":"Sie ist ab dem 1. Januar frei.","qEn":"Flat C is available immediately.","whyEn":"It is available from 1 January."}],"titleEn":"Three flat adverts"},"writing":{"task":"Sie interessieren sich für Wohnung A. Schreiben Sie eine E-Mail an die Verwaltung (60–80 Wörter).","points":["Stellen Sie sich kurz vor.","Warum interessieren Sie sich für die Wohnung? (weil …)","Bitten Sie um einen Termin für die Besichtigung.","Fragen Sie nach Haustieren."],"phrases":[{"de":"Sehr geehrte Damen und Herren","en":"Dear Sir or Madam"},{"de":"Ich habe Ihr Inserat gesehen und interessiere mich für die Wohnung.","en":"I saw your advert and I'm interested in the flat."},{"de":"Wäre eine Besichtigung am … möglich?","en":"Would a viewing on … be possible?"},{"de":"Ich möchte gerne wissen, ob …","en":"I would like to know whether …"},{"de":"Freundliche Grüsse","en":"Kind regards"}],"model":"Sehr geehrte Damen und Herren\n\nIch habe Ihr Inserat für die 3½-Zimmer-Wohnung in Veltheim gesehen und interessiere mich sehr für die Wohnung. Ich heisse Carla Ferreira, bin 32 Jahre alt und arbeite bei einer Logistikfirma in Winterthur. Ich suche eine grössere Wohnung, weil meine jetzige Wohnung nur ein Zimmer hat. Wäre eine Besichtigung am Samstag möglich? Ausserdem möchte ich gerne wissen, ob eine Katze erlaubt ist.\n\nFreundliche Grüsse\nCarla Ferreira","audio":"d960913f4533","taskS":[["Sie interessieren sich für Wohnung A.","You are interested in flat A.",0],["Schreiben Sie eine E-Mail an die Verwaltung (60–80 Wörter).","Write an email to the property management company (60–80 words).",0]],"pointsEn":["Briefly introduce yourself.","Why are you interested in the flat? (weil …)","Ask for an appointment for a viewing.","Ask about pets."],"modelP":[[["Sehr geehrte Damen und Herren","Dear Sir or Madam",0]],[["Ich habe Ihr Inserat für die 3½-Zimmer-Wohnung in Veltheim gesehen und interessiere mich sehr für die Wohnung.","I saw your advert for the 3.5-room flat in Veltheim and I'm very interested in the flat.",0],["Ich heisse Carla Ferreira, bin 32 Jahre alt und arbeite bei einer Logistikfirma in Winterthur.","My name is Carla Ferreira, I'm 32 years old and I work for a logistics company in Winterthur.",0],["Ich suche eine grössere Wohnung, weil meine jetzige Wohnung nur ein Zimmer hat.","I'm looking for a bigger flat because my current flat only has one room.",0],["Wäre eine Besichtigung am Samstag möglich?","Would a viewing on Saturday be possible?",0],["Ausserdem möchte ich gerne wissen, ob eine Katze erlaubt ist.","I would also like to know whether a cat is allowed.",0]],[["Freundliche Grüsse","Kind regards",0],["Carla Ferreira","Carla Ferreira",1]]]},"speaking":{"task":"Bei der Besichtigung – beantworten Sie die Fragen der Verwaltung. Benutzen Sie weil, dass oder wenn.","phrases":[{"de":"Ist die Wohnung noch frei?","en":"Is the flat still available?","audio":"efc9d32fcafc"},{"de":"Wie hoch sind die Nebenkosten?","en":"How high are the additional costs?","audio":"d5d7224185e3"},{"de":"Ab wann ist die Wohnung frei?","en":"From when is the flat available?","audio":"728e0e8b8d2c"},{"de":"Wann kann ich die Wohnung besichtigen?","en":"When can I view the flat?","audio":"03e9d61693b7"},{"de":"Mir gefällt, dass …","en":"I like that …","audio":null}],"prompts":[{"q":"Warum suchen Sie eine neue Wohnung?","model":"Ich suche eine neue Wohnung, weil meine Wohnung zu klein ist und weil ich näher bei der Arbeit wohnen möchte.","aq":"1ea02ab8891c","am":"e23095715351","qS":[["Warum suchen Sie eine neue Wohnung?","Why are you looking for a new flat?",0]],"modelS":[["Ich suche eine neue Wohnung, weil meine Wohnung zu klein ist und weil ich näher bei der Arbeit wohnen möchte.","I'm looking for a new flat because my flat is too small and because I'd like to live closer to work.",0]]},{"q":"Wie gefällt Ihnen die Wohnung?","model":"Sie gefällt mir sehr gut. Ich finde super, dass sie so hell ist und einen Balkon hat.","aq":"940358669aa0","am":"d06be6d24a76","qS":[["Wie gefällt Ihnen die Wohnung?","How do you like the flat?",0]],"modelS":[["Sie gefällt mir sehr gut.","I like it very much.",0],["Ich finde super, dass sie so hell ist und einen Balkon hat.","I think it's great that it's so bright and has a balcony.",0]]},{"q":"Wann möchten Sie einziehen?","model":"Wenn es möglich ist, möchte ich am ersten Dezember einziehen.","aq":"b39ec88faae8","am":"6b93d6049a35","qS":[["Wann möchten Sie einziehen?","When would you like to move in?",0]],"modelS":[["Wenn es möglich ist, möchte ich am ersten Dezember einziehen.","If possible, I'd like to move in on the first of December.",0]]},{"q":"Haben Sie noch Fragen?","model":"Ja. Ich möchte wissen, wie hoch die Nebenkosten sind und ob ich eine Katze haben darf.","aq":"89e0920c4c2d","am":"ee4585a2b732","qS":[["Haben Sie noch Fragen?","Do you have any other questions?",0]],"modelS":[["Ja.","Yes.",0],["Ich möchte wissen, wie hoch die Nebenkosten sind und ob ich eine Katze haben darf.","I'd like to know how high the additional costs are and whether I'm allowed to have a cat.",0]]}],"taskS":[["Bei der Besichtigung – beantworten Sie die Fragen der Verwaltung.","At the viewing – answer the questions from the property management company.",0],["Benutzen Sie weil, dass oder wenn.","Use weil, dass or wenn.",0]]},"en":{"title":"Finding a flat","subtitle":"Reading adverts, viewing a flat","focus":"Subordinate clauses with weil, dass and wenn"}},{"id":3,"title":"Beim Arzt","subtitle":"Termine, Beschwerden und gute Ratschläge","level":"A2","theme":"Gesundheit","focus":"Modalverben im Präsens und Präteritum","goals":[{"de":"Ich kann telefonisch einen Termin vereinbaren.","en":"I can make an appointment by phone."},{"de":"Ich kann meine Beschwerden beschreiben und die Anweisungen der Ärztin verstehen.","en":"I can describe my symptoms and understand the doctor's instructions."},{"de":"Ich kann sagen, was ich muss, kann, darf und soll.","en":"I can say what I must, can, may and should do."}],"vocab":[{"id":"3-0","de":"der Hausarzt","forms":"Hausärzte","en":"GP, family doctor","ex":"Ich habe noch keinen Hausarzt in der Schweiz.","exEn":"I don't have a GP in Switzerland yet.","aw":"90a9408c720d","ae":"96adb2e6955e"},{"id":"3-1","de":"die Praxis","forms":"Praxen","en":"(doctor's) practice","ex":"Die Praxis ist am Mittwochnachmittag geschlossen.","exEn":"The practice is closed on Wednesday afternoon.","aw":"19514f645d67","ae":"d8e40e98abb0"},{"id":"3-2","de":"einen Termin vereinbaren","forms":"hat vereinbart","en":"to make an appointment","ex":"Ich möchte einen Termin vereinbaren.","exEn":"I'd like to make an appointment.","aw":"5e5b26f2d81b","ae":"59fe1956ddc9"},{"id":"3-3","de":"die Beschwerden","forms":"(Pl.)","en":"symptoms, complaints","ex":"Was für Beschwerden haben Sie?","exEn":"What symptoms do you have?","aw":"f801a96e5c8c","ae":"0efa5b683fd1"},{"id":"3-4","de":"das Fieber","forms":"–","en":"fever","ex":"Ich habe seit gestern Fieber.","exEn":"I've had a fever since yesterday.","aw":"6b07b3eabf3b","ae":"4758776775d6"},{"id":"3-5","de":"der Husten","forms":"–","en":"cough","ex":"Der Husten ist in der Nacht schlimmer.","exEn":"The cough is worse at night.","aw":"8c297b0cf4b7","ae":"828de14a3bcf"},{"id":"3-6","de":"die Halsschmerzen","forms":"(Pl.)","en":"sore throat","ex":"Ich habe starke Halsschmerzen.","exEn":"I have a bad sore throat.","aw":"2f41b59dd35e","ae":"b5b4c21da5c3"},{"id":"3-7","de":"die Erkältung","forms":"-en","en":"cold","ex":"Das ist nur eine Erkältung.","exEn":"It's just a cold.","aw":"c191c6ce09f2","ae":"1f168219ea4a"},{"id":"3-8","de":"wehtun","forms":"hat wehgetan","en":"to hurt","ex":"Mein Rücken tut weh.","exEn":"My back hurts.","aw":"eafda5c11c58","ae":"af2bc309d0b9"},{"id":"3-9","de":"sich krankmelden","forms":"hat sich krankgemeldet","en":"to call in sick","ex":"Ich habe mich heute Morgen krankgemeldet.","exEn":"I called in sick this morning.","aw":"845d0d0867d5","ae":"c394f0facdba"},{"id":"3-10","de":"das Arztzeugnis","forms":"-se","en":"doctor's certificate (CH)","ex":"Mein Chef braucht ein Arztzeugnis.","exEn":"My boss needs a doctor's certificate.","aw":"c62869e7f7e9","ae":"e352b15aacd4"},{"id":"3-11","de":"das Rezept","forms":"-e","en":"prescription","ex":"Mit diesem Rezept gehen Sie in die Apotheke.","exEn":"Take this prescription to the pharmacy.","aw":"d70146f0f5f8","ae":"3ee1c55bc2c6"},{"id":"3-12","de":"die Apotheke","forms":"-n","en":"pharmacy","ex":"Die Apotheke am Bahnhof ist auch am Sonntag offen.","exEn":"The pharmacy at the station is also open on Sundays.","aw":"480793244892","ae":"2ef659382cfd"},{"id":"3-13","de":"das Medikament","forms":"-e","en":"medicine","ex":"Brauche ich für dieses Medikament ein Rezept?","exEn":"Do I need a prescription for this medicine?","aw":"d2f7b2410406","ae":"cc5ea703419d"},{"id":"3-14","de":"einnehmen","forms":"hat eingenommen","en":"to take (medicine)","ex":"Nehmen Sie die Tabletten nach dem Essen ein.","exEn":"Take the tablets after meals.","aw":"9fbae18254a9","ae":"046895818c7c"},{"id":"3-15","de":"sich ausruhen","forms":"hat sich ausgeruht","en":"to rest","ex":"Sie sollten sich ein paar Tage ausruhen.","exEn":"You should rest for a few days.","aw":"6faa4f7bb253","ae":"9e995d140a0d"},{"id":"3-16","de":"der Notfall","forms":"Notfälle","en":"emergency","ex":"Im Notfall rufen Sie die Nummer 144 an.","exEn":"In an emergency, call 144.","aw":"d9f5a34de9ec","ae":"7653d8673a9b"},{"id":"3-17","de":"das Spital","forms":"Spitäler","en":"hospital (CH)","ex":"Er liegt seit Montag im Spital.","exEn":"He has been in hospital since Monday.","aw":"e44795216ea1","ae":"bce7b81db29b"},{"id":"3-18","de":"die Versichertenkarte","forms":"-n","en":"health insurance card","ex":"Bitte bringen Sie Ihre Versichertenkarte mit.","exEn":"Please bring your insurance card.","aw":"5f1fcc73b776","ae":"26d2b9ef2b90"},{"id":"3-19","de":"die Franchise","forms":"-n","en":"annual deductible (CH)","ex":"Ich habe eine hohe Franchise gewählt.","exEn":"I chose a high deductible.","aw":"4e43dc0aed3b","ae":"587105a7fc56"}],"swiss":[{"ch":"das Spital","std":"das Krankenhaus","en":"hospital"},{"ch":"das Arztzeugnis","std":"das Attest","en":"doctor's certificate"},{"ch":"die Franchise","std":"die Selbstbeteiligung","en":"the amount you pay yourself each year before insurance pays"},{"ch":"144","std":"–","en":"ambulance (Sanität); 112 also works"}],"dialogue":{"title":"In der Arztpraxis","intro":"Carla ist krank. Sie ist bei Dr. Keller, ihrem neuen Hausarzt.","speakers":{"F":"Carla","M":"Dr. Keller"},"lines":[{"s":"M","de":"Guten Tag, Frau Ferreira. Was fehlt Ihnen denn?","en":"Hello, Ms Ferreira. What seems to be the problem?","audio":"4375deae2898"},{"s":"F","de":"Guten Tag. Ich habe seit drei Tagen Halsschmerzen und Husten. Und gestern Abend hatte ich Fieber.","en":"Hello. I've had a sore throat and a cough for three days. And yesterday evening I had a fever.","audio":"b4d587d2c410"},{"s":"M","de":"Wie hoch war das Fieber?","en":"How high was the fever?","audio":"4d8d86332d90"},{"s":"F","de":"Achtunddreissig Komma fünf. Ich konnte die ganze Nacht nicht schlafen.","en":"Thirty-eight point five. I couldn't sleep all night.","audio":"b3149e70e4a4"},{"s":"M","de":"Das tut mir leid. Mussten Sie heute arbeiten?","en":"I'm sorry. Did you have to work today?","audio":"1859889f103a"},{"s":"F","de":"Nein, ich habe mich heute Morgen krankgemeldet. Aber mein Chef will ein Arztzeugnis.","en":"No, I called in sick this morning. But my boss wants a doctor's certificate.","audio":"7d21b6973635"},{"s":"M","de":"Kein Problem, das bekommen Sie. Darf ich mal in Ihren Hals schauen? Machen Sie bitte den Mund auf.","en":"No problem, you'll get that. May I have a look at your throat? Please open your mouth.","audio":"88d1ec6c2303"},{"s":"M","de":"Ja, der Hals ist ziemlich rot.","en":"Yes, the throat is quite red.","audio":"cd71011d22b3"},{"s":"F","de":"Ist es etwas Schlimmes?","en":"Is it something serious?","audio":"898608e272e6"},{"s":"M","de":"Nein, keine Sorge. Es ist eine starke Erkältung. Sie müssen keine Antibiotika nehmen.","en":"No, don't worry. It's a bad cold. You don't need to take antibiotics.","audio":"5111fd40ddd3"},{"s":"F","de":"Was kann ich denn machen?","en":"So what can I do?","audio":"4740954f6293"},{"s":"M","de":"Sie sollten viel Tee trinken und sich ausruhen. Für den Hals gebe ich Ihnen ein Rezept für Lutschtabletten.","en":"You should drink lots of tea and rest. For your throat I'll give you a prescription for lozenges.","audio":"4a7f82c93a2a"},{"s":"F","de":"Darf ich am Wochenende Sport machen? Ich wollte eigentlich joggen gehen.","en":"May I do sport at the weekend? I was actually planning to go jogging.","audio":"9d4671c63038"},{"s":"M","de":"Nein, lieber nicht. Sie dürfen erst wieder Sport machen, wenn das Fieber weg ist.","en":"No, better not. You may only do sport again once the fever has gone.","audio":"7b9b34ff4773"},{"s":"F","de":"Okay. Wie oft muss ich die Tabletten nehmen?","en":"Okay. How often do I have to take the tablets?","audio":"4fc94c15c62a"},{"s":"M","de":"Sie können alle drei Stunden eine Tablette nehmen, aber nicht mehr als sechs pro Tag.","en":"You can take one tablet every three hours, but not more than six a day.","audio":"1391f8995014"},{"s":"F","de":"Und wie lange bin ich krankgeschrieben?","en":"And how long am I on sick leave?","audio":"69ba4bf4ab0e"},{"s":"M","de":"Bis Freitag. Wenn es Ihnen am Montag nicht besser geht, kommen Sie bitte wieder.","en":"Until Friday. If you're not feeling better on Monday, please come back.","audio":"0ba2a8d5c091"},{"s":"F","de":"Gut, das mache ich. Vielen Dank!","en":"Good, I'll do that. Thank you very much!","audio":"2f260bd239cb"},{"s":"M","de":"Gute Besserung, Frau Ferreira!","en":"Get well soon, Ms Ferreira!","audio":"1bba5ca67e14"}],"questions":[{"type":"tf","q":"Carla hat seit einer Woche Halsschmerzen.","a":false,"why":"Seit drei Tagen.","qEn":"Carla has had a sore throat for a week.","whyEn":"For three days."},{"type":"tf","q":"Carla konnte in der Nacht nicht schlafen.","a":true,"why":"","qEn":"Carla couldn't sleep during the night."},{"type":"mc","q":"Was möchte Carlas Chef?","options":["ein Rezept","ein Arztzeugnis","eine Versichertenkarte"],"a":1,"qEn":"What does Carla's boss want?","optionsEn":["a prescription","a doctor's certificate","an insurance card"]},{"type":"mc","q":"Was soll Carla machen?","options":["am Wochenende joggen","viel Tee trinken und sich ausruhen","Antibiotika nehmen"],"a":1,"qEn":"What should Carla do?","optionsEn":["go jogging at the weekend","drink lots of tea and rest","take antibiotics"]},{"type":"mc","q":"Wann soll Carla wiederkommen?","options":["morgen","am Freitag","am Montag, wenn es ihr nicht besser geht"],"a":2,"qEn":"When should Carla come back?","optionsEn":["tomorrow","on Friday","on Monday, if she isn't feeling better"]}],"titleEn":"At the doctor's practice","introS":[["Carla ist krank.","Carla is ill.",0],["Sie ist bei Dr. Keller, ihrem neuen Hausarzt.","She is at Dr Keller's, her new GP.",0]]},"grammar":{"title":"Modalverben – können, müssen, dürfen, sollen, wollen, möchten","summary":"Modalverben stehen auf Position 2, der Infinitiv steht am Ende.","sections":[{"h":"Was bedeuten die Modalverben?","table":[["Modalverb","Bedeutung","Beispiel"],["können","Fähigkeit, Möglichkeit","Ich kann nicht schlafen."],["müssen","Notwendigkeit, Pflicht","Ich muss zum Arzt gehen."],["dürfen","Erlaubnis","Darf ich hier parkieren?"],["nicht dürfen","Verbot","Im Spital darf man nicht rauchen."],["sollen","Rat oder Auftrag von einer anderen Person","Die Ärztin sagt, ich soll mich ausruhen."],["wollen","starker Wunsch, Plan","Ich will wieder gesund werden."],["möchten","höflicher Wunsch","Ich möchte einen Termin."]],"hEn":"What do the modal verbs mean?"},{"h":"Konjugation im Präsens","text":"Bei **ich** und **er/sie/es** haben Modalverben **keine Endung**, und oft ändert sich der Vokal im Singular.","table":[["Person","können","müssen","dürfen","sollen","wollen","möchten"],["ich","kann","muss","darf","soll","will","möchte"],["du","kannst","musst","darfst","sollst","willst","möchtest"],["er/sie/es","kann","muss","darf","soll","will","möchte"],["wir","können","müssen","dürfen","sollen","wollen","möchten"],["ihr","könnt","müsst","dürft","sollt","wollt","möchtet"],["sie/Sie","können","müssen","dürfen","sollen","wollen","möchten"]],"hEn":"Conjugation in the present tense","textP":[[["Bei **ich** und **er/sie/es** haben Modalverben **keine Endung**, und oft ändert sich der Vokal im Singular.","With ich and er/sie/es, modal verbs have no ending, and the vowel often changes in the singular.",0]]]},{"h":"Die Satzklammer","text":"Das Modalverb steht auf **Position 2** (in der W-Frage und im Aussagesatz) oder auf **Position 1** (Ja/Nein-Frage). Der **Infinitiv** steht am Ende.","examples":[{"de":"Ich ==muss== heute zum Arzt ==gehen==.","en":"I have to go to the doctor today.","audio":"06c7e3c5f37a"},{"de":"Wann ==können== Sie in die Praxis ==kommen==?","en":"When can you come to the practice?","audio":"2d0d608f6dff"},{"de":"==Darf== ich am Wochenende Sport ==machen==?","en":"May I do sport at the weekend?","audio":"a36d56317178"}],"hEn":"The sentence bracket","textP":[[["Das Modalverb steht auf **Position 2** (in der W-Frage und im Aussagesatz) oder auf **Position 1** (Ja/Nein-Frage).","The modal verb goes in position 2 (in W-questions and statements) or in position 1 (yes/no questions).",0],["Der **Infinitiv** steht am Ende.","The infinitive goes at the end.",0]]]},{"h":"Präteritum – ohne Umlaut","text":"In der Vergangenheit benutzt man bei Modalverben fast immer das **Präteritum**. Die Endung ist **-te**, und der Umlaut fällt weg. Für **möchten** benutzt man in der Vergangenheit **wollen**.","table":[["Person","können","müssen","dürfen","sollen","wollen"],["ich","konnte","musste","durfte","sollte","wollte"],["du","konntest","musstest","durftest","solltest","wolltest"],["er/sie/es","konnte","musste","durfte","sollte","wollte"],["wir","konnten","mussten","durften","sollten","wollten"],["ihr","konntet","musstet","durftet","solltet","wolltet"],["sie/Sie","konnten","mussten","durften","sollten","wollten"]],"examples":[{"de":"Ich ==konnte== die ganze Nacht nicht ==schlafen==.","en":"I couldn't sleep all night.","audio":"54f6b6e8aea0"},{"de":"Ich ==wollte== eigentlich joggen ==gehen==.","en":"I was actually planning to go jogging.","audio":"537619e57648"}],"hEn":"Simple past – without umlaut","textP":[[["In der Vergangenheit benutzt man bei Modalverben fast immer das **Präteritum**.","In the past, modal verbs are almost always used in the simple past.",0],["Die Endung ist **-te**, und der Umlaut fällt weg.","The ending is -te, and the umlaut disappears.",0],["Für **möchten** benutzt man in der Vergangenheit **wollen**.","For möchten, you use wollen in the past.",0]]]},{"h":"Ratschläge mit sollte","text":"Für einen freundlichen Rat benutzt man oft **sollte** (Konjunktiv II): *Sie sollten sich ausruhen. Du solltest mehr trinken.* Mehr dazu in Lektion 6.","hEn":"Advice with sollte","textP":[[["Für einen freundlichen Rat benutzt man oft **sollte** (Konjunktiv II): *Sie sollten sich ausruhen.*","For friendly advice people often use sollte (subjunctive II): You should rest.",0],["*Du solltest mehr trinken.*","You should drink more.",0],["Mehr dazu in Lektion 6.","More on this in unit 6.",0]]]}],"tip":"Achtung: „nicht müssen\" ist nicht „nicht dürfen\"! Sie müssen keine Antibiotika nehmen = es ist nicht nötig. Sie dürfen keinen Sport machen = es ist verboten.","titleEn":"Modal verbs – können, müssen, dürfen, sollen, wollen, möchten","summaryS":[["Modalverben stehen auf Position 2, der Infinitiv steht am Ende.","Modal verbs go in position 2, the infinitive goes at the end.",0]],"tipP":[[["Achtung: „nicht müssen\" ist nicht „nicht dürfen\"!","Careful: \"nicht müssen\" is not \"nicht dürfen\"!",0],["Sie müssen keine Antibiotika nehmen = es ist nicht nötig.","You don't need to take antibiotics = it isn't necessary.",0],["Sie dürfen keinen Sport machen = es ist verboten.","You mustn't do sport = it's forbidden.",0]]]},"exercises":[{"type":"choice","title":"Welches Modalverb passt?","items":[{"q":"Die Ärztin sagt, ich ___ viel Wasser trinken.","options":["soll","darf","kann"],"a":0,"full":"Die Ärztin sagt, ich soll viel Wasser trinken.","audio":"4a2c1524d2d5","en":"The doctor says I should drink lots of water."},{"q":"Im Spital ___ man nicht rauchen.","options":["darf","muss","will"],"a":0,"full":"Im Spital darf man nicht rauchen.","audio":"2bf8272b9f77","en":"You're not allowed to smoke in the hospital."},{"q":"___ Sie mir bitte Ihre Versichertenkarte geben?","options":["Können","Müssen","Dürfen"],"a":0,"full":"Können Sie mir bitte Ihre Versichertenkarte geben?","audio":"40ddd9a03b0d","en":"Could you please give me your insurance card?"},{"q":"Sie haben keine Infektion. Sie ___ keine Antibiotika nehmen.","options":["müssen","dürfen","wollen"],"a":0,"full":"Sie haben keine Infektion. Sie müssen keine Antibiotika nehmen.","audio":"5bbe06d7fcc9","en":"You don't have an infection. You don't need to take antibiotics."},{"q":"Gestern ___ ich nicht schlafen, weil ich so stark husten musste.","options":["konnte","durfte","sollte"],"a":0,"full":"Gestern konnte ich nicht schlafen, weil ich so stark husten musste.","audio":"3d89930fd39f","en":"Yesterday I couldn't sleep because I had to cough so much."},{"q":"Mein Chef ___ unbedingt ein Arztzeugnis sehen.","options":["will","darf","soll"],"a":0,"full":"Mein Chef will unbedingt ein Arztzeugnis sehen.","audio":"53cc73415e9a","en":"My boss absolutely wants to see a doctor's certificate."},{"q":"Als Kind ___ ich jeden Tag Gemüse essen – meine Mutter war sehr streng.","options":["musste","konnte","wollte"],"a":0,"full":"Als Kind musste ich jeden Tag Gemüse essen – meine Mutter war sehr streng.","audio":"c35e1d3c24d0","en":"As a child I had to eat vegetables every day – my mother was very strict."},{"q":"___ ich hier parkieren? – Ja, aber nur für Patienten.","options":["Darf","Muss","Soll"],"a":0,"full":"Darf ich hier parkieren? – Ja, aber nur für Patienten.","audio":"35162c6c7028","en":"May I park here? – Yes, but only for patients."}],"titleEn":"Which modal verb fits?"},{"type":"gap","title":"Konjugieren Sie das Modalverb","items":[{"q":"Du ___ dich ausruhen. (sollen)","a":["sollst"],"full":"Du sollst dich ausruhen.","audio":"17c9cae65d17","en":"You're supposed to rest."},{"q":"___ ihr morgen zum Arzt gehen? (müssen)","a":["Müsst"],"full":"Müsst ihr morgen zum Arzt gehen?","audio":"8f876d3ddf6c","en":"Do you (all) have to go to the doctor tomorrow?"},{"q":"Er ___ leider nicht kommen. (können)","a":["kann"],"full":"Er kann leider nicht kommen.","audio":"fbfa464341c4","en":"Unfortunately he can't come."},{"q":"Wir ___ gestern um acht Uhr in der Praxis sein. (müssen, Präteritum)","a":["mussten"],"full":"Wir mussten gestern um acht Uhr in der Praxis sein.","audio":"c62a40ccf21a","en":"We had to be at the practice at eight o'clock yesterday."},{"q":"Ich ___ bitte einen Termin vereinbaren. (möchten)","a":["möchte"],"full":"Ich möchte bitte einen Termin vereinbaren.","audio":"6cd96b4b9605","en":"I would like to make an appointment, please."},{"q":"Carla ___ letzte Woche keinen Sport machen. (dürfen, Präteritum)","a":["durfte"],"full":"Carla durfte letzte Woche keinen Sport machen.","audio":"308d8b253e08","en":"Carla wasn't allowed to do any sport last week."},{"q":"___ du heute Abend mitkommen? (wollen)","a":["Willst"],"full":"Willst du heute Abend mitkommen?","audio":"ba5c2848de15","en":"Do you want to come along this evening?"}],"titleEn":"Conjugate the modal verb"},{"type":"order","title":"Bilden Sie Sätze","items":[{"a":["Ich muss heute zum Arzt gehen.","Heute muss ich zum Arzt gehen."],"tokens":["Ich","muss","heute","zum","Arzt","gehen."],"audio":"06c7e3c5f37a","en":"I have to go to the doctor today."},{"a":["Kann ich morgen einen Termin bekommen?"],"tokens":["Kann","ich","morgen","einen","Termin","bekommen?"],"audio":"d18634f67ffb","en":"Can I get an appointment tomorrow?"},{"a":["Gestern konnte ich nicht zur Arbeit gehen.","Ich konnte gestern nicht zur Arbeit gehen."],"tokens":["Gestern","konnte","ich","nicht","zur","Arbeit","gehen."],"audio":"aa525063cfaf","en":"Yesterday I couldn't go to work."},{"a":["Im Wartezimmer darf man nicht telefonieren.","Man darf im Wartezimmer nicht telefonieren."],"tokens":["Im","Wartezimmer","darf","man","nicht","telefonieren."],"audio":"81d7e0940b2f","en":"You mustn't make phone calls in the waiting room."},{"a":["Wie oft soll ich die Tabletten nehmen?"],"tokens":["Wie","oft","soll","ich","die","Tabletten","nehmen?"],"audio":"de217bae7f7d","en":"How often should I take the tablets?"}],"titleEn":"Make sentences"},{"type":"match","title":"Problem und Ratschlag","items":[{"l":"Ich kann nicht schlafen.","r":"Du solltest abends keinen Kaffee trinken."},{"l":"Ich habe Rückenschmerzen.","r":"Du solltest nicht so lange sitzen."},{"l":"Ich habe hohes Fieber.","r":"Du solltest zum Arzt gehen."},{"l":"Ich bin immer müde.","r":"Du solltest früher ins Bett gehen."},{"l":"Ich habe Zahnschmerzen.","r":"Du solltest einen Termin beim Zahnarzt vereinbaren."}],"titleEn":"Problem and advice"},{"type":"dictation","title":"Diktat – hören und schreiben","items":[{"a":"Ich habe seit drei Tagen Fieber.","audio":"a08de445f1b7","en":"I've had a fever for three days."},{"a":"Sie müssen die Tabletten nach dem Essen einnehmen.","audio":"8cca5bd1d3fe","en":"You have to take the tablets after meals."},{"a":"Darf ich morgen wieder arbeiten?","audio":"e55d1cbfa731","en":"Can I go back to work tomorrow?"},{"a":"Ich möchte gerne einen Termin vereinbaren.","audio":"50b61818e73d","en":"I'd like to make an appointment."}],"titleEn":"Dictation – listen and write"}],"reading":{"title":"Krank in der Schweiz – was muss ich wissen?","kind":"Infotext","paras":[{"t":"Wenn Sie in der Schweiz krank sind, gehen Sie normalerweise zuerst zu Ihrer Hausärztin oder zu Ihrem Hausarzt. Viele Menschen haben bei der Krankenkasse ein Hausarztmodell. Dann müssen sie immer zuerst in die Hausarztpraxis gehen – dafür bezahlen sie jeden Monat weniger. Bei anderen Modellen muss man zuerst eine Telefonberatung anrufen.","audio":"6892be8b386c","s":[["Wenn Sie in der Schweiz krank sind, gehen Sie normalerweise zuerst zu Ihrer Hausärztin oder zu Ihrem Hausarzt.","If you're ill in Switzerland, you normally go to your GP first.",0],["Viele Menschen haben bei der Krankenkasse ein Hausarztmodell.","Many people have a GP model with their health insurance.",0],["Dann müssen sie immer zuerst in die Hausarztpraxis gehen – dafür bezahlen sie jeden Monat weniger.","Then they always have to go to the GP's practice first – in return they pay less every month.",0],["Bei anderen Modellen muss man zuerst eine Telefonberatung anrufen.","With other models you first have to call a medical advice line.",0]]},{"t":"Für kleine Probleme wie eine Erkältung oder Kopfschmerzen können Sie auch in eine Apotheke gehen. Die Apothekerinnen und Apotheker beraten Sie gern, und viele Medikamente kann man ohne Rezept kaufen.","audio":"748c18fe93e1","s":[["Für kleine Probleme wie eine Erkältung oder Kopfschmerzen können Sie auch in eine Apotheke gehen.","For small problems like a cold or a headache you can also go to a pharmacy.",0],["Die Apothekerinnen und Apotheker beraten Sie gern, und viele Medikamente kann man ohne Rezept kaufen.","The pharmacists are happy to advise you, and you can buy many medicines without a prescription.",0]]},{"t":"Im Notfall dürfen Sie nicht warten: Rufen Sie sofort die Nummer 144 an, oder gehen Sie auf die Notfallstation im Spital.","audio":"00962130adea","s":[["Im Notfall dürfen Sie nicht warten: Rufen Sie sofort die Nummer 144 an, oder gehen Sie auf die Notfallstation im Spital.","In an emergency you mustn't wait: call 144 immediately, or go to the emergency department at the hospital.",0]]},{"t":"Wichtig: Die Krankenkasse bezahlt nicht alles. Jede erwachsene Person hat eine Franchise. Diesen Betrag muss man jedes Jahr selbst bezahlen – mindestens 300 Franken. Danach bezahlt man meistens noch zehn Prozent der Kosten selbst. Das nennt man Selbstbehalt.","audio":"28e19ea8eb93","s":[["Wichtig: Die Krankenkasse bezahlt nicht alles.","Important: health insurance doesn't pay for everything.",0],["Jede erwachsene Person hat eine Franchise.","Every adult has a deductible.",0],["Diesen Betrag muss man jedes Jahr selbst bezahlen – mindestens 300 Franken.","You have to pay this amount yourself every year – at least 300 francs.",0],["Danach bezahlt man meistens noch zehn Prozent der Kosten selbst.","After that you usually still pay ten percent of the costs yourself.",0],["Das nennt man Selbstbehalt.","This is called the co-payment.",0]]},{"t":"Wenn Sie krank sind und nicht arbeiten können, müssen Sie sich sofort bei Ihrem Arbeitgeber krankmelden. Bei vielen Firmen braucht man ab dem dritten Tag ein Arztzeugnis.","audio":"27532f42f259","s":[["Wenn Sie krank sind und nicht arbeiten können, müssen Sie sich sofort bei Ihrem Arbeitgeber krankmelden.","If you're ill and can't work, you must call in sick with your employer straight away.",0],["Bei vielen Firmen braucht man ab dem dritten Tag ein Arztzeugnis.","At many companies you need a doctor's certificate from the third day.",0]]}],"glossary":[{"de":"das Hausarztmodell","en":"insurance model where you always see your GP first"},{"de":"die Telefonberatung","en":"medical advice line"},{"de":"beraten","en":"to advise"},{"de":"die Notfallstation","en":"emergency department"},{"de":"der Betrag","en":"amount"},{"de":"der Selbstbehalt","en":"co-payment (10 % of costs)"}],"questions":[{"type":"tf","q":"Mit einem Hausarztmodell geht man zuerst zur Hausärztin oder zum Hausarzt.","a":true,"why":"","qEn":"With a GP model you go to your GP first."},{"type":"tf","q":"In der Apotheke bekommt man nur Medikamente mit Rezept.","a":false,"why":"Viele Medikamente kann man ohne Rezept kaufen.","qEn":"At the pharmacy you can only get prescription medicines.","whyEn":"You can buy many medicines without a prescription."},{"type":"mc","q":"Was macht man im Notfall?","options":["Man ruft sofort die Nummer 144 an.","Man wartet bis zum nächsten Tag.","Man geht in die Apotheke."],"a":0,"qEn":"What do you do in an emergency?","optionsEn":["You call 144 immediately.","You wait until the next day.","You go to the pharmacy."]},{"type":"mc","q":"Was ist die Franchise?","options":["ein Betrag, den man jedes Jahr selbst bezahlt","eine Telefonberatung","ein Arztzeugnis"],"a":0,"qEn":"What is the \"Franchise\"?","optionsEn":["an amount you pay yourself every year","a telephone advice service","a doctor's certificate"]},{"type":"tf","q":"Bei vielen Firmen braucht man schon am ersten Tag ein Arztzeugnis.","a":false,"why":"Oft erst ab dem dritten Tag.","qEn":"At many companies you need a doctor's certificate from the very first day.","whyEn":"Often only from the third day."}],"titleEn":"Ill in Switzerland – what do I need to know?"},"writing":{"task":"Sie sind krank und können diese Woche nicht arbeiten. Schreiben Sie Ihrer Chefin eine E-Mail (60–80 Wörter).","points":["Sagen Sie, dass Sie krank sind.","Was haben Sie? Wie lange sind Sie krankgeschrieben?","Wer kann Ihre Arbeit machen?","Wann kommen Sie wieder?"],"phrases":[{"de":"Leider bin ich krank und kann nicht zur Arbeit kommen.","en":"Unfortunately I'm ill and can't come to work."},{"de":"Die Ärztin hat mich bis … krankgeschrieben.","en":"The doctor has signed me off sick until …"},{"de":"Das Arztzeugnis schicke ich Ihnen …","en":"I'll send you the doctor's certificate …"},{"de":"… kann meine Aufgaben übernehmen.","en":"… can take over my tasks."}],"model":"Sehr geehrte Frau Weber\n\nLeider bin ich krank und kann diese Woche nicht zur Arbeit kommen. Ich habe eine starke Erkältung mit Fieber. Ich war heute Morgen beim Arzt, und er hat mich bis Freitag krankgeschrieben. Das Arztzeugnis schicke ich Ihnen heute noch per E-Mail. Mein Kollege Luca kann die Lieferungen am Donnerstag kontrollieren – ich habe ihn schon informiert. Am Montag bin ich hoffentlich wieder im Büro.\n\nFreundliche Grüsse\nCarla Ferreira","audio":"742862a53733","taskS":[["Sie sind krank und können diese Woche nicht arbeiten.","You're ill and can't work this week.",0],["Schreiben Sie Ihrer Chefin eine E-Mail (60–80 Wörter).","Write an email to your boss (60–80 words).",0]],"pointsEn":["Say that you're ill.","What do you have? How long are you signed off sick?","Who can do your work?","When will you be back?"],"modelP":[[["Sehr geehrte Frau Weber","Dear Ms Weber",0]],[["Leider bin ich krank und kann diese Woche nicht zur Arbeit kommen.","Unfortunately I'm ill and can't come to work this week.",0],["Ich habe eine starke Erkältung mit Fieber.","I have a bad cold with a fever.",0],["Ich war heute Morgen beim Arzt, und er hat mich bis Freitag krankgeschrieben.","I was at the doctor's this morning, and he has signed me off sick until Friday.",0],["Das Arztzeugnis schicke ich Ihnen heute noch per E-Mail.","I'll send you the doctor's certificate by email today.",0],["Mein Kollege Luca kann die Lieferungen am Donnerstag kontrollieren – ich habe ihn schon informiert.","My colleague Luca can check the deliveries on Thursday – I've already told him.",0],["Am Montag bin ich hoffentlich wieder im Büro.","I hope to be back in the office on Monday.",0]],[["Freundliche Grüsse","Kind regards",0],["Carla Ferreira","Carla Ferreira",1]]]},"speaking":{"task":"Sie rufen in der Arztpraxis an. Beantworten Sie die Fragen der Praxisassistentin.","phrases":[{"de":"Ich möchte gerne einen Termin vereinbaren.","en":"I'd like to make an appointment.","audio":"221eb03c7c97"},{"de":"Ich habe seit … Tagen …","en":"I've had … for … days.","audio":null},{"de":"Mir ist schlecht.","en":"I feel sick.","audio":"f42fcf8fdb52"},{"de":"Geht es auch etwas später?","en":"Would a bit later also work?","audio":"4023ad1531fa"},{"de":"Muss ich etwas mitbringen?","en":"Do I need to bring anything?","audio":"9bfe7a79f16a"}],"prompts":[{"q":"Praxis Dr. Keller, guten Tag. Was kann ich für Sie tun?","model":"Guten Tag, hier ist Carla Ferreira. Ich möchte gerne einen Termin vereinbaren.","aq":"7b5f3f8925cc","am":"fa5e9faf8a22","qS":[["Praxis Dr. Keller, guten Tag.","Dr Keller's practice, good morning.",0],["Was kann ich für Sie tun?","What can I do for you?",0]],"modelS":[["Guten Tag, hier ist Carla Ferreira.","Hello, this is Carla Ferreira.",0],["Ich möchte gerne einen Termin vereinbaren.","I'd like to make an appointment.",0]]},{"q":"Was für Beschwerden haben Sie?","model":"Ich habe seit drei Tagen Halsschmerzen und Husten, und gestern hatte ich auch Fieber.","aq":"14f0d3a1cb51","am":"b147a7f42930","qS":[["Was für Beschwerden haben Sie?","What symptoms do you have?",0]],"modelS":[["Ich habe seit drei Tagen Halsschmerzen und Husten, und gestern hatte ich auch Fieber.","I've had a sore throat and a cough for three days, and yesterday I also had a fever.",0]]},{"q":"Können Sie morgen um halb neun kommen?","model":"Morgen früh muss ich leider arbeiten. Geht es auch am Nachmittag?","aq":"34e39b31f820","am":"6297eb010541","qS":[["Können Sie morgen um halb neun kommen?","Can you come tomorrow at half past eight?",0]],"modelS":[["Morgen früh muss ich leider arbeiten.","Unfortunately I have to work tomorrow morning.",0],["Geht es auch am Nachmittag?","Would the afternoon also work?",0]]},{"q":"Gut, dann um fünfzehn Uhr. Haben Sie noch eine Frage?","model":"Ja, muss ich etwas mitbringen? – Ah, die Versichertenkarte. Vielen Dank, bis morgen!","aq":"591f0ab8e5f8","am":"001f8a007845","qS":[["Gut, dann um fünfzehn Uhr.","Fine, then at three p.m.",0],["Haben Sie noch eine Frage?","Do you have any other questions?",0]],"modelS":[["Ja, muss ich etwas mitbringen? – Ah, die Versichertenkarte.","Yes, do I need to bring anything? – Ah, the insurance card.",0],["Vielen Dank, bis morgen!","Thank you very much, see you tomorrow!",0]]}],"taskS":[["Sie rufen in der Arztpraxis an.","You're calling the doctor's practice.",0],["Beantworten Sie die Fragen der Praxisassistentin.","Answer the medical assistant's questions.",0]]},"en":{"title":"At the doctor's","subtitle":"Appointments, symptoms and good advice","focus":"Modal verbs in the present and simple past"}},{"id":4,"title":"Einkaufen und reklamieren","subtitle":"Produkte vergleichen, umtauschen, sich beschweren","level":"A2","theme":"Einkaufen","focus":"Adjektivendungen, Komparativ und Superlativ","goals":[{"de":"Ich kann ein Produkt reklamieren und sagen, was nicht funktioniert.","en":"I can complain about a product and say what isn't working."},{"de":"Ich kann Produkte vergleichen (günstiger, besser, am schnellsten).","en":"I can compare products."},{"de":"Ich kann Regeln für Umtausch und Rückgabe verstehen.","en":"I can understand exchange and return rules."}],"vocab":[{"id":"4-0","de":"die Reklamation","forms":"-en","en":"complaint (about a product)","ex":"Ich habe eine Reklamation.","exEn":"I have a complaint.","aw":"bb984d3681bd","ae":"81434eb9227c"},{"id":"4-1","de":"reklamieren","forms":"hat reklamiert","en":"to complain about, return as faulty","ex":"Ich möchte diesen Wasserkocher reklamieren.","exEn":"I'd like to return this kettle, it's faulty.","aw":"a0dcc02c2c62","ae":"152d035c5d20"},{"id":"4-2","de":"sich beschweren","forms":"hat sich beschwert","en":"to complain","ex":"Er hat sich beim Kundendienst beschwert.","exEn":"He complained to customer service.","aw":"9d479f7eaf8c","ae":"7e4fee877ec9"},{"id":"4-3","de":"umtauschen","forms":"hat umgetauscht","en":"to exchange","ex":"Kann ich die Jacke umtauschen?","exEn":"Can I exchange the jacket?","aw":"0d1615d8032b","ae":"f4beefeb5cbb"},{"id":"4-4","de":"die Quittung","forms":"-en","en":"receipt","ex":"Haben Sie die Quittung noch?","exEn":"Do you still have the receipt?","aw":"b1aab9d8f4a6","ae":"01c089f4e5c7"},{"id":"4-5","de":"die Garantie","forms":"-n","en":"warranty, guarantee","ex":"Das Gerät hat zwei Jahre Garantie.","exEn":"The appliance has a two-year warranty.","aw":"8898dac0dfb1","ae":"6cdbff7db849"},{"id":"4-6","de":"das Gerät","forms":"-e","en":"appliance, device","ex":"Das Gerät ist nach einer Woche kaputtgegangen.","exEn":"The appliance broke after a week.","aw":"9f61e9ead914","ae":"b392433aae6d"},{"id":"4-7","de":"kaputt","forms":"–","en":"broken","ex":"Mein Handy ist schon wieder kaputt.","exEn":"My phone is broken again.","aw":"019c649b646d","ae":"f19b80d47afa"},{"id":"4-8","de":"funktionieren","forms":"hat funktioniert","en":"to work, to function","ex":"Die Kaffeemaschine funktioniert nicht mehr.","exEn":"The coffee machine doesn't work any more.","aw":"5b71bb5112bd","ae":"952dd6a526b1"},{"id":"4-9","de":"die Grösse","forms":"-n","en":"size","ex":"Haben Sie das auch in einer anderen Grösse?","exEn":"Do you have this in another size?","aw":"7e2b8d76b723","ae":"3f792ae937e0"},{"id":"4-10","de":"anprobieren","forms":"hat anprobiert","en":"to try on","ex":"Kann ich die Hose anprobieren?","exEn":"Can I try on the trousers?","aw":"580f2f4f8497","ae":"b05d15cce348"},{"id":"4-11","de":"passen","forms":"hat gepasst","en":"to fit","ex":"Die Schuhe passen mir leider nicht.","exEn":"Unfortunately the shoes don't fit me.","aw":"04b29c25e7f6","ae":"9d3017b0a846"},{"id":"4-12","de":"die Aktion","forms":"-en","en":"special offer (CH)","ex":"Die Äpfel sind diese Woche in Aktion.","exEn":"Apples are on special offer this week.","aw":"7cb046ca11b3","ae":"dcb72053e8d8"},{"id":"4-13","de":"günstig","forms":"–","en":"inexpensive, good value","ex":"Im Internet ist es oft günstiger.","exEn":"It's often cheaper online.","aw":"080c7e6aa331","ae":"2fd6728e0c89"},{"id":"4-14","de":"der Kundendienst","forms":"–","en":"customer service","ex":"Der Kundendienst hat mir sofort geholfen.","exEn":"Customer service helped me right away.","aw":"d582c3852b06","ae":"1c2433f830b7"},{"id":"4-15","de":"das Geld zurückbekommen","forms":"hat zurückbekommen","en":"to get your money back","ex":"Bekomme ich mein Geld zurück?","exEn":"Do I get my money back?","aw":"cb3ee1b4a232","ae":"d7be5c3da750"},{"id":"4-16","de":"der Gutschein","forms":"-e","en":"voucher","ex":"Sie bekommen einen Gutschein über fünfzig Franken.","exEn":"You get a voucher for fifty francs.","aw":"ab395f9059e3","ae":"1a7e959ce99a"},{"id":"4-17","de":"die Kasse","forms":"-n","en":"checkout, till","ex":"Bitte bezahlen Sie vorne an der Kasse.","exEn":"Please pay at the checkout at the front.","aw":"a9796659fd7e","ae":"6b662859703e"},{"id":"4-18","de":"enttäuscht","forms":"–","en":"disappointed","ex":"Ich bin von der Qualität enttäuscht.","exEn":"I'm disappointed with the quality.","aw":"72f75fde2b10","ae":"8e3218d306a8"},{"id":"4-19","de":"die Verpackung","forms":"-en","en":"packaging","ex":"Bitte bringen Sie das Gerät in der Originalverpackung zurück.","exEn":"Please bring the appliance back in its original packaging.","aw":"d7ed8c14cf77","ae":"1b7289fac992"}],"swiss":[{"ch":"die Aktion","std":"das Sonderangebot","en":"special offer"},{"ch":"TWINT","std":"–","en":"Swiss mobile payment app, accepted almost everywhere"},{"ch":"das Portemonnaie","std":"der Geldbeutel","en":"wallet, purse"}],"dialogue":{"title":"Ein kaputter Wasserkocher","intro":"Carla hat letzte Woche einen Wasserkocher gekauft. Jetzt ist sie wieder im Geschäft.","speakers":{"F":"Carla","M":"Verkäufer"},"lines":[{"s":"M","de":"Guten Tag. Kann ich Ihnen helfen?","en":"Hello. Can I help you?","audio":"585f4b74672c"},{"s":"F","de":"Guten Tag. Ich habe letzte Woche diesen Wasserkocher gekauft, aber er funktioniert nicht mehr.","en":"Hello. I bought this kettle last week, but it doesn't work any more.","audio":"0d369fa88520"},{"s":"M","de":"Oh, das tut mir leid. Was ist denn das Problem?","en":"Oh, I'm sorry. What's the problem?","audio":"70f8b660032b"},{"s":"F","de":"Das Wasser wird nicht mehr heiss. Das rote Licht geht an, aber sonst passiert nichts.","en":"The water doesn't get hot any more. The red light comes on, but nothing else happens.","audio":"5e4011cbc2da"},{"s":"M","de":"Haben Sie die Quittung dabei?","en":"Do you have the receipt with you?","audio":"e8ab6e8259d0"},{"s":"F","de":"Ja, hier ist sie.","en":"Yes, here it is.","audio":"197c9617712a"},{"s":"M","de":"Danke. Das Gerät hat zwei Jahre Garantie. Möchten Sie einen neuen Wasserkocher oder lieber Ihr Geld zurück?","en":"Thanks. The appliance has a two-year warranty. Would you like a new kettle or would you prefer your money back?","audio":"43f817f7dcb4"},{"s":"F","de":"Gibt es auch ein anderes Modell? Der alte Wasserkocher war ziemlich laut.","en":"Is there another model too? The old kettle was quite loud.","audio":"fc3c5833fef2"},{"s":"M","de":"Ja, hier haben wir zum Beispiel diesen weissen Wasserkocher. Er ist leiser und schneller als Ihr altes Modell.","en":"Yes, here we have this white kettle, for example. It's quieter and faster than your old model.","audio":"f98f5ba9b31a"},{"s":"F","de":"Und was kostet er?","en":"And how much does it cost?","audio":"26cf90ee6d4b"},{"s":"M","de":"Neunundvierzig Franken. Er ist also zehn Franken teurer.","en":"Forty-nine francs. So it's ten francs more expensive.","audio":"b276fa78a45c"},{"s":"F","de":"Und der silberne da hinten?","en":"And the silver one back there?","audio":"c6db0b660909"},{"s":"M","de":"Der ist am günstigsten, nur fünfunddreissig Franken. Aber er ist kleiner – nur ein Liter.","en":"That's the cheapest, only thirty-five francs. But it's smaller – only one litre.","audio":"341e4e7f8241"},{"s":"F","de":"Das ist mir zu klein, ich trinke sehr viel Tee! Ich nehme den weissen.","en":"That's too small for me, I drink a lot of tea! I'll take the white one.","audio":"9ba01686e744"},{"s":"M","de":"Gute Wahl. Dann bezahlen Sie nur die Differenz, also zehn Franken.","en":"Good choice. Then you only pay the difference, so ten francs.","audio":"1f123a63517b"},{"s":"F","de":"Kann ich mit TWINT bezahlen?","en":"Can I pay with TWINT?","audio":"3368e11aef5f"},{"s":"M","de":"Natürlich, hier ist der QR-Code.","en":"Of course, here's the QR code.","audio":"8e438593f761"},{"s":"F","de":"Super. Vielen Dank für den guten Service!","en":"Great. Thank you for the good service!","audio":"1554c02d7d0e"}],"questions":[{"type":"tf","q":"Carla hat den Wasserkocher vor einem Jahr gekauft.","a":false,"why":"Sie hat ihn letzte Woche gekauft.","qEn":"Carla bought the kettle a year ago.","whyEn":"She bought it last week."},{"type":"mc","q":"Was ist das Problem?","options":["Er ist zu laut.","Das Wasser wird nicht heiss.","Das Licht funktioniert nicht."],"a":1,"qEn":"What's the problem?","optionsEn":["It's too loud.","The water doesn't get hot.","The light doesn't work."]},{"type":"mc","q":"Warum möchte Carla ein anderes Modell?","options":["Das alte Modell war zu laut.","Das alte Modell war zu teuer.","Das alte Modell war zu klein."],"a":0,"qEn":"Why does Carla want a different model?","optionsEn":["The old model was too loud.","The old model was too expensive.","The old model was too small."]},{"type":"tf","q":"Der silberne Wasserkocher ist am günstigsten.","a":true,"why":"","qEn":"The silver kettle is the cheapest."},{"type":"mc","q":"Wie viel bezahlt Carla heute?","options":["nichts","zehn Franken","neunundvierzig Franken"],"a":1,"qEn":"How much does Carla pay today?","optionsEn":["nothing","ten francs","forty-nine francs"]}],"titleEn":"A broken kettle","introS":[["Carla hat letzte Woche einen Wasserkocher gekauft.","Carla bought a kettle last week.",0],["Jetzt ist sie wieder im Geschäft.","Now she's back in the shop.",0]]},"grammar":{"title":"Adjektivendungen, Komparativ und Superlativ","summary":"Vor einem Nomen braucht das Adjektiv eine Endung.","sections":[{"h":"Adjektiv mit oder ohne Endung?","text":"Nach **sein, werden, bleiben** hat das Adjektiv **keine Endung**: *Der Wasserkocher ist neu.*\n**Vor** einem Nomen hat es immer eine Endung: *der neu==e== Wasserkocher, ein neu==er== Wasserkocher.*","hEn":"Adjective with or without an ending?","textP":[[["Nach **sein, werden, bleiben** hat das Adjektiv **keine Endung**: *Der Wasserkocher ist neu.*","After sein, werden, bleiben the adjective has no ending: The kettle is new.",0],["**Vor** einem Nomen hat es immer eine Endung: *der neu==e== Wasserkocher, ein neu==er== Wasserkocher.*","Before a noun it always has an ending: the new kettle, a new kettle.",1]]]},{"h":"Nach dem bestimmten Artikel (der, die, das, dieser …)","text":"Die Regel ist einfach: **-e** im Nominativ Singular und im Akkusativ bei *die* und *das*. Überall sonst: **-en**.","table":[["Kasus","maskulin","feminin","neutral","Plural"],["Nominativ","der neue Tisch","die neue Jacke","das neue Handy","die neuen Schuhe"],["Akkusativ","den neuen Tisch","die neue Jacke","das neue Handy","die neuen Schuhe"],["Dativ","dem neuen Tisch","der neuen Jacke","dem neuen Handy","den neuen Schuhen"]],"hEn":"After the definite article (der, die, das, dieser …)","textP":[[["Die Regel ist einfach: **-e** im Nominativ Singular und im Akkusativ bei *die* und *das*.","The rule is simple: -e in the nominative singular and in the accusative with die and das.",0],["Überall sonst: **-en**.","Everywhere else: -en.",0]]]},{"h":"Nach dem unbestimmten Artikel (ein, kein, mein …)","text":"Wenn der Artikel **keine Endung** hat (*ein Tisch, ein Handy*), zeigt das Adjektiv das Genus: **-er** (maskulin) und **-es** (neutral).","table":[["Kasus","maskulin","feminin","neutral","Plural"],["Nominativ","ein neuer Tisch","eine neue Jacke","ein neues Handy","keine neuen Schuhe"],["Akkusativ","einen neuen Tisch","eine neue Jacke","ein neues Handy","keine neuen Schuhe"],["Dativ","einem neuen Tisch","einer neuen Jacke","einem neuen Handy","keinen neuen Schuhen"]],"hEn":"After the indefinite article (ein, kein, mein …)","textP":[[["Wenn der Artikel **keine Endung** hat (*ein Tisch, ein Handy*), zeigt das Adjektiv das Genus: **-er** (maskulin) und **-es** (neutral).","When the article has no ending (ein Tisch, ein Handy), the adjective shows the gender: -er (masculine) and -es (neuter).",0]]]},{"h":"Vergleichen – Komparativ und Superlativ","text":"**Komparativ:** Adjektiv + **-er** (+ *als*). **Superlativ:** **am** + Adjektiv + **-sten**. Viele kurze Adjektive bekommen einen Umlaut.\nGleich ist: **so … wie** (*Die Jacke ist so teuer wie die Hose.*).","table":[["Grundform","Komparativ","Superlativ"],["schnell","schneller","am schnellsten"],["günstig","günstiger","am günstigsten"],["teuer","teurer","am teuersten"],["gross","grösser","am grössten"],["alt","älter","am ältesten"],["gut","besser","am besten"],["viel","mehr","am meisten"],["gern","lieber","am liebsten"],["hoch","höher","am höchsten"]],"examples":[{"de":"Der weisse Wasserkocher ist ==leiser als== der alte.","en":"The white kettle is quieter than the old one.","audio":"35dfd6042325"},{"de":"Der silberne ist ==am günstigsten==.","en":"The silver one is the cheapest.","audio":"e0762b90ed12"},{"de":"Ich trinke ==lieber== Tee ==als== Kaffee.","en":"I prefer tea to coffee.","audio":"430a14e449cb"}],"hEn":"Comparing – comparative and superlative","textP":[[["**Komparativ:** Adjektiv + **-er** (+ *als*).","Comparative: adjective + -er (+ als).",0],["**Superlativ:** **am** + Adjektiv + **-sten**.","Superlative: am + adjective + -sten.",0],["Viele kurze Adjektive bekommen einen Umlaut.","Many short adjectives take an umlaut.",0],["Gleich ist: **so … wie** (*Die Jacke ist so teuer wie die Hose.*).","For \"the same\": so … wie (The jacket is as expensive as the trousers.).",1]]]}],"tip":"Auch der Komparativ braucht vor dem Nomen eine Endung: ein kleiner==er== Wasserkocher, die günstiger==e== Jacke, das beste Angebot.","titleEn":"Adjective endings, comparative and superlative","summaryS":[["Vor einem Nomen braucht das Adjektiv eine Endung.","Before a noun, the adjective needs an ending.",0]],"tipP":[[["Auch der Komparativ braucht vor dem Nomen eine Endung: ein kleiner==er== Wasserkocher, die günstiger==e== Jacke, das beste Angebot.","The comparative also needs an ending before a noun: a smaller kettle, the cheaper jacket, the best offer.",0]]]},"exercises":[{"type":"choice","title":"Welche Endung ist richtig?","items":[{"q":"Ich möchte den ___ Wasserkocher zurückgeben.","options":["kaputten","kaputte","kaputter"],"a":0,"full":"Ich möchte den kaputten Wasserkocher zurückgeben.","audio":"57fc99c44b68","en":"I'd like to return the broken kettle."},{"q":"Haben Sie diese Jacke auch in einer ___ Grösse?","options":["kleineren","kleinere","kleiner"],"a":0,"full":"Haben Sie diese Jacke auch in einer kleineren Grösse?","audio":"ea0489cd30b1","en":"Do you also have this jacket in a smaller size?"},{"q":"Das ist ein sehr ___ Angebot!","options":["gutes","guter","gute"],"a":0,"full":"Das ist ein sehr gutes Angebot!","audio":"00e8ee6e5974","en":"That's a very good offer!"},{"q":"Die ___ Schuhe passen mir nicht.","options":["neuen","neue","neuer"],"a":0,"full":"Die neuen Schuhe passen mir nicht.","audio":"136859c4cf69","en":"The new shoes don't fit me."},{"q":"Ich suche einen ___ Tisch für meine Küche.","options":["runden","runder","runde"],"a":0,"full":"Ich suche einen runden Tisch für meine Küche.","audio":"cfd86636dfc2","en":"I'm looking for a round table for my kitchen."},{"q":"Er hat mit einer ___ Kreditkarte bezahlt.","options":["alten","alte","alter"],"a":0,"full":"Er hat mit einer alten Kreditkarte bezahlt.","audio":"44e6ab921a6d","en":"He paid with an old credit card."},{"q":"Wo ist die ___ Filiale?","options":["nächste","nächsten","nächster"],"a":0,"full":"Wo ist die nächste Filiale?","audio":"3f477ca6be92","en":"Where is the nearest branch?"},{"q":"Das ___ Handy ist leider schon kaputt.","options":["neue","neues","neuen"],"a":0,"full":"Das neue Handy ist leider schon kaputt.","audio":"922b24f8f06a","en":"Unfortunately the new phone is already broken."}],"titleEn":"Which ending is correct?"},{"type":"gap","title":"Komparativ oder Superlativ","items":[{"q":"Der weisse Wasserkocher ist ___ als der schwarze. (leise)","a":["leiser"],"full":"Der weisse Wasserkocher ist leiser als der schwarze.","audio":"24e1dd6c2789","en":"The white kettle is quieter than the black one."},{"q":"Im Internet ist es oft ___ als im Geschäft. (günstig)","a":["günstiger"],"full":"Im Internet ist es oft günstiger als im Geschäft.","audio":"ae324bce89e9","en":"It's often cheaper online than in the shop."},{"q":"Diese Jacke gefällt mir ___ als die blaue. (gut)","a":["besser"],"full":"Diese Jacke gefällt mir besser als die blaue.","audio":"a9798721a438","en":"I like this jacket better than the blue one."},{"q":"Welcher Supermarkt ist am ___? (billig)","a":["billigsten"],"full":"Welcher Supermarkt ist am billigsten?","audio":"f0fe05682d50","en":"Which supermarket is the cheapest?"},{"q":"Ich trinke ___ Tee als Kaffee. (gern)","a":["lieber"],"full":"Ich trinke lieber Tee als Kaffee.","audio":"430a14e449cb","en":"I prefer tea to coffee."},{"q":"Die Schuhe sind zu klein. Haben Sie sie eine Nummer ___? (gross)","a":["grösser"],"full":"Die Schuhe sind zu klein. Haben Sie sie eine Nummer grösser?","audio":"5ed52a17243f","en":"The shoes are too small. Do you have them a size bigger?"},{"q":"Zürich ist ___ als Winterthur. (teuer)","a":["teurer"],"full":"Zürich ist teurer als Winterthur.","audio":"2be5a5e9c00e","en":"Zurich is more expensive than Winterthur."}],"titleEn":"Comparative or superlative"},{"type":"order","title":"Bilden Sie Sätze","items":[{"a":["Ich möchte diese schwarze Hose umtauschen."],"tokens":["Ich","möchte","diese","schwarze","Hose","umtauschen."],"audio":"0410e991cac1","en":"I'd like to exchange these black trousers."},{"a":["Haben Sie den Pullover auch in einer anderen Farbe?"],"tokens":["Haben","Sie","den","Pullover","auch","in","einer","anderen","Farbe?"],"audio":"e50170d9f378","en":"Do you also have the sweater in a different colour?"},{"a":["Der neue Wasserkocher ist leiser als der alte."],"tokens":["Der","neue","Wasserkocher","ist","leiser","als","der","alte."],"audio":"f34d739762d4","en":"The new kettle is quieter than the old one."},{"a":["Kann ich die blaue Jacke anprobieren?"],"tokens":["Kann","ich","die","blaue","Jacke","anprobieren?"],"audio":"40d628e8f478","en":"Can I try on the blue jacket?"},{"a":["Das ist das günstigste Modell im Geschäft."],"tokens":["Das","ist","das","günstigste","Modell","im","Geschäft."],"audio":"6ae289939f31","en":"This is the cheapest model in the shop."}],"titleEn":"Make sentences"},{"type":"match","title":"Grundform und Komparativ","items":[{"l":"gut","r":"besser"},{"l":"viel","r":"mehr"},{"l":"gern","r":"lieber"},{"l":"hoch","r":"höher"},{"l":"teuer","r":"teurer"},{"l":"nah","r":"näher"},{"l":"gross","r":"grösser"},{"l":"alt","r":"älter"}],"titleEn":"Base form and comparative"},{"type":"dictation","title":"Diktat – hören und schreiben","items":[{"a":"Ich möchte diesen Wasserkocher umtauschen.","audio":"8ae493f84e5d","en":"I'd like to exchange this kettle."},{"a":"Haben Sie die Quittung dabei?","audio":"2c6ddde5231f","en":"Do you have the receipt with you?"},{"a":"Der neue Wasserkocher ist leiser als der alte.","audio":"23a3fd7a1f3c","en":"The new kettle is quieter than the old one."},{"a":"Die blauen Schuhe sind am günstigsten.","audio":"73ddb881ba29","en":"The blue shoes are the cheapest."}],"titleEn":"Dictation – listen and write"}],"reading":{"title":"Umtausch und Rückgabe – so einfach geht's","kind":"Aushang","paras":[{"t":"Sie sind mit einem Artikel nicht zufrieden? Kein Problem!","audio":"dec4b2062b97","s":[["Sie sind mit einem Artikel nicht zufrieden?","Not happy with an item?",0],["Kein Problem!","No problem!",0]]},{"t":"Ungebrauchte Artikel können Sie innerhalb von 30 Tagen in jeder Filiale umtauschen. Bitte bringen Sie die Quittung und die Originalverpackung mit.","audio":"2b3621d688e3","s":[["Ungebrauchte Artikel können Sie innerhalb von 30 Tagen in jeder Filiale umtauschen.","You can exchange unused items within 30 days at any branch.",0],["Bitte bringen Sie die Quittung und die Originalverpackung mit.","Please bring the receipt and the original packaging.",0]]},{"t":"Ihr Geld bekommen Sie nur bei defekten Artikeln zurück. Für ungebrauchte Artikel bekommen Sie einen Gutschein.","audio":"62d4c91a458a","s":[["Ihr Geld bekommen Sie nur bei defekten Artikeln zurück.","You only get your money back for faulty items.",0],["Für ungebrauchte Artikel bekommen Sie einen Gutschein.","For unused items you get a voucher.",0]]},{"t":"Alle Elektrogeräte haben zwei Jahre Garantie. Wenn ein Gerät in dieser Zeit kaputtgeht, reparieren wir es kostenlos, oder Sie bekommen ein neues Gerät.","audio":"2a21629da867","s":[["Alle Elektrogeräte haben zwei Jahre Garantie.","All electrical appliances have a two-year warranty.",0],["Wenn ein Gerät in dieser Zeit kaputtgeht, reparieren wir es kostenlos, oder Sie bekommen ein neues Gerät.","If an appliance breaks during this time, we'll repair it free of charge, or you'll get a new appliance.",0]]},{"t":"Reduzierte Artikel aus unseren Aktionen können Sie leider nicht umtauschen.","audio":"3850cf5b98ce","s":[["Reduzierte Artikel aus unseren Aktionen können Sie leider nicht umtauschen.","Unfortunately you can't exchange reduced items from our special offers.",0]]},{"t":"Online gekaufte Artikel können Sie per Post zurückschicken oder in einer Filiale abgeben. Die Rücksendung ist gratis.","audio":"60f0ddf31e08","s":[["Online gekaufte Artikel können Sie per Post zurückschicken oder in einer Filiale abgeben.","You can send items bought online back by post or drop them off at a branch.",0],["Die Rücksendung ist gratis.","Returns are free.",0]]},{"t":"Haben Sie Fragen? Unser Kundendienst ist von Montag bis Samstag von 8 bis 18 Uhr per Telefon und im Chat für Sie da.","audio":"0be0b7eb28c7","s":[["Haben Sie Fragen?","Any questions?",0],["Unser Kundendienst ist von Montag bis Samstag von 8 bis 18 Uhr per Telefon und im Chat für Sie da.","Our customer service is there for you by phone and chat from Monday to Saturday, 8 a.m. to 6 p.m.",0]]}],"glossary":[{"de":"ungebraucht","en":"unused"},{"de":"innerhalb von","en":"within"},{"de":"defekt","en":"faulty"},{"de":"reduziert","en":"reduced (price)"},{"de":"abgeben","en":"to hand in, drop off"},{"de":"die Rücksendung","en":"return shipment"}],"questions":[{"type":"tf","q":"Ungebrauchte Artikel kann man innerhalb von 30 Tagen umtauschen.","a":true,"why":"","qEn":"You can exchange unused items within 30 days."},{"type":"mc","q":"Was braucht man für den Umtausch?","options":["nur die Quittung","die Quittung und die Originalverpackung","einen Gutschein"],"a":1,"qEn":"What do you need for an exchange?","optionsEn":["only the receipt","the receipt and the original packaging","a voucher"]},{"type":"mc","q":"Sie bringen einen ungebrauchten Pullover zurück. Was bekommen Sie?","options":["Ihr Geld","einen Gutschein","nichts"],"a":1,"qEn":"You bring back an unused sweater. What do you get?","optionsEn":["your money","a voucher","nothing"]},{"type":"tf","q":"Artikel aus einer Aktion kann man nicht umtauschen.","a":true,"why":"","qEn":"You can't exchange items from a special offer."},{"type":"tf","q":"Die Rücksendung per Post kostet zehn Franken.","a":false,"why":"Die Rücksendung ist gratis.","qEn":"Returning by post costs ten francs.","whyEn":"Returns are free."}],"titleEn":"Exchanges and returns – it's that easy"},"writing":{"task":"Sie haben online eine Jacke bestellt. Sie ist zu klein, und die Farbe ist anders als auf dem Foto. Schreiben Sie an den Kundendienst (60–80 Wörter).","points":["Was haben Sie wann bestellt?","Was ist das Problem?","Was möchten Sie? (umtauschen oder Geld zurück)","Fragen Sie, wie Sie die Jacke zurückschicken können."],"phrases":[{"de":"Am … habe ich bei Ihnen … bestellt.","en":"On … I ordered … from you."},{"de":"Leider gibt es ein Problem mit …","en":"Unfortunately there's a problem with …"},{"de":"Ich möchte … gegen … umtauschen.","en":"I'd like to exchange … for …"},{"de":"Falls das nicht möglich ist, …","en":"If that's not possible, …"},{"de":"Können Sie mir bitte sagen, wie …?","en":"Could you please tell me how …?"}],"model":"Sehr geehrte Damen und Herren\n\nAm 3. Oktober habe ich bei Ihnen eine blaue Winterjacke in Grösse M bestellt. Leider gibt es zwei Probleme: Die Jacke ist zu klein, und die Farbe ist viel dunkler als auf dem Foto. Ich möchte die Jacke gerne gegen eine grössere Jacke in Grösse L umtauschen. Falls das nicht möglich ist, möchte ich mein Geld zurück. Können Sie mir bitte sagen, wie ich die Jacke zurückschicken kann?\n\nFreundliche Grüsse\nCarla Ferreira","audio":"af2f6eaf67e9","taskS":[["Sie haben online eine Jacke bestellt.","You ordered a jacket online.",0],["Sie ist zu klein, und die Farbe ist anders als auf dem Foto.","It's too small, and the colour is different from the photo.",0],["Schreiben Sie an den Kundendienst (60–80 Wörter).","Write to customer service (60–80 words).",0]],"pointsEn":["What did you order and when?","What's the problem?","What would you like? (exchange or money back)","Ask how you can send the jacket back."],"modelP":[[["Sehr geehrte Damen und Herren","Dear Sir or Madam",0]],[["Am 3. Oktober habe ich bei Ihnen eine blaue Winterjacke in Grösse M bestellt.","On 3 October I ordered a blue winter jacket in size M from you.",0],["Leider gibt es zwei Probleme: Die Jacke ist zu klein, und die Farbe ist viel dunkler als auf dem Foto.","Unfortunately there are two problems: the jacket is too small, and the colour is much darker than in the photo.",0],["Ich möchte die Jacke gerne gegen eine grössere Jacke in Grösse L umtauschen.","I would like to exchange the jacket for a bigger one in size L.",0],["Falls das nicht möglich ist, möchte ich mein Geld zurück.","If that's not possible, I would like my money back.",0],["Können Sie mir bitte sagen, wie ich die Jacke zurückschicken kann?","Could you please tell me how I can send the jacket back?",0]],[["Freundliche Grüsse","Kind regards",0],["Carla Ferreira","Carla Ferreira",1]]]},"speaking":{"task":"Im Kleidergeschäft – antworten Sie der Verkäuferin. Vergleichen Sie die Produkte.","phrases":[{"de":"Ich suche …","en":"I'm looking for …","audio":null},{"de":"Haben Sie das auch in Grösse …?","en":"Do you have this in size …?","audio":null},{"de":"Kann ich das anprobieren?","en":"Can I try it on?","audio":"ddc16d2100d6"},{"de":"Das ist mir zu teuer.","en":"That's too expensive for me.","audio":"e12d5b5dc47d"},{"de":"Ich nehme lieber …","en":"I'd rather take …","audio":null}],"prompts":[{"q":"Guten Tag, kann ich Ihnen helfen?","model":"Ja, gerne. Ich suche eine warme Jacke für den Winter.","aq":"399b1ed10c96","am":"45870c242d12","qS":[["Guten Tag, kann ich Ihnen helfen?","Hello, can I help you?",0]],"modelS":[["Ja, gerne.","Yes, please.",0],["Ich suche eine warme Jacke für den Winter.","I'm looking for a warm jacket for the winter.",0]]},{"q":"Welche Farbe möchten Sie?","model":"Am liebsten eine dunkle Farbe, zum Beispiel dunkelblau oder schwarz.","aq":"4c1e3be3f12f","am":"28ba636480c7","qS":[["Welche Farbe möchten Sie?","Which colour would you like?",0]],"modelS":[["Am liebsten eine dunkle Farbe, zum Beispiel dunkelblau oder schwarz.","Preferably a dark colour, for example dark blue or black.",0]]},{"q":"Wie gefällt Ihnen diese Jacke hier?","model":"Sie gefällt mir gut, aber sie ist ein bisschen zu gross. Haben Sie sie eine Nummer kleiner?","aq":"d14116e4a3a1","am":"92ce0b770f38","qS":[["Wie gefällt Ihnen diese Jacke hier?","How do you like this jacket here?",0]],"modelS":[["Sie gefällt mir gut, aber sie ist ein bisschen zu gross.","I like it, but it's a bit too big.",0],["Haben Sie sie eine Nummer kleiner?","Do you have it a size smaller?",0]]},{"q":"Diese kostet hundertneunzig Franken. Die andere hier ist günstiger.","model":"Die günstigere Jacke ist aber nicht so warm. Ich nehme lieber die teurere, die ist besser für den Winter.","aq":"02c1856a74e8","am":"905baf4b9a69","qS":[["Diese kostet hundertneunzig Franken.","This one costs one hundred and ninety francs.",0],["Die andere hier ist günstiger.","The other one here is cheaper.",0]],"modelS":[["Die günstigere Jacke ist aber nicht so warm.","But the cheaper jacket isn't as warm.",0],["Ich nehme lieber die teurere, die ist besser für den Winter.","I'd rather take the more expensive one, it's better for the winter.",0]]}],"taskS":[["Im Kleidergeschäft – antworten Sie der Verkäuferin.","In the clothes shop – answer the shop assistant.",0],["Vergleichen Sie die Produkte.","Compare the products.",0]]},"en":{"title":"Shopping and making complaints","subtitle":"Comparing products, exchanging, complaining","focus":"Adjective endings, comparative and superlative"}},{"id":5,"title":"Mit Bahn und Bus","subtitle":"Auskunft am Bahnhof, Durchsagen verstehen","level":"A2","theme":"Mobilität","focus":"Wechselpräpositionen und indirekte Fragen","goals":[{"de":"Ich kann am Bahnhof Informationen über Verbindungen und Billette erfragen.","en":"I can ask for information about connections and tickets at the station."},{"de":"Ich kann Durchsagen und Informationen zu Verspätungen verstehen.","en":"I can understand announcements and information about delays."},{"de":"Ich kann höflich fragen (Können Sie mir sagen, …?).","en":"I can ask politely (Could you tell me …?)."}],"vocab":[{"id":"5-0","de":"der Fahrplan","forms":"Fahrpläne","en":"timetable","ex":"Ich schaue kurz im Fahrplan nach.","exEn":"I'll quickly check the timetable.","aw":"f50e513db3bf","ae":"a0e375b88e86"},{"id":"5-1","de":"das Billett","forms":"-e","en":"ticket (CH)","ex":"Ich habe mein Billett in der App gekauft.","exEn":"I bought my ticket in the app.","aw":"e9bf0d3f1f5d","ae":"c9c45565e377"},{"id":"5-2","de":"das Halbtax","forms":"–","en":"half-fare card (CH)","ex":"Mit dem Halbtax bezahlt man nur die Hälfte.","exEn":"With the half-fare card you only pay half.","aw":"4fe4fe8612ea","ae":"d1dda17e75a2"},{"id":"5-3","de":"das Gleis","forms":"-e","en":"track, platform number","ex":"Der Zug fährt auf Gleis sieben ab.","exEn":"The train leaves from platform seven.","aw":"8e9415ffed2f","ae":"7ebf45b68228"},{"id":"5-4","de":"umsteigen","forms":"ist umgestiegen","en":"to change (trains, buses)","ex":"Sie müssen in Zürich umsteigen.","exEn":"You have to change in Zurich.","aw":"2fad214349ff","ae":"55f98269fb3b"},{"id":"5-5","de":"einsteigen","forms":"ist eingestiegen","en":"to get on","ex":"Bitte schnell einsteigen, der Zug fährt gleich ab!","exEn":"Please get on quickly, the train is about to leave!","aw":"4b9f026e9fe4","ae":"8127ee3c329f"},{"id":"5-6","de":"aussteigen","forms":"ist ausgestiegen","en":"to get off","ex":"Wir steigen an der nächsten Haltestelle aus.","exEn":"We're getting off at the next stop.","aw":"4477f115d13b","ae":"f12b0a4b5762"},{"id":"5-7","de":"die Verspätung","forms":"-en","en":"delay","ex":"Der Zug hat zehn Minuten Verspätung.","exEn":"The train is ten minutes late.","aw":"e75832564656","ae":"828402f14cf7"},{"id":"5-8","de":"der Anschluss","forms":"Anschlüsse","en":"connection","ex":"Ich habe meinen Anschluss verpasst.","exEn":"I missed my connection.","aw":"40bc0c9a2554","ae":"6f94ebb9bcfe"},{"id":"5-9","de":"verpassen","forms":"hat verpasst","en":"to miss","ex":"Beeil dich, sonst verpassen wir den Bus!","exEn":"Hurry up, or we'll miss the bus!","aw":"08a8cdaa58e9","ae":"fd5507d34de8"},{"id":"5-10","de":"die Haltestelle","forms":"-n","en":"(bus/tram) stop","ex":"Die Haltestelle ist direkt vor dem Haus.","exEn":"The stop is right in front of the building.","aw":"badf438d7ec7","ae":"4f9e237399ac"},{"id":"5-11","de":"die Durchsage","forms":"-n","en":"announcement","ex":"Hast du die Durchsage verstanden?","exEn":"Did you understand the announcement?","aw":"ee12fe7537bc","ae":"3d7cef6a1362"},{"id":"5-12","de":"die Richtung","forms":"-en","en":"direction","ex":"Nehmen Sie den Bus in Richtung Bahnhof.","exEn":"Take the bus towards the station.","aw":"46652beedb79","ae":"4ce628a3c390"},{"id":"5-13","de":"hin und zurück","forms":"–","en":"return (ticket)","ex":"Einmal nach Luzern, hin und zurück, bitte.","exEn":"One return to Lucerne, please.","aw":"e7aaa53ebd9f","ae":"1dec01cc6ffc"},{"id":"5-14","de":"ausfallen","forms":"ist ausgefallen","en":"to be cancelled","ex":"Der Zug fällt heute wegen Bauarbeiten aus.","exEn":"The train is cancelled today due to construction work.","aw":"324a96a61b20","ae":"391bf3c1e923"},{"id":"5-15","de":"der Ersatzbus","forms":"-se","en":"replacement bus","ex":"Zwischen Winterthur und Frauenfeld fahren Ersatzbusse.","exEn":"Replacement buses run between Winterthur and Frauenfeld.","aw":"cfd25b828c6a","ae":"c4e615a90a17"},{"id":"5-16","de":"das Velo","forms":"-s","en":"bicycle (CH)","ex":"Ich fahre jeden Tag mit dem Velo zur Arbeit.","exEn":"I cycle to work every day.","aw":"07b8869be926","ae":"e467d208add7"},{"id":"5-17","de":"sich auskennen","forms":"hat sich ausgekannt","en":"to know your way around","ex":"Ich kenne mich in Bern noch nicht gut aus.","exEn":"I don't know my way around Bern well yet.","aw":"d4f5be780982","ae":"8a9a94a35191"},{"id":"5-18","de":"die Auskunft","forms":"Auskünfte","en":"information","ex":"Vielen Dank für die Auskunft!","exEn":"Thank you for the information!","aw":"9c832a33ba05","ae":"538624184106"},{"id":"5-19","de":"der Automat","forms":"-en","en":"(ticket) machine","ex":"Der Automat nimmt leider keine Karten.","exEn":"Unfortunately the machine doesn't take cards.","aw":"98885f322199","ae":"a1e1845c029b"}],"swiss":[{"ch":"das Billett","std":"die Fahrkarte","en":"ticket"},{"ch":"der Perron","std":"der Bahnsteig","en":"platform"},{"ch":"das Velo","std":"das Fahrrad","en":"bicycle"},{"ch":"das Halbtax","std":"–","en":"half-fare card – you pay about half on trains, buses and boats"},{"ch":"das GA","std":"–","en":"Generalabonnement – unlimited travel on almost all Swiss public transport"}],"dialogue":{"title":"Im Reisezentrum","intro":"Carla möchte am Samstag nach Luzern fahren. Sie fragt im Reisezentrum am Bahnhof Winterthur nach.","speakers":{"F":"Carla","M":"Mitarbeiter"},"lines":[{"s":"M","de":"Guten Tag, wie kann ich Ihnen helfen?","en":"Hello, how can I help you?","audio":"4ab24536a912"},{"s":"F","de":"Guten Tag. Ich möchte am Samstag nach Luzern fahren. Können Sie mir sagen, wann die Züge fahren?","en":"Hello. I'd like to go to Lucerne on Saturday. Could you tell me when the trains run?","audio":"d62906c8ebb7"},{"s":"M","de":"Gerne. Am Samstag fährt jede halbe Stunde ein Zug, zum Beispiel um 8.32 Uhr. Sie müssen in Zürich umsteigen.","en":"Sure. On Saturday there's a train every half hour, for example at 8:32. You have to change in Zurich.","audio":"3dcf493002e0"},{"s":"F","de":"Und wissen Sie, wie lange die Fahrt dauert?","en":"And do you know how long the journey takes?","audio":"fcfd9bfbb041"},{"s":"M","de":"Ungefähr eine Stunde und zwanzig Minuten.","en":"About one hour and twenty minutes.","audio":"96dd1f00ed9c"},{"s":"F","de":"Was kostet ein Billett hin und zurück?","en":"How much is a return ticket?","audio":"f5c61148147c"},{"s":"M","de":"Haben Sie ein Halbtax?","en":"Do you have a half-fare card?","audio":"02c5a89699c5"},{"s":"F","de":"Nein, noch nicht. Ich weiss nicht, ob sich das für mich lohnt.","en":"No, not yet. I don't know if it's worth it for me.","audio":"673420d864f2"},{"s":"M","de":"Wenn Sie oft mit dem Zug fahren, lohnt es sich bestimmt. Ohne Halbtax kostet das Billett etwa achtzig Franken, mit Halbtax nur die Hälfte.","en":"If you often travel by train, it's definitely worth it. Without a half-fare card the ticket costs about eighty francs, with it only half.","audio":"2b0fffd3851b"},{"s":"F","de":"Dann kaufe ich heute ein Halbtax. Und kann ich mein Velo in den Zug mitnehmen?","en":"Then I'll buy a half-fare card today. And can I take my bike on the train?","audio":"49e7065f9a2e"},{"s":"M","de":"Ja, aber Sie brauchen ein Velobillett. Stellen Sie das Velo bitte in den Wagen mit dem Velo-Symbol.","en":"Yes, but you need a bike ticket. Please put the bike in the carriage with the bike symbol.","audio":"37f7fbf728be"},{"s":"F","de":"Und wo finde ich diesen Wagen?","en":"And where do I find this carriage?","audio":"3c6f1e117e2a"},{"s":"M","de":"Der ist meistens am Anfang oder am Ende des Zuges. Auf dem Perron gibt es eine Anzeige.","en":"It's usually at the front or the back of the train. There's a display on the platform.","audio":"7b5697476234"},{"s":"F","de":"Super, vielen Dank für die Auskunft!","en":"Great, thank you very much for the information!","audio":"67eb5cfde9e7"},{"s":"M","de":"Gern geschehen. Gute Reise!","en":"You're welcome. Have a good trip!","audio":"7473d7ca9b2c"}],"questions":[{"type":"tf","q":"Carla muss in Zürich umsteigen.","a":true,"why":"","qEn":"Carla has to change in Zurich."},{"type":"mc","q":"Wie oft fährt am Samstag ein Zug nach Luzern?","options":["jede Stunde","jede halbe Stunde","alle zehn Minuten"],"a":1,"qEn":"How often is there a train to Lucerne on Saturday?","optionsEn":["every hour","every half hour","every ten minutes"]},{"type":"mc","q":"Wie viel kostet das Billett mit Halbtax ungefähr?","options":["achtzig Franken","vierzig Franken","zwanzig Franken"],"a":1,"qEn":"About how much does the ticket cost with a half-fare card?","optionsEn":["eighty francs","forty francs","twenty francs"]},{"type":"tf","q":"Für das Velo braucht man kein Billett.","a":false,"why":"Man braucht ein Velobillett.","qEn":"You don't need a ticket for the bike.","whyEn":"You need a bike ticket."},{"type":"mc","q":"Wo sieht man, wo der Velowagen ist?","options":["auf dem Perron","im Reisezentrum","im Zug"],"a":0,"qEn":"Where can you see where the bike carriage is?","optionsEn":["on the platform","at the travel centre","on the train"]}],"titleEn":"At the travel centre","introS":[["Carla möchte am Samstag nach Luzern fahren.","Carla wants to go to Lucerne on Saturday.",0],["Sie fragt im Reisezentrum am Bahnhof Winterthur nach.","She asks at the travel centre at Winterthur station.",0]]},"grammar":{"title":"Wechselpräpositionen und indirekte Fragen","summary":"Wo? → Dativ. Wohin? → Akkusativ.","sections":[{"h":"Neun Präpositionen mit zwei Kasus","text":"**an, auf, hinter, in, neben, über, unter, vor, zwischen** können mit Dativ oder Akkusativ stehen.\n**Wo?** (Position, keine Bewegung zu einem Ziel) → **Dativ**. **Wohin?** (Richtung, Bewegung zu einem Ziel) → **Akkusativ**.","table":[["Wo? (Dativ)","Wohin? (Akkusativ)"],["Das Velo steht ==im== Wagen.","Ich stelle das Velo ==in den== Wagen."],["Wir warten ==auf dem== Perron.","Wir gehen ==auf den== Perron."],["Die Tasche liegt ==unter dem== Sitz.","Ich lege die Tasche ==unter den== Sitz."],["Die Jacke hängt ==an der== Tür.","Ich hänge die Jacke ==an die== Tür."],["Sie sitzt ==neben dem== Fenster.","Sie setzt sich ==neben das== Fenster."]],"hEn":"Nine prepositions with two cases","textP":[[["**an, auf, hinter, in, neben, über, unter, vor, zwischen** können mit Dativ oder Akkusativ stehen.","an, auf, hinter, in, neben, über, unter, vor, zwischen can be used with the dative or the accusative.",0],["**Wo?** (Position, keine Bewegung zu einem Ziel) → **Dativ**.","Where? (position, no movement towards a destination) → dative.",1],["**Wohin?** (Richtung, Bewegung zu einem Ziel) → **Akkusativ**.","Where to? (direction, movement towards a destination) → accusative.",0]]]},{"h":"Die Artikel","text":"Kurzformen: **in dem → im, in das → ins, an dem → am, an das → ans**.","table":[["Nominativ","Dativ (wo?)","Akkusativ (wohin?)"],["der Zug","in dem (= im) Zug","in den Zug"],["die Stadt","in der Stadt","in die Stadt"],["das Kino","in dem (= im) Kino","in das (= ins) Kino"],["die Busse (Pl.)","in den Bussen","in die Busse"]],"hEn":"The articles","textP":[[["Kurzformen: **in dem → im, in das → ins, an dem → am, an das → ans**.","Short forms: in dem → im, in das → ins, an dem → am, an das → ans.",0]]]},{"h":"Verbpaare – Position und Bewegung","text":"Hinweis: In der Schweiz und in Süddeutschland sagt man *ist gestanden, ist gelegen, ist gesessen*; in Norddeutschland *hat gestanden* usw.","table":[["Wo? + Dativ","Wohin? + Akkusativ"],["stehen (ist gestanden)","stellen (hat gestellt)"],["liegen (ist gelegen)","legen (hat gelegt)"],["hängen (ist gehangen)","hängen (hat gehängt)"],["sitzen (ist gesessen)","sich setzen (hat sich gesetzt)"]],"hEn":"Verb pairs – position and movement","textP":[[["Hinweis: In der Schweiz und in Süddeutschland sagt man *ist gestanden, ist gelegen, ist gesessen*; in Norddeutschland *hat gestanden* usw.","Note: In Switzerland and southern Germany people say ist gestanden, ist gelegen, ist gesessen; in northern Germany hat gestanden etc.",0]]]},{"h":"Indirekte Fragen – höflich fragen","text":"Mit **Können Sie mir sagen, …? / Wissen Sie, …? / Ich möchte wissen, …** wird eine Frage höflicher. Die Frage wird ein Nebensatz: Das Verb geht ans **Ende**.\nW-Frage → W-Wort bleibt. Ja/Nein-Frage → **ob**.","examples":[{"de":"Wann ==fährt== der Zug? → Können Sie mir sagen, wann der Zug ==fährt==?","en":"When does the train leave? → Could you tell me when the train leaves?","audio":"fd93b4f3397b"},{"de":"Muss ich umsteigen? → Wissen Sie, ==ob== ich umsteigen ==muss==?","en":"Do I have to change? → Do you know whether I have to change?","audio":"ce109030cefd"},{"de":"Wo ist der Automat? → Ich möchte wissen, wo der Automat ==ist==.","en":"Where is the machine? → I'd like to know where the machine is.","audio":"b3a6268181dc"}],"hEn":"Indirect questions – asking politely","textP":[[["Mit **Können Sie mir sagen, …? / Wissen Sie, …? / Ich möchte wissen, …** wird eine Frage höflicher.","With Können Sie mir sagen, …? / Wissen Sie, …? / Ich möchte wissen, … a question becomes more polite.",0],["Die Frage wird ein Nebensatz: Das Verb geht ans **Ende**.","The question becomes a subordinate clause: the verb goes to the end.",0],["W-Frage → W-Wort bleibt.","W-question → the question word stays.",1],["Ja/Nein-Frage → **ob**.","Yes/no question → ob.",0]]]}],"tip":"Nicht alle Bewegungen brauchen den Akkusativ: „Ich fahre ==im== Zug nach Bern.\" Man bewegt sich, aber im Zug – der Zug ist kein Ziel.","titleEn":"Two-way prepositions and indirect questions","summaryS":[["Wo? → Dativ.","Where? → dative.",0],["Wohin? → Akkusativ.","Where to? → accusative.",0]],"tipP":[[["Nicht alle Bewegungen brauchen den Akkusativ: „Ich fahre ==im== Zug nach Bern.\"","Not every movement needs the accusative: \"I'm travelling to Bern on the train.\"",0],["Man bewegt sich, aber im Zug – der Zug ist kein Ziel.","You are moving, but inside the train – the train isn't a destination.",0]]]},"exercises":[{"type":"choice","title":"Dativ oder Akkusativ?","items":[{"q":"Der Zug steht schon auf ___ Gleis.","options":["dem","das"],"a":0,"full":"Der Zug steht schon auf dem Gleis.","audio":"339d481a0b00","en":"The train is already on the track."},{"q":"Ich stelle mein Velo in ___ Velowagen.","options":["den","dem"],"a":0,"full":"Ich stelle mein Velo in den Velowagen.","audio":"afe9fda11eff","en":"I'm putting my bike in the bike carriage."},{"q":"Wir warten vor ___ Bahnhof auf dich.","options":["dem","den"],"a":0,"full":"Wir warten vor dem Bahnhof auf dich.","audio":"6b744823bc93","en":"We'll wait for you in front of the station."},{"q":"Leg deine Tasche bitte unter ___ Sitz.","options":["den","dem"],"a":0,"full":"Leg deine Tasche bitte unter den Sitz.","audio":"29b06b7e4c0d","en":"Please put your bag under the seat."},{"q":"Das Billett ist in ___ App.","options":["der","die"],"a":0,"full":"Das Billett ist in der App.","audio":"253596126684","en":"The ticket is in the app."},{"q":"Er setzt sich neben ___ Fenster.","options":["das","dem"],"a":0,"full":"Er setzt sich neben das Fenster.","audio":"12f76bd4dc7f","en":"He sits down next to the window."},{"q":"Die Haltestelle ist zwischen ___ Post und ___ Bank.","options":["der … der","die … die"],"a":0,"full":"Die Haltestelle ist zwischen der Post und der Bank.","audio":"7648f24509ce","en":"The stop is between the post office and the bank."},{"q":"Am Sonntag fahren wir an ___ See.","options":["den","dem"],"a":0,"full":"Am Sonntag fahren wir an den See.","audio":"ad07c7476777","en":"On Sunday we're going to the lake."}],"titleEn":"Dative or accusative?"},{"type":"gap","title":"Präposition und Artikel","items":[{"q":"Ich gehe heute Abend ___ Kino. (in + das)","a":["ins"],"full":"Ich gehe heute Abend ins Kino.","audio":"1b06f412bf90","en":"I'm going to the cinema this evening."},{"q":"Der Bus wartet ___ Bahnhof. (an + dem)","a":["am"],"full":"Der Bus wartet am Bahnhof.","audio":"b6cb890bae41","en":"The bus is waiting at the station."},{"q":"Wir treffen uns ___ Perron sieben. (auf + der)","a":["auf dem"],"full":"Wir treffen uns auf dem Perron sieben.","audio":"b61eaeda78c3","en":"Let's meet on platform seven."},{"q":"Carla steigt ___ Zug nach Bern. (in + der)","a":["in den"],"full":"Carla steigt in den Zug nach Bern.","audio":"f7375e1fcc4a","en":"Carla gets on the train to Bern."},{"q":"Das Velo steht ___ Haus. (hinter + das)","a":["hinter dem"],"full":"Das Velo steht hinter dem Haus.","audio":"5811ad2996fb","en":"The bike is behind the house."},{"q":"Ich hänge die Jacke ___ Haken. (an + der)","a":["an den"],"full":"Ich hänge die Jacke an den Haken.","audio":"d882d9490591","en":"I hang the jacket on the hook."}],"titleEn":"Preposition and article"},{"type":"gap","title":"Indirekte Fragen – ergänzen Sie","items":[{"q":"Fährt der Bus zum Spital? → Wissen Sie, ___ der Bus zum Spital fährt?","a":["ob"],"full":"Wissen Sie, ob der Bus zum Spital fährt?","audio":"2fdc68385695","en":"Do you know whether the bus goes to the hospital?"},{"q":"Wann kommt der Zug an? → Können Sie mir sagen, wann der Zug ___?","a":["ankommt"],"full":"Können Sie mir sagen, wann der Zug ankommt?","audio":"4bb0f0d9a046","en":"Could you tell me when the train arrives?"},{"q":"Wo ist der Billettautomat? → Wissen Sie, wo der Billettautomat ___?","a":["ist"],"full":"Wissen Sie, wo der Billettautomat ist?","audio":"258e86fd4da1","en":"Do you know where the ticket machine is?"},{"q":"Muss ich umsteigen? → Ich möchte wissen, ob ich umsteigen ___.","a":["muss"],"full":"Ich möchte wissen, ob ich umsteigen muss.","audio":"8d93422ae651","en":"I'd like to know whether I have to change."},{"q":"Wie lange dauert die Fahrt? → Können Sie mir sagen, wie lange die Fahrt ___?","a":["dauert"],"full":"Können Sie mir sagen, wie lange die Fahrt dauert?","audio":"878745167cf0","en":"Could you tell me how long the journey takes?"}],"titleEn":"Indirect questions – fill in the gaps"},{"type":"order","title":"Bilden Sie höfliche Fragen","items":[{"a":["Können Sie mir sagen, wann der nächste Zug fährt?"],"tokens":["Können","Sie","mir","sagen,","wann","der","nächste","Zug","fährt?"],"audio":"a43b811bcf11","en":"Could you tell me when the next train leaves?"},{"a":["Wissen Sie, ob der Zug Verspätung hat?"],"tokens":["Wissen","Sie,","ob","der","Zug","Verspätung","hat?"],"audio":"70b4f836d863","en":"Do you know whether the train is delayed?"},{"a":["Ich möchte wissen, wie viel das Billett kostet."],"tokens":["Ich","möchte","wissen,","wie","viel","das","Billett","kostet."],"audio":"bccca7e214d2","en":"I'd like to know how much the ticket costs."},{"a":["Können Sie mir sagen, wo ich umsteigen muss?"],"tokens":["Können","Sie","mir","sagen,","wo","ich","umsteigen","muss?"],"audio":"a0b00eeaccc4","en":"Could you tell me where I have to change?"},{"a":["Weisst du, auf welchem Gleis der Zug abfährt?"],"tokens":["Weisst","du,","auf","welchem","Gleis","der","Zug","abfährt?"],"audio":"b250e16e4389","en":"Do you know which platform the train leaves from?"}],"titleEn":"Make polite questions"},{"type":"dictation","title":"Diktat – hören und schreiben","items":[{"a":"Können Sie mir sagen, wann der Zug nach Luzern fährt?","audio":"d9c4bc027105","en":"Could you tell me when the train to Lucerne leaves?"},{"a":"Wir müssen in Zürich umsteigen.","audio":"bc379785c363","en":"We have to change in Zurich."},{"a":"Der Zug hat zehn Minuten Verspätung.","audio":"61352497721a","en":"The train is ten minutes late."},{"a":"Ich stelle mein Velo in den Velowagen.","audio":"160494db6a50","en":"I'm putting my bike in the bike carriage."}],"titleEn":"Dictation – listen and write"}],"reading":{"title":"Durchsagen und Informationen","kind":"Durchsagen","paras":[{"t":"**Durchsage am Bahnhof Winterthur**\nGleis 4: Der InterRegio nach Luzern, Abfahrt 8.32 Uhr, hat circa zehn Minuten Verspätung. Reisende nach Luzern: Ihr Anschlusszug in Zürich wartet.","audio":"ce4902a4e72a","s":[["**Durchsage am Bahnhof Winterthur**","Announcement at Winterthur station",0],["Gleis 4: Der InterRegio nach Luzern, Abfahrt 8.32 Uhr, hat circa zehn Minuten Verspätung.","Platform 4: The InterRegio to Lucerne, departing at 8:32, is about ten minutes late.",1],["Reisende nach Luzern: Ihr Anschlusszug in Zürich wartet.","Passengers to Lucerne: your connecting train in Zurich will wait.",0]]},{"t":"**Durchsage im Zug**\nNächster Halt: Zürich Hauptbahnhof. Bitte beachten Sie: Wegen Bauarbeiten fährt dieser Zug heute auf Gleis 16 ein. Der Zug nach Luzern fährt auf Gleis 8.","audio":"e7277163770e","s":[["**Durchsage im Zug**","Announcement on the train",0],["Nächster Halt: Zürich Hauptbahnhof.","Next stop: Zurich main station.",1],["Bitte beachten Sie: Wegen Bauarbeiten fährt dieser Zug heute auf Gleis 16 ein.","Please note: due to construction work, this train will arrive at platform 16 today.",0],["Der Zug nach Luzern fährt auf Gleis 8.","The train to Lucerne leaves from platform 8.",0]]},{"t":"**Information: Bauarbeiten zwischen Winterthur und Frauenfeld**\nVom 10. bis 12. Oktober fallen alle Züge zwischen Winterthur und Frauenfeld aus. Zwischen den beiden Bahnhöfen fahren Ersatzbusse. Die Busse fahren auf dem Bahnhofplatz ab, direkt vor dem Haupteingang. Bitte rechnen Sie mit 20 Minuten mehr Reisezeit. Velos dürfen Sie leider nicht in die Ersatzbusse mitnehmen.","audio":"6a2854d90f6a","s":[["**Information: Bauarbeiten zwischen Winterthur und Frauenfeld**","Information: construction work between Winterthur and Frauenfeld",0],["Vom 10. bis 12. Oktober fallen alle Züge zwischen Winterthur und Frauenfeld aus.","From 10 to 12 October, all trains between Winterthur and Frauenfeld are cancelled.",1],["Zwischen den beiden Bahnhöfen fahren Ersatzbusse.","Replacement buses run between the two stations.",0],["Die Busse fahren auf dem Bahnhofplatz ab, direkt vor dem Haupteingang.","The buses leave from the station square, right in front of the main entrance.",0],["Bitte rechnen Sie mit 20 Minuten mehr Reisezeit.","Please allow 20 minutes of extra travel time.",0],["Velos dürfen Sie leider nicht in die Ersatzbusse mitnehmen.","Unfortunately you can't take bikes on the replacement buses.",0]]}],"glossary":[{"de":"circa","en":"about, approximately"},{"de":"der Anschlusszug","en":"connecting train"},{"de":"wegen","en":"because of"},{"de":"die Bauarbeiten","en":"construction work"},{"de":"einfahren","en":"to pull in (train)"},{"de":"rechnen mit","en":"to expect, allow for"}],"questions":[{"type":"tf","q":"Der Zug nach Luzern hat ungefähr zehn Minuten Verspätung.","a":true,"why":"","qEn":"The train to Lucerne is about ten minutes late."},{"type":"mc","q":"Auf welchem Gleis kommt der Zug in Zürich an?","options":["Gleis 4","Gleis 8","Gleis 16"],"a":2,"qEn":"Which platform does the train arrive at in Zurich?","optionsEn":["Platform 4","Platform 8","Platform 16"]},{"type":"mc","q":"Was passiert vom 10. bis 12. Oktober?","options":["Die Züge fahren nur am Abend.","Es fahren Busse statt Züge.","Der Bahnhof ist geschlossen."],"a":1,"qEn":"What happens from 10 to 12 October?","optionsEn":["The trains only run in the evening.","Buses run instead of trains.","The station is closed."]},{"type":"tf","q":"Die Ersatzbusse fahren vor dem Haupteingang ab.","a":true,"why":"","qEn":"The replacement buses leave from in front of the main entrance."},{"type":"tf","q":"Man kann sein Velo in den Ersatzbus mitnehmen.","a":false,"why":"Velos darf man nicht mitnehmen.","qEn":"You can take your bike on the replacement bus.","whyEn":"You're not allowed to take bikes."}],"titleEn":"Announcements and information"},"writing":{"task":"Sie haben den Zug verpasst und kommen zu spät zu einem Treffen mit einer Freundin. Schreiben Sie ihr eine Nachricht (40–60 Wörter).","points":["Entschuldigen Sie sich.","Was ist passiert?","Wann kommen Sie an?","Wo können Sie sich treffen?"],"phrases":[{"de":"Es tut mir leid, aber …","en":"I'm sorry, but …"},{"de":"Ich habe den Zug verpasst, weil …","en":"I missed the train because …"},{"de":"Ich bin um … Uhr in …","en":"I'll be in … at …"},{"de":"Wartest du im/am …?","en":"Will you wait in/at …?"}],"model":"Hallo Nina\n\nEs tut mir leid, aber ich komme etwa eine halbe Stunde später! Mein Bus hatte Verspätung, und ich habe den Zug um 10 Uhr verpasst. Jetzt nehme ich den Zug um 10.32 Uhr und bin um 11.05 Uhr in Zürich. Wartest du im Café neben dem Bahnhof auf mich? Ich lade dich zum Kaffee ein!\n\nLiebe Grüsse\nCarla","audio":"3b5f96fdae8d","taskS":[["Sie haben den Zug verpasst und kommen zu spät zu einem Treffen mit einer Freundin.","You missed the train and will be late for a meeting with a friend.",0],["Schreiben Sie ihr eine Nachricht (40–60 Wörter).","Write her a message (40–60 words).",0]],"pointsEn":["Apologise.","What happened?","When will you arrive?","Where can you meet?"],"modelP":[[["Hallo Nina","Hi Nina",0]],[["Es tut mir leid, aber ich komme etwa eine halbe Stunde später!","I'm sorry, but I'll be about half an hour late!",0],["Mein Bus hatte Verspätung, und ich habe den Zug um 10 Uhr verpasst.","My bus was late, and I missed the 10 o'clock train.",0],["Jetzt nehme ich den Zug um 10.32 Uhr und bin um 11.05 Uhr in Zürich.","Now I'm taking the 10:32 train and will be in Zurich at 11:05.",0],["Wartest du im Café neben dem Bahnhof auf mich?","Will you wait for me in the café next to the station?",0],["Ich lade dich zum Kaffee ein!","I'll buy you a coffee!",0]],[["Liebe Grüsse","Love",0],["Carla","Carla",1]]]},"speaking":{"task":"Am Bahnhof – Sie hören eine Situation. Fragen Sie höflich mit einer indirekten Frage.","phrases":[{"de":"Entschuldigung, können Sie mir sagen, …?","en":"Excuse me, could you tell me …?","audio":null},{"de":"Wissen Sie, ob …?","en":"Do you know whether …?","audio":null},{"de":"Ich kenne mich hier leider nicht aus.","en":"Unfortunately I don't know my way around here.","audio":"548b3a5ec111"},{"de":"Einmal nach Bern, hin und zurück, bitte.","en":"One return to Bern, please.","audio":"ceddedac09f4"},{"de":"Wo muss ich umsteigen?","en":"Where do I have to change?","audio":"a9d2821c99e0"}],"prompts":[{"q":"Sie möchten wissen, wann der letzte Zug nach Winterthur fährt.","model":"Entschuldigung, können Sie mir sagen, wann der letzte Zug nach Winterthur fährt?","aq":"f5dcab55c83c","am":"3ae7d40139dc","qS":[["Sie möchten wissen, wann der letzte Zug nach Winterthur fährt.","You want to know when the last train to Winterthur leaves.",0]],"modelS":[["Entschuldigung, können Sie mir sagen, wann der letzte Zug nach Winterthur fährt?","Excuse me, could you tell me when the last train to Winterthur leaves?",0]]},{"q":"Sie wissen nicht, ob Sie in Zürich umsteigen müssen.","model":"Entschuldigung, wissen Sie, ob ich in Zürich umsteigen muss?","aq":"7f40d80bc1a1","am":"a8d448544863","qS":[["Sie wissen nicht, ob Sie in Zürich umsteigen müssen.","You don't know whether you have to change in Zurich.",0]],"modelS":[["Entschuldigung, wissen Sie, ob ich in Zürich umsteigen muss?","Excuse me, do you know whether I have to change in Zurich?",0]]},{"q":"Sie suchen die Haltestelle für den Bus Nummer zwei.","model":"Entschuldigung, ich kenne mich hier nicht aus. Wissen Sie, wo die Haltestelle für den Bus Nummer zwei ist?","aq":"63b8c32f4abf","am":"de28cbb4472d","qS":[["Sie suchen die Haltestelle für den Bus Nummer zwei.","You're looking for the stop for bus number two.",0]],"modelS":[["Entschuldigung, ich kenne mich hier nicht aus.","Excuse me, I don't know my way around here.",0],["Wissen Sie, wo die Haltestelle für den Bus Nummer zwei ist?","Do you know where the stop for bus number two is?",0]]},{"q":"Sie möchten wissen, wie viel ein Billett nach Bern kostet.","model":"Guten Tag. Können Sie mir sagen, wie viel ein Billett nach Bern kostet?","aq":"b14f02de5c25","am":"5f6b2bcf18a9","qS":[["Sie möchten wissen, wie viel ein Billett nach Bern kostet.","You want to know how much a ticket to Bern costs.",0]],"modelS":[["Guten Tag.","Hello.",0],["Können Sie mir sagen, wie viel ein Billett nach Bern kostet?","Could you tell me how much a ticket to Bern costs?",0]]}],"taskS":[["Am Bahnhof – Sie hören eine Situation.","At the station – you'll hear a situation.",0],["Fragen Sie höflich mit einer indirekten Frage.","Ask politely with an indirect question.",0]]},"en":{"title":"By train and bus","subtitle":"Information at the station, understanding announcements","focus":"Two-way prepositions and indirect questions"}},{"id":6,"title":"Nachbarn und Hausordnung","subtitle":"Waschküche, Ruhezeiten und höfliche Bitten","level":"A2/B1","theme":"Zusammenleben","focus":"Konjunktiv II – höfliche Bitten, Wünsche, Ratschläge","goals":[{"de":"Ich kann eine Hausordnung verstehen.","en":"I can understand house rules."},{"de":"Ich kann Nachbarn höflich um etwas bitten und ein Problem freundlich ansprechen.","en":"I can politely ask neighbours for something and raise a problem in a friendly way."},{"de":"Ich kann Ratschläge geben und Wünsche äussern (würde, hätte, wäre, könnte).","en":"I can give advice and express wishes."}],"vocab":[{"id":"6-0","de":"die Hausordnung","forms":"-en","en":"house rules","ex":"Die Hausordnung hängt im Treppenhaus.","exEn":"The house rules are posted in the stairwell.","aw":"31aac9294e4d","ae":"4a36298bee27"},{"id":"6-1","de":"die Nachtruhe","forms":"–","en":"night-time quiet hours","ex":"Ab zweiundzwanzig Uhr ist Nachtruhe.","exEn":"Quiet hours start at ten p.m.","aw":"bfad0021e209","ae":"31118cfdafff"},{"id":"6-2","de":"die Waschküche","forms":"-n","en":"shared laundry room (CH)","ex":"Die Waschküche ist im Keller.","exEn":"The laundry room is in the basement.","aw":"b14b29a7530e","ae":"fbfb84b7c5fc"},{"id":"6-3","de":"der Waschplan","forms":"Waschpläne","en":"laundry schedule (CH)","ex":"Laut Waschplan ist Mittwoch mein Waschtag.","exEn":"According to the schedule, Wednesday is my laundry day.","aw":"cd549dad80ec","ae":"045202d48057"},{"id":"6-4","de":"der Hauswart","forms":"-e","en":"caretaker (CH)","ex":"Rufen Sie den Hauswart an, die Heizung ist kaputt.","exEn":"Call the caretaker, the heating is broken.","aw":"19465af55cdb","ae":"8bca7274f6a9"},{"id":"6-5","de":"der Nachbar","forms":"-n","en":"neighbour","ex":"Unser Nachbar ist sehr hilfsbereit.","exEn":"Our neighbour is very helpful.","aw":"5c65ea2beabb","ae":"2f528831306b"},{"id":"6-6","de":"der Lärm","forms":"–","en":"noise","ex":"Der Lärm von der Baustelle stört mich.","exEn":"The noise from the building site bothers me.","aw":"02da35a6d2c4","ae":"cd07b5191c0d"},{"id":"6-7","de":"stören","forms":"hat gestört","en":"to disturb, bother","ex":"Entschuldigung, störe ich?","exEn":"Sorry, am I disturbing you?","aw":"aa9eceae058e","ae":"aea47fd087df"},{"id":"6-8","de":"das Treppenhaus","forms":"Treppenhäuser","en":"stairwell","ex":"Bitte keine Schuhe im Treppenhaus stehen lassen.","exEn":"Please don't leave shoes in the stairwell.","aw":"72f972ea7f9b","ae":"1da109d95eed"},{"id":"6-9","de":"der Keller","forms":"-","en":"basement, cellar","ex":"Jede Wohnung hat einen eigenen Keller.","exEn":"Every flat has its own cellar.","aw":"6a9a38a62160","ae":"d36b0d779a2b"},{"id":"6-10","de":"der Briefkasten","forms":"Briefkästen","en":"letterbox","ex":"Ich habe einen Zettel in Ihren Briefkasten gelegt.","exEn":"I put a note in your letterbox.","aw":"1eb3ff5b6f35","ae":"e2d50c5df78c"},{"id":"6-11","de":"ausleihen","forms":"hat ausgeliehen","en":"to lend, to borrow","ex":"Könnten Sie mir Ihre Leiter ausleihen?","exEn":"Could you lend me your ladder?","aw":"f361989a4f92","ae":"c21ff16f730c"},{"id":"6-12","de":"sich entschuldigen","forms":"hat sich entschuldigt","en":"to apologise","ex":"Er hat sich für den Lärm entschuldigt.","exEn":"He apologised for the noise.","aw":"ac5796703bc2","ae":"e63477bb632e"},{"id":"6-13","de":"das Missverständnis","forms":"-se","en":"misunderstanding","ex":"Das war nur ein Missverständnis.","exEn":"That was just a misunderstanding.","aw":"e28b194d44ab","ae":"79aeeeac23c2"},{"id":"6-14","de":"Rücksicht nehmen auf","forms":"hat Rücksicht genommen","en":"to be considerate of","ex":"Bitte nehmen Sie Rücksicht auf die Nachbarn.","exEn":"Please be considerate of the neighbours.","aw":"f3e59fef2cbf","ae":"a2540b5ba110"},{"id":"6-15","de":"vorschlagen","forms":"hat vorgeschlagen","en":"to suggest","ex":"Ich schlage vor, dass wir die Waschtage tauschen.","exEn":"I suggest we swap laundry days.","aw":"85bd8923524b","ae":"a56d7f2af881"},{"id":"6-16","de":"der Vorschlag","forms":"Vorschläge","en":"suggestion","ex":"Das ist ein guter Vorschlag!","exEn":"That's a good suggestion!","aw":"49d3f1c3b570","ae":"0582865b02ef"},{"id":"6-17","de":"einverstanden","forms":"–","en":"in agreement, okay with","ex":"Sind Sie damit einverstanden?","exEn":"Are you okay with that?","aw":"ac31036c61de","ae":"0540ba93a1f0"},{"id":"6-18","de":"die Lösung","forms":"-en","en":"solution","ex":"Wir finden sicher eine Lösung.","exEn":"We'll surely find a solution.","aw":"18fd4e00cafd","ae":"a482ebe532f2"},{"id":"6-19","de":"grillieren","forms":"hat grilliert","en":"to barbecue (CH)","ex":"Darf man auf dem Balkon grillieren?","exEn":"Are you allowed to barbecue on the balcony?","aw":"4c4f2d2aa094","ae":"4111b8538830"}],"swiss":[{"ch":"die Waschküche","std":"–","en":"shared laundry room; each flat has fixed laundry days"},{"ch":"der Hauswart","std":"der Hausmeister","en":"caretaker"},{"ch":"grillieren","std":"grillen","en":"to barbecue"},{"ch":"lärmig","std":"laut","en":"noisy"},{"ch":"parkieren","std":"parken","en":"to park"}],"dialogue":{"title":"Ein Missverständnis in der Waschküche","intro":"Carla wäscht an einem Dienstag. Da kommt ihr Nachbar, Herr Schmid, in die Waschküche.","speakers":{"F":"Carla","M":"Herr Schmid"},"lines":[{"s":"M","de":"Guten Abend, Frau Ferreira. Entschuldigung, aber heute ist eigentlich mein Waschtag.","en":"Good evening, Ms Ferreira. Excuse me, but today is actually my laundry day.","audio":"c0fd92775d26"},{"s":"F","de":"Oh, wirklich? Das tut mir leid! Ich dachte, dass ich am Dienstag waschen darf.","en":"Oh, really? I'm sorry! I thought I was allowed to wash on Tuesdays.","audio":"678cfc359f0e"},{"s":"M","de":"Auf dem Waschplan steht, dass Ihr Tag der Mittwoch ist. Schauen Sie, hier.","en":"The schedule says your day is Wednesday. Look, here.","audio":"3c050382f7e0"},{"s":"F","de":"Ach so, da habe ich mich geirrt. Das war ein Missverständnis.","en":"Oh, I see, I made a mistake. That was a misunderstanding.","audio":"4f1a6d6a0409"},{"s":"M","de":"Kein Problem, das kann passieren. Wie lange braucht Ihre Maschine noch?","en":"No problem, it happens. How much longer does your machine need?","audio":"5863884a9c7f"},{"s":"F","de":"Ungefähr vierzig Minuten. Könnten Sie vielleicht so lange warten? Danach würde ich die Wäsche sofort in den Tumbler legen.","en":"About forty minutes. Could you perhaps wait that long? Then I'd put the laundry in the dryer straight away.","audio":"39432fb846f8"},{"s":"M","de":"Hmm, eigentlich müsste ich um sechs Uhr weg. Aber gut, das geht schon.","en":"Hmm, I'd actually have to leave at six. But fine, that's okay.","audio":"195d132947b9"},{"s":"F","de":"Vielen Dank! Darf ich Ihnen als Dankeschön einen Kuchen backen?","en":"Thank you so much! May I bake you a cake as a thank-you?","audio":"25dad6233634"},{"s":"M","de":"Das wäre sehr nett, aber das ist wirklich nicht nötig.","en":"That would be very kind, but it's really not necessary.","audio":"390a9fc658a7"},{"s":"F","de":"Darf ich Sie noch etwas fragen? Wissen Sie, ob man auf dem Balkon grillieren darf?","en":"May I ask you something else? Do you know whether you're allowed to barbecue on the balcony?","audio":"1db35e8da1a2"},{"s":"M","de":"Mit einem Elektrogrill schon, aber nicht mit Holzkohle, wegen des Rauchs. An Ihrer Stelle würde ich aber noch den Hauswart fragen.","en":"With an electric grill, yes, but not with charcoal, because of the smoke. If I were you, I'd still ask the caretaker, though.","audio":"aa9fae381fb4"},{"s":"F","de":"Gute Idee. Und ab wann ist hier Nachtruhe?","en":"Good idea. And from when are the quiet hours here?","audio":"bb7050ab3268"},{"s":"M","de":"Ab zweiundzwanzig Uhr. Und am Sonntag sollte man nicht zu laut sein – also nicht staubsaugen und nicht bohren.","en":"From ten p.m. And on Sundays you shouldn't be too loud – so no vacuuming and no drilling.","audio":"773dd444968e"},{"s":"F","de":"Gut zu wissen! In Portugal ist das ein bisschen anders.","en":"Good to know! It's a bit different in Portugal.","audio":"3dcfdee07234"},{"s":"M","de":"Das glaube ich. Wenn Sie etwas brauchen, klingeln Sie einfach bei mir. Ich wohne im ersten Stock.","en":"I believe it. If you need anything, just ring my bell. I live on the first floor.","audio":"4b886d17aab8"},{"s":"F","de":"Das ist sehr nett. Ich hätte tatsächlich noch eine Bitte. Könnten Sie mir am Samstag Ihre Leiter ausleihen?","en":"That's very kind. Actually, I do have one more request. Could you lend me your ladder on Saturday?","audio":"55f3f60ac3d9"},{"s":"M","de":"Natürlich, kein Problem!","en":"Of course, no problem!","audio":"8cfcdb50f44d"}],"questions":[{"type":"tf","q":"Heute ist eigentlich der Waschtag von Herrn Schmid.","a":true,"why":"","qEn":"Today is actually Mr Schmid's laundry day."},{"type":"mc","q":"Wann ist Carlas Waschtag?","options":["am Dienstag","am Mittwoch","am Sonntag"],"a":1,"qEn":"When is Carla's laundry day?","optionsEn":["on Tuesday","on Wednesday","on Sunday"]},{"type":"mc","q":"Was möchte Carla als Dankeschön machen?","options":["einen Kuchen backen","ihn zum Essen einladen","seine Wäsche waschen"],"a":0,"qEn":"What does Carla want to do as a thank-you?","optionsEn":["bake a cake","invite him for a meal","do his laundry"]},{"type":"tf","q":"Auf dem Balkon darf man mit Holzkohle grillieren.","a":false,"why":"Nur mit einem Elektrogrill.","qEn":"You're allowed to barbecue with charcoal on the balcony.","whyEn":"Only with an electric grill."},{"type":"mc","q":"Was möchte Carla ausleihen?","options":["eine Bohrmaschine","einen Grill","eine Leiter"],"a":2,"qEn":"What does Carla want to borrow?","optionsEn":["a drill","a grill","a ladder"]}],"titleEn":"A misunderstanding in the laundry room","introS":[["Carla wäscht an einem Dienstag.","Carla is doing her laundry on a Tuesday.",0],["Da kommt ihr Nachbar, Herr Schmid, in die Waschküche.","Then her neighbour, Mr Schmid, comes into the laundry room.",0]]},"grammar":{"title":"Konjunktiv II – höflich, vorsichtig, irreal","summary":"Mit dem Konjunktiv II klingen Bitten höflicher und Ratschläge freundlicher.","sections":[{"h":"Höfliche Bitten","text":"Statt eines Imperativs (*Machen Sie die Musik leiser!*) benutzt man im Alltag viel lieber den Konjunktiv II:","examples":[{"de":"==Könnten== Sie bitte die Musik leiser machen?","en":"Could you please turn the music down?","audio":"de14d4048aba"},{"de":"==Würden== Sie mir bitte die Leiter ausleihen?","en":"Would you lend me the ladder, please?","audio":"1f5272060859"},{"de":"==Wäre== es möglich, dass ich am Samstag wasche?","en":"Would it be possible for me to do laundry on Saturday?","audio":"0dd50a2aa224"},{"de":"Ich ==hätte== eine Bitte.","en":"I have a request.","audio":"ce1b96a4f326"}],"hEn":"Polite requests","textP":[[["Statt eines Imperativs (*Machen Sie die Musik leiser!*) benutzt man im Alltag viel lieber den Konjunktiv II:","Instead of an imperative (Turn the music down!), people much prefer to use subjunctive II in everyday life:",0]]]},{"h":"Die wichtigsten Formen","text":"Die Formen kommen vom Präteritum – oft mit Umlaut: *war → wäre, hatte → hätte, konnte → könnte, wurde → würde.*","table":[["Person","sein","haben","können","werden","müssen","sollen"],["ich","wäre","hätte","könnte","würde","müsste","sollte"],["du","wärst","hättest","könntest","würdest","müsstest","solltest"],["er/sie/es","wäre","hätte","könnte","würde","müsste","sollte"],["wir","wären","hätten","könnten","würden","müssten","sollten"],["ihr","wärt","hättet","könntet","würdet","müsstet","solltet"],["sie/Sie","wären","hätten","könnten","würden","müssten","sollten"]],"hEn":"The most important forms","textP":[[["Die Formen kommen vom Präteritum – oft mit Umlaut: *war → wäre, hatte → hätte, konnte → könnte, wurde → würde.*","The forms come from the simple past – often with an umlaut: war → wäre, hatte → hätte, konnte → könnte, wurde → würde.",0]]]},{"h":"würde + Infinitiv","text":"Bei den meisten anderen Verben benutzt man **würde + Infinitiv** (am Satzende).","examples":[{"de":"Ich ==würde== gern im Erdgeschoss ==wohnen==.","en":"I would like to live on the ground floor.","audio":"2836c2409a05"},{"de":"==Würden== Sie das Fenster bitte ==schliessen==?","en":"Would you close the window, please?","audio":"84ba1bc89633"}],"hEn":"würde + infinitive","textP":[[["Bei den meisten anderen Verben benutzt man **würde + Infinitiv** (am Satzende).","With most other verbs you use würde + infinitive (at the end of the sentence).",0]]]},{"h":"Wünsche und Ratschläge","table":[["Funktion","Redemittel"],["Wunsch","Ich hätte gern … / Ich würde gern … / Es wäre schön, wenn …"],["Rat","Du solltest … / An deiner Stelle würde ich … / Wie wäre es, wenn …?"],["Vorschlag","Wir könnten … / Wäre es nicht besser, …?"]],"hEn":"Wishes and advice"},{"h":"Irreale Bedingung (B1)","text":"Wenn etwas nicht real ist, sondern nur eine Idee: **wenn** + Konjunktiv II, **dann** Konjunktiv II.","examples":[{"de":"Wenn ich einen Garten ==hätte==, ==würde== ich Gemüse ==pflanzen==.","en":"If I had a garden, I would plant vegetables.","audio":"6deb186f3111"},{"de":"Wenn das Wetter schöner ==wäre==, ==könnten== wir ==grillieren==.","en":"If the weather were nicer, we could have a barbecue.","audio":"a9967f764391"}],"hEn":"Hypothetical condition (B1)","textP":[[["Wenn etwas nicht real ist, sondern nur eine Idee: **wenn** + Konjunktiv II, **dann** Konjunktiv II.","When something isn't real, just an idea: wenn + subjunctive II, then subjunctive II.",0]]]}],"tip":"Für sein, haben und die Modalverben benutzt man fast nie „würde\": Man sagt „Ich wäre froh\" und nicht „Ich würde froh sein\". Man sagt „Ich hätte Zeit\" und nicht „Ich würde Zeit haben\".","titleEn":"Subjunctive II – polite, cautious, hypothetical","summaryS":[["Mit dem Konjunktiv II klingen Bitten höflicher und Ratschläge freundlicher.","With subjunctive II, requests sound more polite and advice sounds friendlier.",0]],"tipP":[[["Für sein, haben und die Modalverben benutzt man fast nie „würde\": Man sagt „Ich wäre froh\" und nicht „Ich würde froh sein\".","For sein, haben and the modal verbs you almost never use \"würde\": you say \"Ich wäre froh\" and not \"Ich würde froh sein\".",0],["Man sagt „Ich hätte Zeit\" und nicht „Ich würde Zeit haben\".","You say \"Ich hätte Zeit\" and not \"Ich würde Zeit haben\".",0]]]},"exercises":[{"type":"choice","title":"Welche Form passt?","items":[{"q":"___ Sie bitte etwas leiser sein?","options":["Könnten","Hätten","Wären"],"a":0,"full":"Könnten Sie bitte etwas leiser sein?","audio":"974b4fd2c121","en":"Could you please be a bit quieter?"},{"q":"Ich ___ gern einen Termin mit dem Hauswart.","options":["hätte","wäre","würde"],"a":0,"full":"Ich hätte gern einen Termin mit dem Hauswart.","audio":"90310a692d3d","en":"I'd like an appointment with the caretaker."},{"q":"___ es möglich, dass ich am Samstag wasche?","options":["Wäre","Hätte","Würde"],"a":0,"full":"Wäre es möglich, dass ich am Samstag wasche?","audio":"0dd50a2aa224","en":"Would it be possible for me to do my laundry on Saturday?"},{"q":"An deiner Stelle ___ ich mit dem Nachbarn sprechen.","options":["würde","hätte","wäre"],"a":0,"full":"An deiner Stelle würde ich mit dem Nachbarn sprechen.","audio":"9bbecda72b92","en":"If I were you, I'd talk to the neighbour."},{"q":"Du ___ die Hausordnung genau lesen.","options":["solltest","wärst","hättest"],"a":0,"full":"Du solltest die Hausordnung genau lesen.","audio":"c35e6af60376","en":"You should read the house rules carefully."},{"q":"Wenn ich mehr Zeit ___, würde ich öfter kochen.","options":["hätte","wäre","würde"],"a":0,"full":"Wenn ich mehr Zeit hätte, würde ich öfter kochen.","audio":"21bac08f8e8b","en":"If I had more time, I would cook more often."},{"q":"Wenn das Wetter schöner ___, könnten wir grillieren.","options":["wäre","hätte","würde"],"a":0,"full":"Wenn das Wetter schöner wäre, könnten wir grillieren.","audio":"a9967f764391","en":"If the weather were nicer, we could have a barbecue."},{"q":"___ Sie mir bitte Ihre Leiter ausleihen?","options":["Würden","Wären","Hätten"],"a":0,"full":"Würden Sie mir bitte Ihre Leiter ausleihen?","audio":"fe4b1c807109","en":"Would you lend me your ladder, please?"}],"titleEn":"Which form fits?"},{"type":"gap","title":"Konjunktiv II – ergänzen Sie","items":[{"q":"___ du mir kurz helfen? (können)","a":["Könntest"],"full":"Könntest du mir kurz helfen?","audio":"33c26e352bc7","en":"Could you help me for a moment?"},{"q":"Ich ___ lieber im Erdgeschoss wohnen. (werden)","a":["würde"],"full":"Ich würde lieber im Erdgeschoss wohnen.","audio":"8f5ef88b0cff","en":"I'd rather live on the ground floor."},{"q":"Es ___ schön, wenn wir zusammen grillieren. (sein)","a":["wäre"],"full":"Es wäre schön, wenn wir zusammen grillieren.","audio":"9ffc0831d18c","en":"It would be nice if we had a barbecue together."},{"q":"Wir ___ gern eine grössere Wohnung. (haben)","a":["hätten"],"full":"Wir hätten gern eine grössere Wohnung.","audio":"bffe5b45b921","en":"We'd like a bigger flat."},{"q":"Sie ___ den Hauswart anrufen. (sollen)","a":["sollten"],"full":"Sie sollten den Hauswart anrufen.","audio":"972079a288f8","en":"You should call the caretaker."},{"q":"___ ihr am Sonntag Zeit? (haben)","a":["Hättet"],"full":"Hättet ihr am Sonntag Zeit?","audio":"ff4c09aeaa95","en":"Would you (all) have time on Sunday?"}],"titleEn":"Subjunctive II – fill in the gaps"},{"type":"order","title":"Bilden Sie Sätze","items":[{"a":["Könnten Sie bitte die Musik leiser machen?"],"tokens":["Könnten","Sie","bitte","die","Musik","leiser","machen?"],"audio":"de14d4048aba","en":"Could you please turn the music down?"},{"a":["Ich würde gern mit Ihnen über den Waschplan sprechen."],"tokens":["Ich","würde","gern","mit","Ihnen","über","den","Waschplan","sprechen."],"audio":"70d9bdf3c389","en":"I'd like to talk to you about the laundry schedule."},{"a":["An Ihrer Stelle würde ich den Hauswart fragen."],"tokens":["An","Ihrer","Stelle","würde","ich","den","Hauswart","fragen."],"audio":"dc3603280a5d","en":"If I were you, I'd ask the caretaker."},{"a":["Wenn ich einen Garten hätte, würde ich Gemüse pflanzen.","Ich würde Gemüse pflanzen, wenn ich einen Garten hätte."],"tokens":["Wenn","ich","einen","Garten","hätte,","würde","ich","Gemüse","pflanzen."],"audio":"6deb186f3111","en":"If I had a garden, I would plant vegetables."},{"a":["Wäre es möglich, den Waschtag zu tauschen?"],"tokens":["Wäre","es","möglich,","den","Waschtag","zu","tauschen?"],"audio":"8113a84d0e76","en":"Would it be possible to swap laundry days?"}],"titleEn":"Make sentences"},{"type":"match","title":"Direkt → höflich","items":[{"l":"Mach die Musik leiser!","r":"Könntest du bitte die Musik leiser machen?"},{"l":"Gib mir die Leiter!","r":"Würdest du mir bitte die Leiter geben?"},{"l":"Ich will am Samstag waschen.","r":"Ich würde gern am Samstag waschen."},{"l":"Ich will einen Kaffee.","r":"Ich hätte gern einen Kaffee."},{"l":"Räumen Sie die Schuhe weg!","r":"Könnten Sie bitte die Schuhe wegräumen?"}],"titleEn":"Direct → polite"},{"type":"dictation","title":"Diktat – hören und schreiben","items":[{"a":"Könnten Sie bitte etwas leiser sein?","audio":"7c7082a4663c","en":"Could you please be a bit quieter?"},{"a":"Ich hätte noch eine Bitte.","audio":"b01c2b5c73dc","en":"I have one more request."},{"a":"An Ihrer Stelle würde ich den Hauswart fragen.","audio":"5f28102da1e5","en":"If I were you, I'd ask the caretaker."},{"a":"Wenn ich mehr Zeit hätte, würde ich öfter kochen.","audio":"203d5e87cb1a","en":"If I had more time, I would cook more often."}],"titleEn":"Dictation – listen and write"}],"reading":{"title":"Hausordnung – Rosenweg 12","kind":"Hausordnung","paras":[{"t":"Damit sich alle im Haus wohlfühlen, bitten wir Sie, die folgenden Regeln zu beachten.","audio":"8261af0cc736","s":[["Damit sich alle im Haus wohlfühlen, bitten wir Sie, die folgenden Regeln zu beachten.","So that everyone in the building feels at home, we ask you to follow the rules below.",0]]},{"t":"**Ruhezeiten:** Von 22 bis 7 Uhr und von 12 bis 13 Uhr ist Ruhezeit. Am Sonntag und an Feiertagen bitten wir Sie, den ganzen Tag auf lärmige Arbeiten wie Staubsaugen oder Bohren zu verzichten.","audio":"6b58c863e424","s":[["**Ruhezeiten:** Von 22 bis 7 Uhr und von 12 bis 13 Uhr ist Ruhezeit.","Quiet hours: from 10 p.m. to 7 a.m. and from 12 noon to 1 p.m.",0],["Am Sonntag und an Feiertagen bitten wir Sie, den ganzen Tag auf lärmige Arbeiten wie Staubsaugen oder Bohren zu verzichten.","On Sundays and public holidays, we ask you to avoid noisy jobs such as vacuuming or drilling all day.",0]]},{"t":"**Waschküche:** Bitte halten Sie sich an den Waschplan. Wenn Sie Ihren Waschtag tauschen möchten, sprechen Sie mit Ihren Nachbarn. Reinigen Sie nach dem Waschen die Maschinen und das Sieb vom Tumbler.","audio":"4a9630b2fb70","s":[["**Waschküche:** Bitte halten Sie sich an den Waschplan.","Laundry room: please keep to the laundry schedule.",0],["Wenn Sie Ihren Waschtag tauschen möchten, sprechen Sie mit Ihren Nachbarn.","If you want to swap your laundry day, talk to your neighbours.",0],["Reinigen Sie nach dem Waschen die Maschinen und das Sieb vom Tumbler.","After washing, clean the machines and the filter of the tumble dryer.",0]]},{"t":"**Treppenhaus:** Schuhe, Velos und Kinderwagen dürfen nicht im Treppenhaus stehen. Für Velos gibt es einen Veloraum im Keller.","audio":"1218bc065683","s":[["**Treppenhaus:** Schuhe, Velos und Kinderwagen dürfen nicht im Treppenhaus stehen.","Stairwell: shoes, bikes and prams must not be left in the stairwell.",0],["Für Velos gibt es einen Veloraum im Keller.","There is a bike room in the basement for bikes.",0]]},{"t":"**Balkon:** Grillieren ist nur mit Gas- oder Elektrogrills erlaubt. Bitte schütteln Sie keine Teppiche über das Geländer.","audio":"9b411f9d0021","s":[["**Balkon:** Grillieren ist nur mit Gas- oder Elektrogrills erlaubt.","Balcony: barbecuing is only allowed with gas or electric grills.",0],["Bitte schütteln Sie keine Teppiche über das Geländer.","Please don't shake carpets out over the railing.",0]]},{"t":"**Probleme:** Bei Schäden oder Problemen, z. B. mit der Heizung oder dem Wasser, wenden Sie sich bitte an den Hauswart, Herrn Rossi. Im Notfall ist er auch am Wochenende erreichbar.","audio":"e69b6c448fc9","s":[["**Probleme:** Bei Schäden oder Problemen, z. B. mit der Heizung oder dem Wasser, wenden Sie sich bitte an den Hauswart, Herrn Rossi.","Problems: for damage or problems, e.g. with the heating or the water, please contact the caretaker, Mr Rossi.",0],["Im Notfall ist er auch am Wochenende erreichbar.","In an emergency he can also be reached at the weekend.",0]]},{"t":"Ihre Verwaltung","audio":"8cef3ad23b33","s":[["Ihre Verwaltung","Your property management",0]]}],"glossary":[{"de":"sich wohlfühlen","en":"to feel comfortable"},{"de":"verzichten auf","en":"to refrain from, do without"},{"de":"lärmig (CH)","en":"noisy"},{"de":"das Sieb","en":"filter, sieve"},{"de":"das Geländer","en":"railing"},{"de":"sich wenden an","en":"to contact, turn to"},{"de":"erreichbar","en":"reachable"}],"questions":[{"type":"tf","q":"Am Sonntag sollte man nicht staubsaugen.","a":true,"why":"","qEn":"You shouldn't vacuum on Sundays."},{"type":"mc","q":"Was machen Sie, wenn Sie Ihren Waschtag tauschen möchten?","options":["Ich frage den Hauswart.","Ich spreche mit meinen Nachbarn.","Ich schreibe der Verwaltung."],"a":1,"qEn":"What do you do if you want to swap your laundry day?","optionsEn":["I ask the caretaker.","I talk to my neighbours.","I write to the property management company."]},{"type":"mc","q":"Wo stellt man sein Velo hin?","options":["ins Treppenhaus","in den Veloraum im Keller","auf den Balkon"],"a":1,"qEn":"Where do you put your bike?","optionsEn":["in the stairwell","in the bike room in the basement","on the balcony"]},{"type":"tf","q":"Auf dem Balkon darf man mit Holzkohle grillieren.","a":false,"why":"Nur Gas- oder Elektrogrills sind erlaubt.","qEn":"You're allowed to barbecue with charcoal on the balcony.","whyEn":"Only gas or electric grills are allowed."},{"type":"tf","q":"Der Hauswart ist im Notfall auch am Wochenende erreichbar.","a":true,"why":"","qEn":"In an emergency the caretaker can also be reached at the weekend."}],"titleEn":"House rules – Rosenweg 12"},"writing":{"task":"Ihr Nachbar hört jeden Abend bis Mitternacht laute Musik. Schreiben Sie ihm eine höfliche Nachricht (60–80 Wörter).","points":["Stellen Sie sich kurz vor.","Beschreiben Sie das Problem.","Bitten Sie höflich um eine Lösung.","Machen Sie einen Vorschlag."],"phrases":[{"de":"Ich bin Ihre neue Nachbarin / Ihr neuer Nachbar aus dem … Stock.","en":"I'm your new neighbour from the … floor."},{"de":"Leider ist es am Abend oft …","en":"Unfortunately it's often … in the evening."},{"de":"Könnten Sie bitte …?","en":"Could you please …?"},{"de":"Vielleicht könnten wir …","en":"Perhaps we could …"}],"model":"Lieber Herr Brunner\n\nIch bin Ihre neue Nachbarin aus dem zweiten Stock. Leider ist Ihre Musik am Abend oft sehr laut, manchmal bis Mitternacht. Ich muss jeden Morgen um sechs Uhr aufstehen und kann dann nicht gut schlafen. Könnten Sie die Musik ab 22 Uhr bitte etwas leiser machen? Vielleicht könnten wir auch kurz zusammen sprechen – ich würde Sie gern auf einen Kaffee einladen.\n\nFreundliche Grüsse\nCarla Ferreira","audio":"a29ca5f26f07","taskS":[["Ihr Nachbar hört jeden Abend bis Mitternacht laute Musik.","Your neighbour listens to loud music every evening until midnight.",0],["Schreiben Sie ihm eine höfliche Nachricht (60–80 Wörter).","Write him a polite message (60–80 words).",0]],"pointsEn":["Briefly introduce yourself.","Describe the problem.","Politely ask for a solution.","Make a suggestion."],"modelP":[[["Lieber Herr Brunner","Dear Mr Brunner",0]],[["Ich bin Ihre neue Nachbarin aus dem zweiten Stock.","I'm your new neighbour from the second floor.",0],["Leider ist Ihre Musik am Abend oft sehr laut, manchmal bis Mitternacht.","Unfortunately your music is often very loud in the evening, sometimes until midnight.",0],["Ich muss jeden Morgen um sechs Uhr aufstehen und kann dann nicht gut schlafen.","I have to get up at six o'clock every morning and then can't sleep well.",0],["Könnten Sie die Musik ab 22 Uhr bitte etwas leiser machen?","Could you please turn the music down a bit from 10 p.m.?",0],["Vielleicht könnten wir auch kurz zusammen sprechen – ich würde Sie gern auf einen Kaffee einladen.","Perhaps we could also have a quick chat – I'd like to invite you for a coffee.",0]],[["Freundliche Grüsse","Kind regards",0],["Carla Ferreira","Carla Ferreira",1]]]},"speaking":{"task":"Sie hören eine Situation. Bitten Sie höflich um etwas oder geben Sie einen Rat.","phrases":[{"de":"Könnten Sie bitte …?","en":"Could you please …?","audio":null},{"de":"Ich hätte eine Bitte.","en":"I have a request.","audio":"ce1b96a4f326"},{"de":"Wäre es möglich, dass …?","en":"Would it be possible that …?","audio":null},{"de":"An deiner Stelle würde ich …","en":"If I were you, I would …","audio":null},{"de":"Wie wäre es, wenn …?","en":"How about if …?","audio":null}],"prompts":[{"q":"Ihr Nachbar stellt sein Velo immer vor Ihre Tür. Bitten Sie ihn höflich, das Velo in den Veloraum zu stellen.","model":"Entschuldigung, Herr Schmid. Könnten Sie Ihr Velo bitte in den Veloraum stellen? Ich komme sonst kaum in meine Wohnung.","aq":"618bb178588a","am":"5b05690f1dee","qS":[["Ihr Nachbar stellt sein Velo immer vor Ihre Tür.","Your neighbour always puts his bike in front of your door.",0],["Bitten Sie ihn höflich, das Velo in den Veloraum zu stellen.","Politely ask him to put the bike in the bike room.",0]],"modelS":[["Entschuldigung, Herr Schmid.","Excuse me, Mr Schmid.",0],["Könnten Sie Ihr Velo bitte in den Veloraum stellen?","Could you please put your bike in the bike room?",0],["Ich komme sonst kaum in meine Wohnung.","Otherwise I can hardly get into my flat.",0]]},{"q":"Sie brauchen am Samstag eine Bohrmaschine. Fragen Sie Ihre Nachbarin.","model":"Hallo Frau Rossi, ich hätte eine Bitte. Könnten Sie mir am Samstag Ihre Bohrmaschine ausleihen?","aq":"3df1f4490f11","am":"76309e006ae4","qS":[["Sie brauchen am Samstag eine Bohrmaschine.","You need a drill on Saturday.",0],["Fragen Sie Ihre Nachbarin.","Ask your neighbour.",0]],"modelS":[["Hallo Frau Rossi, ich hätte eine Bitte.","Hello Ms Rossi, I have a favour to ask.",0],["Könnten Sie mir am Samstag Ihre Bohrmaschine ausleihen?","Could you lend me your drill on Saturday?",0]]},{"q":"Eine Freundin hat oft Streit mit ihrem Nachbarn. Geben Sie ihr einen Rat.","model":"An deiner Stelle würde ich einmal in Ruhe mit ihm sprechen. Vielleicht könntet ihr zusammen eine Lösung finden.","aq":"5a9cce512158","am":"13154dffdac4","qS":[["Eine Freundin hat oft Streit mit ihrem Nachbarn.","A friend often argues with her neighbour.",0],["Geben Sie ihr einen Rat.","Give her some advice.",0]],"modelS":[["An deiner Stelle würde ich einmal in Ruhe mit ihm sprechen.","If I were you, I'd have a calm talk with him.",0],["Vielleicht könntet ihr zusammen eine Lösung finden.","Maybe you could find a solution together.",0]]},{"q":"Was würden Sie machen, wenn Sie ein Haus mit Garten hätten?","model":"Wenn ich ein Haus mit Garten hätte, würde ich Gemüse pflanzen und im Sommer oft mit Freunden grillieren.","aq":"2a3705390325","am":"23909e7456bd","qS":[["Was würden Sie machen, wenn Sie ein Haus mit Garten hätten?","What would you do if you had a house with a garden?",0]],"modelS":[["Wenn ich ein Haus mit Garten hätte, würde ich Gemüse pflanzen und im Sommer oft mit Freunden grillieren.","If I had a house with a garden, I would plant vegetables and often have barbecues with friends in the summer.",0]]}],"taskS":[["Sie hören eine Situation.","You'll hear a situation.",0],["Bitten Sie höflich um etwas oder geben Sie einen Rat.","Politely ask for something or give advice.",0]]},"en":{"title":"Neighbours and house rules","subtitle":"Laundry room, quiet hours and polite requests","focus":"Subjunctive II – polite requests, wishes, advice"}},{"id":7,"title":"Arbeit und Bewerbung","subtitle":"Stelleninserate, Bewerbung, Vorstellungsgespräch","level":"B1","theme":"Arbeit","focus":"Relativsätze (Nominativ, Akkusativ, Dativ, mit Präposition)","goals":[{"de":"Ich kann ein Stelleninserat verstehen und die wichtigsten Anforderungen erkennen.","en":"I can understand a job advert and identify the main requirements."},{"de":"Ich kann in einem Vorstellungsgespräch über meine Erfahrung und meine Stärken sprechen.","en":"I can talk about my experience and strengths in a job interview."},{"de":"Ich kann Personen und Dinge genauer beschreiben (Relativsätze).","en":"I can describe people and things more precisely."}],"vocab":[{"id":"7-0","de":"die Stelle","forms":"-n","en":"job, position","ex":"Ich habe eine neue Stelle gefunden.","exEn":"I've found a new job.","aw":"72bbcab3d8bf","ae":"4046dfc8cb3a"},{"id":"7-1","de":"das Stelleninserat","forms":"-e","en":"job advert (CH)","ex":"Das Stelleninserat war auf der Website der Firma.","exEn":"The job advert was on the company's website.","aw":"516b15e5c05a","ae":"e7001cb40eb3"},{"id":"7-2","de":"die Bewerbung","forms":"-en","en":"application","ex":"Ich habe meine Bewerbung gestern abgeschickt.","exEn":"I sent off my application yesterday.","aw":"7574a3cb9655","ae":"933c45ca09c4"},{"id":"7-3","de":"der Lebenslauf","forms":"Lebensläufe","en":"CV, résumé","ex":"Mein Lebenslauf ist zwei Seiten lang.","exEn":"My CV is two pages long.","aw":"934d90988915","ae":"da63157bc9d6"},{"id":"7-4","de":"das Vorstellungsgespräch","forms":"-e","en":"job interview","ex":"Morgen habe ich ein Vorstellungsgespräch.","exEn":"I have a job interview tomorrow.","aw":"252c3df08f95","ae":"163a06b0e43b"},{"id":"7-5","de":"die Erfahrung","forms":"-en","en":"experience","ex":"Ich habe fünf Jahre Erfahrung in der Logistik.","exEn":"I have five years' experience in logistics.","aw":"ac57a6ad9066","ae":"eedaf0e2bc08"},{"id":"7-6","de":"die Kenntnisse","forms":"(Pl.)","en":"knowledge, skills","ex":"Gute Deutschkenntnisse sind wichtig.","exEn":"Good German skills are important.","aw":"bf9b0ff3ab7c","ae":"c40d1977e9d0"},{"id":"7-7","de":"die Voraussetzung","forms":"-en","en":"requirement","ex":"Ein Führerschein ist Voraussetzung für diese Stelle.","exEn":"A driving licence is a requirement for this job.","aw":"e95e803c4eee","ae":"7738acc6adbe"},{"id":"7-8","de":"die Aufgabe","forms":"-n","en":"task, duty","ex":"Was sind Ihre Aufgaben?","exEn":"What are your duties?","aw":"0ce80fbf99b3","ae":"cc2a83cc7518"},{"id":"7-9","de":"verantwortlich für","forms":"–","en":"responsible for","ex":"Ich bin für die Tourenplanung verantwortlich.","exEn":"I'm responsible for route planning.","aw":"73ec0dce420d","ae":"7b846206b40d"},{"id":"7-10","de":"der Lohn","forms":"Löhne","en":"wage, salary","ex":"Der Lohn ist höher als bei meiner alten Stelle.","exEn":"The salary is higher than at my old job.","aw":"7e8e440416a5","ae":"4d1240353aa5"},{"id":"7-11","de":"das Pensum","forms":"Pensen","en":"workload in percent (CH)","ex":"Die Stelle hat ein Pensum von achtzig Prozent.","exEn":"The job is an eighty percent position.","aw":"2e358e412369","ae":"1988dd8d7e74"},{"id":"7-12","de":"die Teilzeit","forms":"–","en":"part-time","ex":"Ich möchte lieber Teilzeit arbeiten.","exEn":"I'd rather work part-time.","aw":"210ab03c1e59","ae":"b8ce8b36282a"},{"id":"7-13","de":"die Probezeit","forms":"-en","en":"probation period","ex":"Die Probezeit dauert drei Monate.","exEn":"The probation period lasts three months.","aw":"2330d26e6d10","ae":"5bf68bd02aee"},{"id":"7-14","de":"die Kündigungsfrist","forms":"-en","en":"notice period","ex":"Meine Kündigungsfrist beträgt zwei Monate.","exEn":"My notice period is two months.","aw":"479d4d0159cf","ae":"ea2af824175e"},{"id":"7-15","de":"der Arbeitgeber","forms":"-","en":"employer","ex":"Mein Arbeitgeber bezahlt den Deutschkurs.","exEn":"My employer pays for the German course.","aw":"4f3407d4e8d7","ae":"d4f5eeae171a"},{"id":"7-16","de":"die Weiterbildung","forms":"-en","en":"further training","ex":"Die Firma bietet viele Weiterbildungen an.","exEn":"The company offers a lot of further training.","aw":"c1f64892c9bb","ae":"f534f8effb67"},{"id":"7-17","de":"das Arbeitszeugnis","forms":"-se","en":"employer's reference","ex":"Mein Arbeitszeugnis ist sehr gut.","exEn":"My reference is very good.","aw":"55990501a0ea","ae":"79702e8f207c"},{"id":"7-18","de":"zuverlässig","forms":"–","en":"reliable","ex":"Sie ist sehr zuverlässig und pünktlich.","exEn":"She is very reliable and punctual.","aw":"5a6b6964183e","ae":"301877b52716"},{"id":"7-19","de":"selbstständig","forms":"–","en":"independent(ly)","ex":"In dieser Position muss man selbstständig arbeiten.","exEn":"In this position you have to work independently.","aw":"6dcbb966d2c7","ae":"1fac4c5a0655"}],"swiss":[{"ch":"das Pensum","std":"–","en":"workload in percent – 100 % is full-time, 80 % is four days a week"},{"ch":"der Lohn","std":"das Gehalt","en":"salary (in Switzerland \"Lohn\" is used for all jobs)"},{"ch":"die/der Lernende","std":"die/der Auszubildende","en":"apprentice"},{"ch":"die Ferien","std":"der Urlaub","en":"holidays from work"}],"dialogue":{"title":"Das Vorstellungsgespräch","intro":"Carla hat sich als Teamleiterin bei der Nordlog AG beworben. Herr Graf aus der Personalabteilung führt das Gespräch.","speakers":{"F":"Carla","M":"Herr Graf"},"lines":[{"s":"M","de":"Frau Ferreira, schön, dass Sie da sind. Erzählen Sie doch bitte kurz etwas über sich.","en":"Ms Ferreira, nice that you're here. Please tell us a little about yourself.","audio":"d7eec775949d"},{"s":"F","de":"Gern. Ich komme aus Portugal und lebe seit einem Jahr in Winterthur. Zurzeit arbeite ich als Disponentin bei einer Firma, die Ersatzteile für Maschinen transportiert.","en":"Of course. I'm from Portugal and have been living in Winterthur for a year. At the moment I work as a dispatcher at a company that transports spare parts for machines.","audio":"ca3f37c88d8b"},{"s":"M","de":"Was genau sind dort Ihre Aufgaben?","en":"What exactly are your duties there?","audio":"36099e240d48"},{"s":"F","de":"Ich plane die Touren für unsere Fahrer und bin für die Kommunikation mit den Kunden verantwortlich. Das ist eine Arbeit, die mir viel Spass macht.","en":"I plan the routes for our drivers and I'm responsible for communication with customers. It's work that I really enjoy.","audio":"887c6014d797"},{"s":"M","de":"Und warum möchten Sie die Stelle wechseln?","en":"And why do you want to change jobs?","audio":"38fcd3e97117"},{"s":"F","de":"Ich suche eine Stelle, in der ich mehr Verantwortung übernehmen kann. In Ihrem Inserat steht, dass die Teamleiterin ein Team von sechs Personen führt. Das finde ich sehr spannend.","en":"I'm looking for a job in which I can take on more responsibility. Your advert says that the team leader manages a team of six people. I find that very exciting.","audio":"8bbb04ab6382"},{"s":"M","de":"Haben Sie schon Führungserfahrung?","en":"Do you already have management experience?","audio":"24c37fd6d1fc"},{"s":"F","de":"Ja. In Portugal habe ich zwei Jahre lang ein kleines Team geleitet. Die Kollegen, mit denen ich damals gearbeitet habe, schreiben mir heute noch.","en":"Yes. In Portugal I led a small team for two years. The colleagues I worked with back then still write to me today.","audio":"43b2ff4e5b81"},{"s":"M","de":"Sehr schön. Und wie sieht es mit Ihren Deutschkenntnissen aus? Unsere Kunden sprechen fast alle Deutsch oder Schweizerdeutsch.","en":"Very nice. And what about your German skills? Almost all our customers speak German or Swiss German.","audio":"ebc34dd5092d"},{"s":"F","de":"Ich lerne jeden Tag und mache im Frühling die fide-Prüfung. Schweizerdeutsch verstehe ich schon ein bisschen, aber sprechen kann ich es noch nicht.","en":"I study every day and I'm taking the fide exam in the spring. I can already understand a bit of Swiss German, but I can't speak it yet.","audio":"f01d49b26ae5"},{"s":"M","de":"Das kommt schon noch! Haben Sie Fragen an uns?","en":"That will come! Do you have any questions for us?","audio":"4ea71e767318"},{"s":"F","de":"Ja. Ist die Stelle ein Hundert-Prozent-Pensum, oder wären auch achtzig Prozent möglich?","en":"Yes. Is the job a hundred percent position, or would eighty percent also be possible?","audio":"0f4306fbd70d"},{"s":"M","de":"Wir suchen jemanden für hundert Prozent, aber nach der Probezeit können wir gern darüber sprechen.","en":"We're looking for someone at one hundred percent, but after the probation period we'd be happy to discuss it.","audio":"98f52c551d66"},{"s":"F","de":"Und gibt es bei Ihnen Möglichkeiten zur Weiterbildung?","en":"And are there opportunities for further training with you?","audio":"3328651571b6"},{"s":"M","de":"Ja, wir bezahlen zum Beispiel Kurse, die mit der Arbeit zu tun haben – auch Deutschkurse.","en":"Yes, for example we pay for courses that are related to the work – including German courses.","audio":"8a4f39430dfe"},{"s":"F","de":"Das klingt sehr gut.","en":"That sounds very good.","audio":"80d3d5e34cde"},{"s":"M","de":"Wir melden uns bis Ende nächster Woche bei Ihnen. Vielen Dank für das Gespräch!","en":"We'll get back to you by the end of next week. Thank you very much for the interview!","audio":"af123bec7a5e"},{"s":"F","de":"Ich danke Ihnen. Auf Wiedersehen!","en":"Thank you. Goodbye!","audio":"a6439b090a06"}],"questions":[{"type":"tf","q":"Carla arbeitet zurzeit als Disponentin.","a":true,"why":"","qEn":"Carla currently works as a dispatcher."},{"type":"mc","q":"Warum möchte Carla die Stelle wechseln?","options":["Sie möchte mehr verdienen.","Sie möchte mehr Verantwortung übernehmen.","Sie hat Probleme mit dem Chef."],"a":1,"qEn":"Why does Carla want to change jobs?","optionsEn":["She wants to earn more.","She wants to take on more responsibility.","She has problems with her boss."]},{"type":"mc","q":"Wie gross ist das Team, das die Teamleiterin führt?","options":["vier Personen","sechs Personen","zehn Personen"],"a":1,"qEn":"How big is the team that the team leader manages?","optionsEn":["four people","six people","ten people"]},{"type":"tf","q":"Carla spricht schon gut Schweizerdeutsch.","a":false,"why":"Sie versteht ein bisschen, aber sie kann es noch nicht sprechen.","qEn":"Carla already speaks Swiss German well.","whyEn":"She understands a bit, but she can't speak it yet."},{"type":"mc","q":"Was sagt Herr Graf zum Pensum?","options":["Achtzig Prozent sind sofort möglich.","Nach der Probezeit kann man darüber sprechen.","Die Stelle ist nur Teilzeit."],"a":1,"qEn":"What does Mr Graf say about the workload percentage?","optionsEn":["Eighty percent is possible straight away.","It can be discussed after the probation period.","The job is only part-time."]}],"titleEn":"The job interview","introS":[["Carla hat sich als Teamleiterin bei der Nordlog AG beworben.","Carla has applied for a team leader position at Nordlog AG.",0],["Herr Graf aus der Personalabteilung führt das Gespräch.","Mr Graf from the HR department conducts the interview.",0]]},"grammar":{"title":"Relativsätze","summary":"Ein Relativsatz beschreibt ein Nomen genauer. Das Verb steht am Ende.","sections":[{"h":"Zwei Sätze – ein Satz","text":"Der Relativsatz steht direkt **nach dem Nomen**, das er beschreibt. Er beginnt mit einem **Relativpronomen** und endet mit dem **konjugierten Verb**.","examples":[{"de":"Das ist eine Arbeit. Die Arbeit macht mir Spass. → Das ist eine Arbeit, ==die== mir Spass ==macht==.","en":"That's a job that I enjoy.","audio":"780b4022c0a0"},{"de":"Die Firma transportiert Ersatzteile. → Ich arbeite bei einer Firma, ==die== Ersatzteile ==transportiert==.","en":"I work for a company that transports spare parts.","audio":"02240b434d03"}],"hEn":"Two sentences – one sentence","textP":[[["Der Relativsatz steht direkt **nach dem Nomen**, das er beschreibt.","The relative clause comes directly after the noun it describes.",0],["Er beginnt mit einem **Relativpronomen** und endet mit dem **konjugierten Verb**.","It begins with a relative pronoun and ends with the conjugated verb.",0]]]},{"h":"Die Relativpronomen","text":"**Genus und Zahl** kommen vom Nomen davor. **Der Kasus** kommt vom Verb im Relativsatz.","table":[["Kasus","maskulin","feminin","neutral","Plural"],["Nominativ","der","die","das","die"],["Akkusativ","den","die","das","die"],["Dativ","dem","der","dem","==denen=="]],"hEn":"The relative pronouns","textP":[[["**Genus und Zahl** kommen vom Nomen davor.","Gender and number come from the noun before it.",0],["**Der Kasus** kommt vom Verb im Relativsatz.","The case comes from the verb in the relative clause.",0]]]},{"h":"Welcher Kasus?","examples":[{"de":"Nominativ → Der Kollege, ==der== im dritten Stock arbeitet, heisst Luca. (Er arbeitet …)","en":"The colleague who works on the third floor is called Luca.","audio":"f1eacdde38be"},{"de":"Akkusativ → Der Lebenslauf, ==den== ich geschrieben habe, ist zwei Seiten lang. (Ich habe ihn geschrieben.)","en":"The CV I wrote is two pages long.","audio":"5334248bea7a"},{"de":"Dativ → Die Chefin, ==der== ich die Bewerbung geschickt habe, heisst Frau Graf. (Ich habe ihr … geschickt.)","en":"The boss I sent the application to is called Ms Graf.","audio":"f3c328d0460d"}],"hEn":"Which case?"},{"h":"Relativsatz mit Präposition","text":"Braucht das Verb eine Präposition, steht sie **vor** dem Relativpronomen. Bei Orten kann man auch **wo** sagen.","examples":[{"de":"Das sind die Kollegen, ==mit denen== ich arbeite.","en":"Those are the colleagues I work with.","audio":"bd94058c2e3c"},{"de":"Ich suche eine Stelle, ==in der== ich mehr Verantwortung habe.","en":"I'm looking for a job in which I have more responsibility.","audio":"8ec28bc5460e"},{"de":"Winterthur ist die Stadt, ==wo== ich wohne.","en":"Winterthur is the town where I live.","audio":"45e3a5678050"}],"hEn":"Relative clause with a preposition","textP":[[["Braucht das Verb eine Präposition, steht sie **vor** dem Relativpronomen.","If the verb needs a preposition, it goes before the relative pronoun.",0],["Bei Orten kann man auch **wo** sagen.","For places you can also say wo.",0]]]}],"tip":"Achtung beim Dativ Plural: Das Relativpronomen heisst „denen\", nicht „den\". Die Kunden, mit denen ich telefoniere, sind sehr freundlich.","titleEn":"Relative clauses","summaryS":[["Ein Relativsatz beschreibt ein Nomen genauer.","A relative clause describes a noun more precisely.",0],["Das Verb steht am Ende.","The verb goes at the end.",0]],"tipP":[[["Achtung beim Dativ Plural: Das Relativpronomen heisst „denen\", nicht „den\".","Careful with the dative plural: the relative pronoun is \"denen\", not \"den\".",0],["Die Kunden, mit denen ich telefoniere, sind sehr freundlich.","The customers I talk to on the phone are very friendly.",0]]]},"exercises":[{"type":"choice","title":"Welches Relativpronomen?","items":[{"q":"Das ist die Stelle, ___ mich interessiert.","options":["die","der","das"],"a":0,"full":"Das ist die Stelle, die mich interessiert.","audio":"8e41cf4943f2","en":"That's the job that interests me."},{"q":"Der Lebenslauf, ___ du mir geschickt hast, ist sehr gut.","options":["den","der","dem"],"a":0,"full":"Der Lebenslauf, den du mir geschickt hast, ist sehr gut.","audio":"50b69bcfc86c","en":"The CV you sent me is very good."},{"q":"Wie heisst der Kollege, ___ du geholfen hast?","options":["dem","den","der"],"a":0,"full":"Wie heisst der Kollege, dem du geholfen hast?","audio":"68971ec554f9","en":"What's the name of the colleague you helped?"},{"q":"Das sind die Kunden, mit ___ ich jeden Tag telefoniere.","options":["denen","den","die"],"a":0,"full":"Das sind die Kunden, mit denen ich jeden Tag telefoniere.","audio":"24df6e9a45bb","en":"Those are the customers I talk to on the phone every day."},{"q":"Ich arbeite in einem Team, ___ sehr international ist.","options":["das","dem","der"],"a":0,"full":"Ich arbeite in einem Team, das sehr international ist.","audio":"7274f3773766","en":"I work in a team that is very international."},{"q":"Die Firma, für ___ ich arbeite, hat zweihundert Mitarbeitende.","options":["die","der","das"],"a":0,"full":"Die Firma, für die ich arbeite, hat zweihundert Mitarbeitende.","audio":"f834e392da7e","en":"The company I work for has two hundred employees."},{"q":"Wo ist das Formular, ___ ich unterschreiben muss?","options":["das","dem","den"],"a":0,"full":"Wo ist das Formular, das ich unterschreiben muss?","audio":"872cf942b7c8","en":"Where is the form I have to sign?"},{"q":"Herr Graf ist der Mann, ___ das Vorstellungsgespräch führt.","options":["der","den","dem"],"a":0,"full":"Herr Graf ist der Mann, der das Vorstellungsgespräch führt.","audio":"6b8b37a884d9","en":"Mr Graf is the man who is conducting the job interview."}],"titleEn":"Which relative pronoun?"},{"type":"gap","title":"Ergänzen Sie das Relativpronomen (mit Präposition, wenn nötig)","items":[{"q":"Das ist die Chefin, ___ ich sehr schätze.","a":["die"],"full":"Das ist die Chefin, die ich sehr schätze.","audio":"8165ca1de1a6","en":"That's the boss whom I really appreciate."},{"q":"Ich suche eine Stelle, ___ ich mehr Verantwortung habe. (in)","a":["in der"],"full":"Ich suche eine Stelle, in der ich mehr Verantwortung habe.","audio":"8ec28bc5460e","en":"I'm looking for a job in which I have more responsibility."},{"q":"Kennst du den Kollegen, ___ im dritten Stock arbeitet?","a":["der"],"full":"Kennst du den Kollegen, der im dritten Stock arbeitet?","audio":"22fef265e740","en":"Do you know the colleague who works on the third floor?"},{"q":"Die Kurse, ___ die Firma bezahlt, sind sehr gut.","a":["die"],"full":"Die Kurse, die die Firma bezahlt, sind sehr gut.","audio":"cd9594e61104","en":"The courses that the company pays for are very good."},{"q":"Das Team, mit ___ ich arbeite, ist super.","a":["dem"],"full":"Das Team, mit dem ich arbeite, ist super.","audio":"03396eaee96f","en":"The team I work with is great."},{"q":"Die Lernenden, ___ ich helfe, sind sehr motiviert.","a":["denen"],"full":"Die Lernenden, denen ich helfe, sind sehr motiviert.","audio":"d156eb0b28be","en":"The apprentices I help are very motivated."}],"titleEn":"Fill in the relative pronoun (with a preposition if necessary)"},{"type":"order","title":"Bilden Sie Sätze","items":[{"a":["Das ist eine Arbeit, die mir viel Spass macht."],"tokens":["Das","ist","eine","Arbeit,","die","mir","viel","Spass","macht."],"audio":"d86f5ee8f2df","en":"That's work that I really enjoy."},{"a":["Ich suche eine Stelle, in der ich mehr Verantwortung habe."],"tokens":["Ich","suche","eine","Stelle,","in","der","ich","mehr","Verantwortung","habe."],"audio":"8ec28bc5460e","en":"I'm looking for a job in which I have more responsibility."},{"a":["Der Lebenslauf, den ich geschrieben habe, ist zwei Seiten lang."],"tokens":["Der","Lebenslauf,","den","ich","geschrieben","habe,","ist","zwei","Seiten","lang."],"audio":"5334248bea7a","en":"The CV I wrote is two pages long."},{"a":["Die Kollegen, mit denen ich arbeite, sind sehr nett."],"tokens":["Die","Kollegen,","mit","denen","ich","arbeite,","sind","sehr","nett."],"audio":"7ea75de05f31","en":"The colleagues I work with are very nice."},{"a":["Winterthur ist die Stadt, in der ich seit einem Jahr lebe."],"tokens":["Winterthur","ist","die","Stadt,","in","der","ich","seit","einem","Jahr","lebe."],"audio":"474154ce977f","en":"Winterthur is the town where I've been living for a year."}],"titleEn":"Make sentences"},{"type":"match","title":"Was ist das? Definitionen mit Relativsätzen","items":[{"l":"Ein Lebenslauf ist ein Dokument,","r":"in dem man seine Ausbildung und Berufserfahrung beschreibt."},{"l":"Eine Arbeitgeberin ist eine Person oder Firma,","r":"die Menschen eine Stelle gibt."},{"l":"Die Probezeit ist die Zeit,","r":"in der man schnell kündigen kann."},{"l":"Ein Arbeitszeugnis ist ein Dokument,","r":"das der alte Arbeitgeber schreibt."},{"l":"Lernende sind junge Leute,","r":"die eine Lehre machen."}],"titleEn":"What is it? Definitions with relative clauses"},{"type":"dictation","title":"Diktat – hören und schreiben","items":[{"a":"Das ist eine Arbeit, die mir viel Spass macht.","audio":"88d2487f05a3","en":"That's work that I really enjoy."},{"a":"Ich suche eine Stelle mit mehr Verantwortung.","audio":"30bf334bddf0","en":"I'm looking for a job with more responsibility."},{"a":"Die Kollegen, mit denen ich arbeite, sind sehr nett.","audio":"13c068bc155a","en":"The colleagues I work with are very nice."},{"a":"Wir melden uns bis Ende nächster Woche bei Ihnen.","audio":"3323e8455351","en":"We'll get back to you by the end of next week."}],"titleEn":"Dictation – listen and write"}],"reading":{"title":"Stelleninserat – Teamleiterin / Teamleiter Logistik","kind":"Stelleninserat","paras":[{"t":"**Nordlog AG – Ihre Partnerin für Logistik in der Ostschweiz**\nFür unser Lager in Winterthur suchen wir per 1. Januar oder nach Vereinbarung eine Teamleiterin oder einen Teamleiter Logistik (80–100 %).","audio":"a82cc254a32e","s":[["**Nordlog AG – Ihre Partnerin für Logistik in der Ostschweiz**","Nordlog AG – your partner for logistics in eastern Switzerland",0],["Für unser Lager in Winterthur suchen wir per 1. Januar oder nach Vereinbarung eine Teamleiterin oder einen Teamleiter Logistik (80–100 %).","For our warehouse in Winterthur we are looking for a team leader, logistics (80–100%), starting 1 January or by arrangement.",1]]},{"t":"**Ihre Aufgaben:** Sie führen ein Team von sechs Mitarbeitenden und planen die Einsätze. Sie sind für die Qualität und die Pünktlichkeit der Lieferungen verantwortlich. Für unsere Kundinnen und Kunden sind Sie die wichtigste Ansprechperson.","audio":"ffee40b53ced","s":[["**Ihre Aufgaben:** Sie führen ein Team von sechs Mitarbeitenden und planen die Einsätze.","Your tasks: you lead a team of six employees and plan the shifts.",0],["Sie sind für die Qualität und die Pünktlichkeit der Lieferungen verantwortlich.","You are responsible for the quality and punctuality of deliveries.",0],["Für unsere Kundinnen und Kunden sind Sie die wichtigste Ansprechperson.","You are the main contact person for our customers.",0]]},{"t":"**Ihr Profil:** Sie haben eine abgeschlossene Ausbildung in der Logistik oder eine ähnliche Ausbildung und mindestens drei Jahre Berufserfahrung, idealerweise auch Führungserfahrung. Sie sprechen gut Deutsch (mindestens B1); Englisch ist von Vorteil. Sie arbeiten selbstständig und zuverlässig und bleiben auch in stressigen Situationen ruhig.","audio":"f8b8859c8879","s":[["**Ihr Profil:** Sie haben eine abgeschlossene Ausbildung in der Logistik oder eine ähnliche Ausbildung und mindestens drei Jahre Berufserfahrung, idealerweise auch Führungserfahrung.","Your profile: you have completed training in logistics or similar training and have at least three years of work experience, ideally including management experience.",0],["Sie sprechen gut Deutsch (mindestens B1); Englisch ist von Vorteil.","You speak good German (at least B1); English is an advantage.",0],["Sie arbeiten selbstständig und zuverlässig und bleiben auch in stressigen Situationen ruhig.","You work independently and reliably and stay calm even in stressful situations.",0]]},{"t":"**Wir bieten:** ein junges, internationales Team, moderne Arbeitsplätze, flexible Arbeitszeiten, fünf Wochen Ferien und bezahlte Weiterbildungen.","audio":"c9a880fc9025","s":[["**Wir bieten:** ein junges, internationales Team, moderne Arbeitsplätze, flexible Arbeitszeiten, fünf Wochen Ferien und bezahlte Weiterbildungen.","We offer: a young, international team, modern workplaces, flexible working hours, five weeks' holiday and paid further training.",0]]},{"t":"Interessiert? Dann senden Sie Ihre vollständigen Unterlagen – Lebenslauf, Zeugnisse und Motivationsschreiben – bis zum 31. Oktober über unser Online-Portal. Wir freuen uns auf Sie!","audio":"48b2eaac7a5e","s":[["Interessiert?","Interested?",0],["Dann senden Sie Ihre vollständigen Unterlagen – Lebenslauf, Zeugnisse und Motivationsschreiben – bis zum 31. Oktober über unser Online-Portal.","Then send your complete documents – CV, references and cover letter – through our online portal by 31 October.",0],["Wir freuen uns auf Sie!","We look forward to hearing from you!",0]]}],"glossary":[{"de":"nach Vereinbarung","en":"by arrangement"},{"de":"der Einsatz","en":"shift, assignment"},{"de":"die Ansprechperson","en":"contact person"},{"de":"abgeschlossen","en":"completed"},{"de":"von Vorteil","en":"an advantage"},{"de":"die Unterlagen (Pl.)","en":"documents"}],"questions":[{"type":"tf","q":"Die Stelle ist auch mit einem Pensum von 80 Prozent möglich.","a":true,"why":"","qEn":"The job is also possible at 80 percent."},{"type":"mc","q":"Wie viele Personen führt die Teamleiterin oder der Teamleiter?","options":["drei","sechs","acht"],"a":1,"qEn":"How many people does the team leader manage?","optionsEn":["three","six","eight"]},{"type":"mc","q":"Welche Sprachkenntnisse braucht man?","options":["Deutsch, mindestens B1","Englisch auf C1-Niveau","Französisch"],"a":0,"qEn":"What language skills do you need?","optionsEn":["German, at least B1","English at C1 level","French"]},{"type":"tf","q":"Man braucht mindestens fünf Jahre Berufserfahrung.","a":false,"why":"Man braucht mindestens drei Jahre.","qEn":"You need at least five years of work experience.","whyEn":"You need at least three years."},{"type":"mc","q":"Was bietet die Firma?","options":["ein Geschäftsauto","fünf Wochen Ferien","eine Wohnung"],"a":1,"qEn":"What does the company offer?","optionsEn":["a company car","five weeks' holiday","a flat"]}],"titleEn":"Job advert – team leader, logistics"},"writing":{"task":"Schreiben Sie eine kurze Bewerbung auf das Stelleninserat (80–100 Wörter).","points":["Warum schreiben Sie?","Welche Erfahrung haben Sie?","Warum interessiert Sie die Stelle?","Wann können Sie anfangen?"],"phrases":[{"de":"Mit grossem Interesse habe ich Ihr Inserat gelesen.","en":"I read your advert with great interest."},{"de":"Zurzeit arbeite ich als … bei …","en":"I currently work as … at …"},{"de":"Ich suche eine Stelle, in der …","en":"I'm looking for a job in which …"},{"de":"Ich könnte am … anfangen.","en":"I could start on …"},{"de":"Über eine Einladung zu einem Vorstellungsgespräch würde ich mich sehr freuen.","en":"I would be very pleased to be invited to an interview."}],"model":"Sehr geehrte Frau Graf\n\nMit grossem Interesse habe ich Ihr Inserat für die Stelle als Teamleiterin Logistik gelesen. Zurzeit arbeite ich als Disponentin bei einer Firma in Winterthur, wo ich die Touren für zwölf Fahrer plane. In Portugal habe ich zwei Jahre lang ein kleines Team geleitet. Jetzt suche ich eine Stelle, in der ich wieder mehr Verantwortung übernehmen kann. Ich arbeite selbstständig und zuverlässig, und mein Deutsch verbessere ich jeden Tag. Ich könnte am 1. Februar anfangen. Über eine Einladung zu einem Vorstellungsgespräch würde ich mich sehr freuen.\n\nFreundliche Grüsse\nCarla Ferreira","audio":"355226fec43e","taskS":[["Schreiben Sie eine kurze Bewerbung auf das Stelleninserat (80–100 Wörter).","Write a short application for the job advert (80–100 words).",0]],"pointsEn":["Why are you writing?","What experience do you have?","Why are you interested in the job?","When can you start?"],"modelP":[[["Sehr geehrte Frau Graf","Dear Ms Graf",0]],[["Mit grossem Interesse habe ich Ihr Inserat für die Stelle als Teamleiterin Logistik gelesen.","I read your advert for the position of team leader, logistics with great interest.",0],["Zurzeit arbeite ich als Disponentin bei einer Firma in Winterthur, wo ich die Touren für zwölf Fahrer plane.","I currently work as a dispatcher for a company in Winterthur, where I plan the routes for twelve drivers.",0],["In Portugal habe ich zwei Jahre lang ein kleines Team geleitet.","In Portugal I led a small team for two years.",0],["Jetzt suche ich eine Stelle, in der ich wieder mehr Verantwortung übernehmen kann.","Now I'm looking for a job in which I can take on more responsibility again.",0],["Ich arbeite selbstständig und zuverlässig, und mein Deutsch verbessere ich jeden Tag.","I work independently and reliably, and I'm improving my German every day.",0],["Ich könnte am 1. Februar anfangen.","I could start on 1 February.",0],["Über eine Einladung zu einem Vorstellungsgespräch würde ich mich sehr freuen.","I would be very pleased to be invited to an interview.",0]],[["Freundliche Grüsse","Kind regards",0],["Carla Ferreira","Carla Ferreira",1]]]},"speaking":{"task":"Im Vorstellungsgespräch – beantworten Sie die Fragen ausführlich (drei bis vier Sätze).","phrases":[{"de":"Zurzeit arbeite ich als …","en":"At the moment I work as …","audio":null},{"de":"Ich habe … Jahre Erfahrung in …","en":"I have … years' experience in …","audio":null},{"de":"Meine Stärken sind …","en":"My strengths are …","audio":null},{"de":"Ich suche eine Stelle, in der …","en":"I'm looking for a job in which …","audio":null},{"de":"Wann könnte ich anfangen?","en":"When could I start?","audio":"efe54aaa22d2"}],"prompts":[{"q":"Erzählen Sie bitte etwas über Ihre berufliche Erfahrung.","model":"Ich arbeite seit einem Jahr als Disponentin in Winterthur. Vorher war ich fünf Jahre bei einer Logistikfirma in Porto, wo ich auch ein kleines Team geleitet habe.","aq":"79db14ca966b","am":"bc1e6e596bc6","qS":[["Erzählen Sie bitte etwas über Ihre berufliche Erfahrung.","Please tell us a little about your professional experience.",0]],"modelS":[["Ich arbeite seit einem Jahr als Disponentin in Winterthur.","I've been working as a dispatcher in Winterthur for a year.",0],["Vorher war ich fünf Jahre bei einer Logistikfirma in Porto, wo ich auch ein kleines Team geleitet habe.","Before that I spent five years at a logistics company in Porto, where I also led a small team.",0]]},{"q":"Was sind Ihre Stärken?","model":"Ich bin zuverlässig und gut organisiert, und ich bleibe auch in stressigen Situationen ruhig. Meine Kollegen sagen, dass ich gut zuhören kann.","aq":"572ea2b589b2","am":"dfe6b655cc2e","qS":[["Was sind Ihre Stärken?","What are your strengths?",0]],"modelS":[["Ich bin zuverlässig und gut organisiert, und ich bleibe auch in stressigen Situationen ruhig.","I'm reliable and well organised, and I stay calm even in stressful situations.",0],["Meine Kollegen sagen, dass ich gut zuhören kann.","My colleagues say that I'm a good listener.",0]]},{"q":"Beschreiben Sie eine Aufgabe, die Ihnen besonders gut gefällt.","model":"Am liebsten mache ich Aufgaben, bei denen ich Probleme lösen und mit Menschen sprechen kann – zum Beispiel, wenn eine Lieferung nicht pünktlich ist.","aq":"618cc771284f","am":"0bbb219f2bfc","qS":[["Beschreiben Sie eine Aufgabe, die Ihnen besonders gut gefällt.","Describe a task you particularly enjoy.",0]],"modelS":[["Am liebsten mache ich Aufgaben, bei denen ich Probleme lösen und mit Menschen sprechen kann – zum Beispiel, wenn eine Lieferung nicht pünktlich ist.","I most enjoy tasks where I can solve problems and talk to people – for example, when a delivery isn't on time.",0]]},{"q":"Wo sehen Sie sich in fünf Jahren?","model":"In fünf Jahren möchte ich ein grösseres Team führen und sehr gut Deutsch sprechen. Vielleicht verstehe ich dann auch Schweizerdeutsch!","aq":"024f69f9923d","am":"5f7fb9f058ff","qS":[["Wo sehen Sie sich in fünf Jahren?","Where do you see yourself in five years?",0]],"modelS":[["In fünf Jahren möchte ich ein grösseres Team führen und sehr gut Deutsch sprechen.","In five years I'd like to lead a bigger team and speak very good German.",0],["Vielleicht verstehe ich dann auch Schweizerdeutsch!","Maybe by then I'll understand Swiss German too!",0]]}],"taskS":[["Im Vorstellungsgespräch – beantworten Sie die Fragen ausführlich (drei bis vier Sätze).","In the job interview – answer the questions in detail (three to four sentences).",0]]},"en":{"title":"Work and job applications","subtitle":"Job adverts, applications, job interviews","focus":"Relative clauses (nominative, accusative, dative, with a preposition)"}},{"id":8,"title":"Freizeit und Vereine","subtitle":"Hobbys, Pläne und Leute kennenlernen","level":"B1","theme":"Freizeit","focus":"Verben mit Präpositionen, da-/wo-Wörter, Infinitiv mit zu","goals":[{"de":"Ich kann über meine Hobbys und Interessen sprechen.","en":"I can talk about my hobbies and interests."},{"de":"Ich kann einen Zeitungsartikel über einen Verein verstehen.","en":"I can understand a newspaper article about a club."},{"de":"Ich kann Verben mit Präpositionen richtig benutzen (sich freuen auf, sich interessieren für …).","en":"I can use verbs with prepositions correctly."}],"vocab":[{"id":"8-0","de":"der Verein","forms":"-e","en":"club, association","ex":"In der Schweiz gibt es sehr viele Vereine.","exEn":"There are a great many clubs in Switzerland.","aw":"5609e277669c","ae":"a38e41b98475"},{"id":"8-1","de":"das Mitglied","forms":"-er","en":"member","ex":"Ich bin seit zwei Jahren Mitglied im Turnverein.","exEn":"I've been a member of the gymnastics club for two years.","aw":"fed93849f1bb","ae":"4b723718de94"},{"id":"8-2","de":"der Mitgliederbeitrag","forms":"-beiträge","en":"membership fee (CH)","ex":"Der Mitgliederbeitrag kostet fünfzig Franken pro Jahr.","exEn":"The membership fee is fifty francs a year.","aw":"4e5c115cfda7","ae":"11a0088bde99"},{"id":"8-3","de":"sich interessieren für","forms":"hat sich interessiert","en":"to be interested in","ex":"Ich interessiere mich für Fotografie.","exEn":"I'm interested in photography.","aw":"984ee70b8b1f","ae":"adacac5c4e58"},{"id":"8-4","de":"sich freuen auf","forms":"hat sich gefreut","en":"to look forward to","ex":"Ich freue mich auf das Wochenende.","exEn":"I'm looking forward to the weekend.","aw":"0f7ca9678d0e","ae":"82f85f6d30db"},{"id":"8-5","de":"sich freuen über","forms":"hat sich gefreut","en":"to be pleased about","ex":"Sie hat sich sehr über die Blumen gefreut.","exEn":"She was very pleased about the flowers.","aw":"6f22384877c8","ae":"5398f235fcca"},{"id":"8-6","de":"teilnehmen an","forms":"hat teilgenommen","en":"to take part in","ex":"Nimmst du am Sommerfest teil?","exEn":"Are you taking part in the summer party?","aw":"310d45729c87","ae":"fb526f08d4c7"},{"id":"8-7","de":"sich erinnern an","forms":"hat sich erinnert","en":"to remember","ex":"Ich erinnere mich gut an meinen ersten Tag in der Schweiz.","exEn":"I remember my first day in Switzerland well.","aw":"01b2cb5ce1c4","ae":"ac299bce4007"},{"id":"8-8","de":"träumen von","forms":"hat geträumt","en":"to dream of","ex":"Er träumt von einer Reise nach Japan.","exEn":"He dreams of a trip to Japan.","aw":"4d7661940c9d","ae":"19a84123fe80"},{"id":"8-9","de":"sich kümmern um","forms":"hat sich gekümmert","en":"to take care of","ex":"Wer kümmert sich um die Getränke?","exEn":"Who's taking care of the drinks?","aw":"6a4e6f58dc94","ae":"25cbf72fd318"},{"id":"8-10","de":"Lust haben auf","forms":"hatte Lust","en":"to feel like","ex":"Hast du Lust auf einen Kaffee?","exEn":"Do you feel like a coffee?","aw":"9c48a1f7f487","ae":"0ab2a94af478"},{"id":"8-11","de":"der Ausflug","forms":"Ausflüge","en":"outing, excursion","ex":"Am Sonntag machen wir einen Ausflug an den See.","exEn":"On Sunday we're making a trip to the lake.","aw":"343b54ffd6e5","ae":"27b76ddf3dab"},{"id":"8-12","de":"die Veranstaltung","forms":"-en","en":"event","ex":"Die Veranstaltung beginnt um neunzehn Uhr.","exEn":"The event starts at seven p.m.","aw":"4c6f58bee877","ae":"7c9bab52af9f"},{"id":"8-13","de":"ehrenamtlich","forms":"–","en":"voluntary, unpaid","ex":"Sie arbeitet ehrenamtlich im Quartierverein.","exEn":"She volunteers in the neighbourhood association.","aw":"f1d47da5ef0b","ae":"aa36cf4abd3f"},{"id":"8-14","de":"der Chor","forms":"Chöre","en":"choir","ex":"Meine Schwester singt in einem Chor.","exEn":"My sister sings in a choir.","aw":"e526965e38de","ae":"0d8939cd567c"},{"id":"8-15","de":"die Probe","forms":"-n","en":"rehearsal","ex":"Die Chorprobe ist jeden Dienstag.","exEn":"Choir rehearsal is every Tuesday.","aw":"3f820d92f346","ae":"cd1f56a08551"},{"id":"8-16","de":"die Wanderung","forms":"-en","en":"hike","ex":"Die Wanderung dauert ungefähr vier Stunden.","exEn":"The hike takes about four hours.","aw":"67cfbbda5da3","ae":"d63887efa742"},{"id":"8-17","de":"sich entspannen","forms":"hat sich entspannt","en":"to relax","ex":"Am Abend entspanne ich mich mit einem Buch.","exEn":"In the evening I relax with a book.","aw":"13a13234f996","ae":"3049d3467ef2"},{"id":"8-18","de":"anfangen mit","forms":"hat angefangen","en":"to start (with)","ex":"Ich habe letztes Jahr mit Yoga angefangen.","exEn":"I started yoga last year.","aw":"cf021ed14eb6","ae":"e262572ad9ae"},{"id":"8-19","de":"aufhören mit","forms":"hat aufgehört","en":"to stop, give up","ex":"Er hat mit dem Rauchen aufgehört.","exEn":"He has stopped smoking.","aw":"b3829b1179c9","ae":"92a15a492a9f"}],"swiss":[{"ch":"der Mitgliederbeitrag","std":"der Mitgliedsbeitrag","en":"membership fee"},{"ch":"das Quartier","std":"das Viertel","en":"neighbourhood"},{"ch":"der Neuzuzüger","std":"der Neubürger","en":"newcomer to a town; many towns hold a welcome event for them"}],"dialogue":{"title":"Hast du Lust mitzukommen?","intro":"In der Mittagspause spricht Carla mit ihrem Kollegen Luca über das Wochenende.","speakers":{"F":"Carla","M":"Luca"},"lines":[{"s":"M","de":"Na, Carla, hast du schon Pläne fürs Wochenende?","en":"So, Carla, do you have plans for the weekend yet?","audio":"6928f177f421"},{"s":"F","de":"Noch nicht. Ehrlich gesagt habe ich keine Lust, schon wieder allein zu Hause zu sitzen. Ich möchte mehr Leute kennenlernen.","en":"Not yet. To be honest, I don't feel like sitting at home alone again. I'd like to get to know more people.","audio":"16cae25f6f51"},{"s":"M","de":"Warum gehst du nicht in einen Verein? So habe ich hier die meisten meiner Freunde gefunden.","en":"Why don't you join a club? That's how I found most of my friends here.","audio":"fb738bb5a7a1"},{"s":"F","de":"In einen Verein? Woran denkst du denn?","en":"A club? What are you thinking of?","audio":"c3e9765b91d6"},{"s":"M","de":"Ich bin zum Beispiel in einem Wanderverein. Wir machen jeden Monat einen Ausflug in die Berge. Am Samstag wandern wir auf den Säntis.","en":"I'm in a hiking club, for example. We go on a trip to the mountains every month. On Saturday we're hiking up the Säntis.","audio":"79cb3ceca785"},{"s":"F","de":"Das klingt toll! Ich interessiere mich sehr für die Berge, aber ich habe keine gute Ausrüstung.","en":"That sounds great! I'm very interested in the mountains, but I don't have good gear.","audio":"3630f3fc4e6c"},{"s":"M","de":"Darum musst du dich nicht kümmern. Gute Schuhe reichen am Anfang. Wie wäre es, wenn du einfach einmal mitkommst?","en":"You don't need to worry about that. Good shoes are enough at the start. How about just coming along once?","audio":"eaebb5354f77"},{"s":"F","de":"Gern! Ich freue mich schon darauf. Kostet das etwas?","en":"I'd love to! I'm already looking forward to it. Does it cost anything?","audio":"c0265222e99c"},{"s":"M","de":"Nicht viel. Der Mitgliederbeitrag ist fünfzig Franken pro Jahr, aber beim ersten Mal ist es gratis.","en":"Not much. The membership fee is fifty francs a year, but the first time is free.","audio":"661a4e228528"},{"s":"F","de":"Super. Weisst du, ich träume auch davon, in einem Chor zu singen. In Porto habe ich jahrelang gesungen.","en":"Great. You know, I also dream of singing in a choir. In Porto I sang for years.","audio":"f8d28affbec2"},{"s":"M","de":"Wirklich? Meine Schwester singt in einem Chor in der Altstadt. Sie suchen immer neue Stimmen. Ich kann sie fragen, wann die Proben sind.","en":"Really? My sister sings in a choir in the old town. They're always looking for new voices. I can ask her when the rehearsals are.","audio":"3227b4752315"},{"s":"F","de":"Das wäre wunderbar! Aber vielleicht ist mein Deutsch noch nicht gut genug …","en":"That would be wonderful! But maybe my German isn't good enough yet …","audio":"41d22d03c248"},{"s":"M","de":"Keine Angst. Sie singen sowieso oft auf Englisch oder Latein. Und in der Pause kannst du Deutsch üben.","en":"Don't worry. They often sing in English or Latin anyway. And you can practise German in the break.","audio":"34f7f7852b23"},{"s":"F","de":"Stimmt. Ich erinnere mich noch gut an meine erste Chorprobe in Porto – da war ich auch sehr nervös.","en":"True. I still remember my first choir rehearsal in Porto well – I was very nervous then too.","audio":"d09c8d719261"},{"s":"M","de":"Siehst du! Ich schicke dir heute Abend die Infos für Samstag. Und vergiss nicht, etwas zu essen mitzunehmen!","en":"See! I'll send you the info for Saturday tonight. And don't forget to bring something to eat!","audio":"aa7fd8182e15"},{"s":"F","de":"Mache ich. Danke, Luca!","en":"Will do. Thanks, Luca!","audio":"b682e975509f"}],"questions":[{"type":"tf","q":"Carla möchte mehr Leute kennenlernen.","a":true,"why":"","qEn":"Carla would like to get to know more people."},{"type":"mc","q":"Was macht Lucas Verein?","options":["Er macht jeden Monat einen Ausflug in die Berge.","Er spielt jede Woche Fussball.","Er singt in einem Chor."],"a":0,"qEn":"What does Luca's club do?","optionsEn":["It goes on a trip to the mountains every month.","It plays football every week.","It sings in a choir."]},{"type":"tf","q":"Beim ersten Mal muss Carla fünfzig Franken bezahlen.","a":false,"why":"Beim ersten Mal ist es gratis.","qEn":"Carla has to pay fifty francs the first time.","whyEn":"The first time is free."},{"type":"mc","q":"Wovon träumt Carla?","options":["von einem Haus in den Bergen","davon, in einem Chor zu singen","von einer Reise nach Porto"],"a":1,"qEn":"What does Carla dream of?","optionsEn":["of a house in the mountains","of singing in a choir","of a trip to Porto"]},{"type":"mc","q":"Was soll Carla am Samstag mitnehmen?","options":["etwas zu essen","Wanderstöcke","ein Liederbuch"],"a":0,"qEn":"What should Carla bring on Saturday?","optionsEn":["something to eat","hiking poles","a songbook"]}],"titleEn":"Do you feel like coming along?","introS":[["In der Mittagspause spricht Carla mit ihrem Kollegen Luca über das Wochenende.","During the lunch break Carla talks to her colleague Luca about the weekend.",0]]},"grammar":{"title":"Verben mit Präpositionen, da-/wo-Wörter und zu + Infinitiv","summary":"Viele Verben haben eine feste Präposition. Lernen Sie Verb, Präposition und Kasus immer zusammen.","sections":[{"h":"Feste Präpositionen","table":[["Verb","Präposition","Beispiel"],["sich interessieren","für + Akk.","Ich interessiere mich für Musik."],["sich freuen","auf + Akk. (Zukunft)","Ich freue mich auf den Ausflug."],["sich freuen","über + Akk. (jetzt / vorher)","Ich freue mich über dein Geschenk."],["teilnehmen","an + Dat.","Sie nimmt an einem Kurs teil."],["sich erinnern","an + Akk.","Ich erinnere mich an den Tag."],["träumen","von + Dat.","Er träumt von einem Garten."],["sich kümmern","um + Akk.","Wer kümmert sich um den Hund?"],["warten","auf + Akk.","Wir warten auf den Bus."],["denken","an + Akk.","Ich denke oft an meine Familie."],["Angst haben","vor + Dat.","Sie hat Angst vor Hunden."]],"hEn":"Fixed prepositions"},{"h":"Fragen – wo(r)- oder Präposition + wen/wem","text":"Fragt man nach einer **Sache**: **wo + Präposition** (vor einem Vokal: **wor-**). Fragt man nach einer **Person**: **Präposition + wen / wem**.","examples":[{"de":"==Wofür== interessierst du dich? – Für Musik.","en":"What are you interested in? – Music.","audio":"8993138568bf"},{"de":"==Worauf== wartest du? – Auf den Bus.","en":"What are you waiting for? – The bus.","audio":"566c0a7eaf27"},{"de":"==Auf wen== wartest du? – Auf Luca.","en":"Who are you waiting for? – Luca.","audio":"617d900dcd39"}],"hEn":"Questions – wo(r)- or preposition + wen/wem","textP":[[["Fragt man nach einer **Sache**: **wo + Präposition** (vor einem Vokal: **wor-**).","When you ask about a thing: wo + preposition (before a vowel: wor-).",0],["Fragt man nach einer **Person**: **Präposition + wen / wem**.","When you ask about a person: preposition + wen / wem.",0]]]},{"h":"da(r)-Wörter","text":"Statt Präposition + Sache sagt man oft **da + Präposition** (vor einem Vokal: **dar-**). Bei Personen benutzt man ein Pronomen.","text2":"Ein **da-Wort** kann auch einen ganzen Nebensatz oder einen zu-Infinitiv ankündigen: *Ich träume ==davon==, in einem Chor zu singen. Ich freue mich ==darauf==, dass du kommst.*","examples":[{"de":"Freust du dich auf den Ausflug? – Ja, ich freue mich ==darauf==.","en":"Are you looking forward to the trip? – Yes, I'm looking forward to it.","audio":"eba4e9ed1985"},{"de":"Denkst du an den Termin? – Ja, ich denke ==daran==.","en":"Are you thinking about the appointment? – Yes, I'm thinking about it.","audio":"a6312af168c5"},{"de":"Denkst du an deine Mutter? – Ja, ich denke oft ==an sie==.","en":"Do you think about your mother? – Yes, I often think about her.","audio":"ad187b709e07"}],"hEn":"da(r)- words","textP":[[["Statt Präposition + Sache sagt man oft **da + Präposition** (vor einem Vokal: **dar-**).","Instead of preposition + thing, people often say da + preposition (before a vowel: dar-).",0],["Bei Personen benutzt man ein Pronomen.","For people you use a pronoun.",0]]],"text2P":[[["Ein **da-Wort** kann auch einen ganzen Nebensatz oder einen zu-Infinitiv ankündigen: *Ich träume ==davon==, in einem Chor zu singen.*","A da- word can also announce a whole subordinate clause or a zu-infinitive: I dream of singing in a choir.",0],["*Ich freue mich ==darauf==, dass du kommst.*","I'm looking forward to you coming.",0]]]},{"h":"Infinitiv mit zu","text":"Nach vielen Ausdrücken steht ein **Infinitiv mit zu** am Satzende: *Lust haben, Zeit haben, vergessen, versuchen, anfangen, aufhören, es ist schön / wichtig / schwierig …*\nBei trennbaren Verben steht **zu** in der Mitte: *mit==zu==kommen, kennen==zu==lernen.*","examples":[{"de":"Hast du Lust, am Samstag ==mitzukommen==?","en":"Do you feel like coming along on Saturday?","audio":"d5591a96f8fd"},{"de":"Vergiss nicht, etwas zu essen ==mitzunehmen==.","en":"Don't forget to bring something to eat.","audio":"5a7bec54fe17"},{"de":"Es ist schön, neue Leute ==kennenzulernen==.","en":"It's nice to meet new people.","audio":"625825ddc728"}],"hEn":"Infinitive with zu","textP":[[["Nach vielen Ausdrücken steht ein **Infinitiv mit zu** am Satzende: *Lust haben, Zeit haben, vergessen, versuchen, anfangen, aufhören, es ist schön / wichtig / schwierig …*","After many expressions an infinitive with zu goes at the end of the sentence: Lust haben, Zeit haben, vergessen, versuchen, anfangen, aufhören, es ist schön / wichtig / schwierig …",0],["Bei trennbaren Verben steht **zu** in der Mitte: *mit==zu==kommen, kennen==zu==lernen.*","With separable verbs, zu goes in the middle: mitzukommen, kennenzulernen.",1]]]}],"tip":"Kein „zu\" nach Modalverben: „Ich möchte mitkommen\" (nicht „Ich möchte mitzukommen\"). Und: sich freuen auf = etwas kommt noch; sich freuen über = etwas ist schon da.","titleEn":"Verbs with prepositions, da-/wo- words and zu + infinitive","summaryS":[["Viele Verben haben eine feste Präposition.","Many verbs have a fixed preposition.",0],["Lernen Sie Verb, Präposition und Kasus immer zusammen.","Always learn the verb, preposition and case together.",0]],"tipP":[[["Kein „zu\" nach Modalverben: „Ich möchte mitkommen\" (nicht „Ich möchte mitzukommen\").","No \"zu\" after modal verbs: \"Ich möchte mitkommen\" (not \"Ich möchte mitzukommen\").",0],["Und: sich freuen auf = etwas kommt noch; sich freuen über = etwas ist schon da.","And: sich freuen auf = something is still to come; sich freuen über = something is already here.",0]]]},"exercises":[{"type":"choice","title":"Welche Präposition passt?","items":[{"q":"Ich interessiere mich ___ Musik.","options":["für","an","auf"],"a":0,"full":"Ich interessiere mich für Musik.","audio":"f1983b750ae4","en":"I'm interested in music."},{"q":"Wir freuen uns schon ___ die Ferien.","options":["auf","über","für"],"a":0,"full":"Wir freuen uns schon auf die Ferien.","audio":"2e6fb9610fc0","en":"We're already looking forward to the holidays."},{"q":"Nimmst du am Samstag ___ der Wanderung teil?","options":["an","auf","für"],"a":0,"full":"Nimmst du am Samstag an der Wanderung teil?","audio":"bb6a317d9ca9","en":"Are you taking part in the hike on Saturday?"},{"q":"Er erinnert sich gern ___ seine Kindheit.","options":["an","von","über"],"a":0,"full":"Er erinnert sich gern an seine Kindheit.","audio":"ae9e3305328d","en":"He likes to remember his childhood."},{"q":"Sie träumt ___ einem eigenen Garten.","options":["von","über","für"],"a":0,"full":"Sie träumt von einem eigenen Garten.","audio":"4f7fa1be92f6","en":"She dreams of having her own garden."},{"q":"Wer kümmert sich ___ die Katze, wenn du weg bist?","options":["um","für","auf"],"a":0,"full":"Wer kümmert sich um die Katze, wenn du weg bist?","audio":"006271e9e327","en":"Who will look after the cat when you're away?"},{"q":"Ich habe mich sehr ___ dein Geschenk gefreut.","options":["über","auf","an"],"a":0,"full":"Ich habe mich sehr über dein Geschenk gefreut.","audio":"2b1c623831f4","en":"I was really pleased about your present."},{"q":"Warte bitte ___ mich!","options":["auf","für","an"],"a":0,"full":"Warte bitte auf mich!","audio":"5bfed64ee2cf","en":"Please wait for me!"}],"titleEn":"Which preposition fits?"},{"type":"gap","title":"wo(r)- oder da(r)-?","items":[{"q":"___ interessierst du dich? – Für Fotografie.","a":["Wofür"],"full":"Wofür interessierst du dich? – Für Fotografie.","audio":"65dc3ef797c0","en":"What are you interested in? – Photography."},{"q":"___ wartest du? – Auf den Bus.","a":["Worauf"],"full":"Worauf wartest du? – Auf den Bus.","audio":"566c0a7eaf27","en":"What are you waiting for? – The bus."},{"q":"Freust du dich auf das Konzert? – Ja, ich freue mich sehr ___.","a":["darauf"],"full":"Freust du dich auf das Konzert? – Ja, ich freue mich sehr darauf.","audio":"e2c5a4b16bdf","en":"Are you looking forward to the concert? – Yes, I'm really looking forward to it."},{"q":"Denkst du an den Termin? – Ja, ich denke ___.","a":["daran"],"full":"Denkst du an den Termin? – Ja, ich denke daran.","audio":"a6312af168c5","en":"Are you thinking about the appointment? – Yes, I'm thinking about it."},{"q":"___ träumst du? – Von einer Reise nach Japan.","a":["Wovon"],"full":"Wovon träumst du? – Von einer Reise nach Japan.","audio":"4c3134beace1","en":"What do you dream of? – A trip to Japan."},{"q":"Nimmst du an dem Kurs teil? – Nein, ich nehme nicht ___ teil.","a":["daran"],"full":"Nimmst du an dem Kurs teil? – Nein, ich nehme nicht daran teil.","audio":"4c7cf6837d3f","en":"Are you taking part in the course? – No, I'm not taking part in it."}],"titleEn":"wo(r)- or da(r)-?"},{"type":"gap","title":"Infinitiv mit zu","items":[{"q":"Ich habe keine Lust, heute ___. (kochen)","a":["zu kochen"],"full":"Ich habe keine Lust, heute zu kochen.","audio":"09c60c04e291","en":"I don't feel like cooking today."},{"q":"Vergiss nicht, etwas zu essen ___. (mitnehmen)","a":["mitzunehmen"],"full":"Vergiss nicht, etwas zu essen mitzunehmen.","audio":"5a7bec54fe17","en":"Don't forget to bring something to eat."},{"q":"Es ist schön, neue Leute ___. (kennenlernen)","a":["kennenzulernen"],"full":"Es ist schön, neue Leute kennenzulernen.","audio":"625825ddc728","en":"It's nice to meet new people."},{"q":"Ich versuche, jeden Tag Deutsch ___. (sprechen)","a":["zu sprechen"],"full":"Ich versuche, jeden Tag Deutsch zu sprechen.","audio":"95ab3e3e4bdd","en":"I try to speak German every day."},{"q":"Wann hast du angefangen, Klavier ___? (spielen)","a":["zu spielen"],"full":"Wann hast du angefangen, Klavier zu spielen?","audio":"910f41cd26ee","en":"When did you start playing the piano?"},{"q":"Hast du Zeit, am Samstag ___? (mitkommen)","a":["mitzukommen"],"full":"Hast du Zeit, am Samstag mitzukommen?","audio":"15c3b7bbad9f","en":"Do you have time to come along on Saturday?"}],"titleEn":"Infinitive with zu"},{"type":"order","title":"Bilden Sie Sätze","items":[{"a":["Ich interessiere mich schon lange für Fotografie."],"tokens":["Ich","interessiere","mich","schon","lange","für","Fotografie."],"audio":"e6cfcc8ed93e","en":"I've been interested in photography for a long time."},{"a":["Wir freuen uns auf den Ausflug in die Berge."],"tokens":["Wir","freuen","uns","auf","den","Ausflug","in","die","Berge."],"audio":"fca2d72eae87","en":"We're looking forward to the trip to the mountains."},{"a":["Ich träume davon, in einem Chor zu singen."],"tokens":["Ich","träume","davon,","in","einem","Chor","zu","singen."],"audio":"b58b594e484a","en":"I dream of singing in a choir."},{"a":["Hast du Lust, am Samstag mitzukommen?"],"tokens":["Hast","du","Lust,","am","Samstag","mitzukommen?"],"audio":"d5591a96f8fd","en":"Do you feel like coming along on Saturday?"},{"a":["Woran denkst du gerade?"],"tokens":["Woran","denkst","du","gerade?"],"audio":"899dea7d136c","en":"What are you thinking about right now?"}],"titleEn":"Make sentences"},{"type":"dictation","title":"Diktat – hören und schreiben","items":[{"a":"Ich interessiere mich sehr für die Berge.","audio":"8a9cf7ee5b9c","en":"I'm very interested in the mountains."},{"a":"Hast du Lust, am Samstag mitzukommen?","audio":"722355d4b3c4","en":"Do you feel like coming along on Saturday?"},{"a":"Ich freue mich schon darauf.","audio":"d1743f0dcd50","en":"I'm already looking forward to it."},{"a":"Vergiss nicht, etwas zu essen mitzunehmen.","audio":"107e54979106","en":"Don't forget to bring something to eat."}],"titleEn":"Dictation – listen and write"}],"reading":{"title":"Mitmachen im Quartier","kind":"Zeitungsartikel","paras":[{"t":"In der Schweiz gibt es sehr viele Vereine – für Sport, Musik, Kultur, Natur und vieles mehr. Wer neu in einer Gemeinde ist, findet in einem Verein schnell Kontakt. Wir haben mit Sandra Meier gesprochen. Sie ist seit acht Jahren Präsidentin des Quartiervereins Rosenberg.","audio":"bbe82f5ab6cf","s":[["In der Schweiz gibt es sehr viele Vereine – für Sport, Musik, Kultur, Natur und vieles mehr.","There are a great many clubs in Switzerland – for sport, music, culture, nature and much more.",0],["Wer neu in einer Gemeinde ist, findet in einem Verein schnell Kontakt.","If you're new in a municipality, you quickly make contacts in a club.",0],["Wir haben mit Sandra Meier gesprochen.","We spoke to Sandra Meier.",0],["Sie ist seit acht Jahren Präsidentin des Quartiervereins Rosenberg.","She has been president of the Rosenberg neighbourhood association for eight years.",0]]},{"t":"„Unser Verein kümmert sich um das Leben im Quartier\", erzählt sie. „Wir organisieren jedes Jahr ein Sommerfest, einen Flohmarkt und im Dezember einen kleinen Weihnachtsmarkt. Ausserdem gibt es jeden Mittwoch einen Mittagstisch für ältere Menschen.\" Alle Mitglieder arbeiten ehrenamtlich, also ohne Lohn.","audio":"fef53eb53256","s":[["„Unser Verein kümmert sich um das Leben im Quartier\", erzählt sie.","\"Our association looks after life in the neighbourhood,\" she says.",0],["„Wir organisieren jedes Jahr ein Sommerfest, einen Flohmarkt und im Dezember einen kleinen Weihnachtsmarkt.","\"Every year we organise a summer party, a flea market and a small Christmas market in December.",0],["Ausserdem gibt es jeden Mittwoch einen Mittagstisch für ältere Menschen.\"","There's also a shared lunch for older people every Wednesday.\"",0],["Alle Mitglieder arbeiten ehrenamtlich, also ohne Lohn.","All members work as volunteers, so without pay.",0]]},{"t":"Besonders freut sich Sandra Meier darüber, dass immer mehr Neuzuzüger mitmachen. „Letztes Jahr hat eine Familie aus Syrien am Sommerfest gekocht. Nach einer Stunde war das ganze Essen weg!\" Viele neue Mitglieder erzählen, dass sie im Verein ihre ersten Schweizer Freunde gefunden haben – und dass sie dort viel Deutsch üben konnten.","audio":"a3328d8bcd2a","s":[["Besonders freut sich Sandra Meier darüber, dass immer mehr Neuzuzüger mitmachen.","Sandra Meier is particularly pleased that more and more newcomers are joining in.",0],["„Letztes Jahr hat eine Familie aus Syrien am Sommerfest gekocht.","\"Last year a family from Syria cooked at the summer party.",0],["Nach einer Stunde war das ganze Essen weg!\"","After an hour all the food was gone!\"",0],["Viele neue Mitglieder erzählen, dass sie im Verein ihre ersten Schweizer Freunde gefunden haben – und dass sie dort viel Deutsch üben konnten.","Many new members say that they found their first Swiss friends in the association – and that they were able to practise a lot of German there.",0]]},{"t":"Wer Lust hat, mitzumachen, kann einfach an einer Veranstaltung teilnehmen. Der Mitgliederbeitrag kostet 30 Franken pro Jahr, für Familien 50 Franken. Man muss aber nicht Mitglied sein, um zu helfen. „Jede Hilfe ist willkommen\", sagt Sandra Meier, „auch nur für einen Nachmittag.\"","audio":"241bfec94e6d","s":[["Wer Lust hat, mitzumachen, kann einfach an einer Veranstaltung teilnehmen.","Anyone who wants to join in can simply take part in an event.",0],["Der Mitgliederbeitrag kostet 30 Franken pro Jahr, für Familien 50 Franken.","The membership fee is 30 francs a year, 50 francs for families.",0],["Man muss aber nicht Mitglied sein, um zu helfen.","But you don't have to be a member to help.",0],["„Jede Hilfe ist willkommen\", sagt Sandra Meier, „auch nur für einen Nachmittag.\"","\"Any help is welcome,\" says Sandra Meier, \"even for just one afternoon.\"",0]]}],"glossary":[{"de":"die Präsidentin","en":"president, chair"},{"de":"der Flohmarkt","en":"flea market"},{"de":"der Mittagstisch","en":"shared lunch (often for seniors)"},{"de":"der Neuzuzüger (CH)","en":"newcomer to a town"},{"de":"mitmachen","en":"to join in"},{"de":"willkommen","en":"welcome"}],"questions":[{"type":"tf","q":"Sandra Meier ist seit acht Jahren Präsidentin des Vereins.","a":true,"why":"","qEn":"Sandra Meier has been president of the club for eight years."},{"type":"mc","q":"Was organisiert der Verein nicht?","options":["ein Sommerfest","einen Flohmarkt","ein Fussballturnier"],"a":2,"qEn":"What does the club not organise?","optionsEn":["a summer party","a flea market","a football tournament"]},{"type":"tf","q":"Die Mitglieder bekommen einen kleinen Lohn.","a":false,"why":"Sie arbeiten ehrenamtlich, also ohne Lohn.","qEn":"The members get a small wage.","whyEn":"They work as volunteers, so without pay."},{"type":"mc","q":"Worüber freut sich Sandra Meier besonders?","options":["dass immer mehr Neuzuzüger mitmachen","dass der Verein viel Geld hat","dass das Sommerfest so gross ist"],"a":0,"qEn":"What is Sandra Meier particularly pleased about?","optionsEn":["that more and more newcomers are joining in","that the club has a lot of money","that the summer party is so big"]},{"type":"mc","q":"Was muss man machen, wenn man helfen möchte?","options":["Mitglied werden","fünfzig Franken bezahlen","einfach an einer Veranstaltung teilnehmen"],"a":2,"qEn":"What do you have to do if you want to help?","optionsEn":["become a member","pay fifty francs","simply take part in an event"]}],"titleEn":"Getting involved in the neighbourhood"},"writing":{"task":"Sie möchten beim Quartierverein mitmachen. Schreiben Sie eine E-Mail an Frau Meier (80–100 Wörter).","points":["Stellen Sie sich vor.","Wofür interessieren Sie sich?","Wobei möchten Sie helfen?","Stellen Sie eine Frage zum nächsten Treffen."],"phrases":[{"de":"Ich habe den Artikel über … gelesen.","en":"I read the article about …"},{"de":"Ich interessiere mich für …","en":"I'm interested in …"},{"de":"Ich hätte Lust, bei … mitzuhelfen.","en":"I'd like to help with …"},{"de":"Können Sie mir sagen, wann …?","en":"Could you tell me when …?"},{"de":"Ich freue mich darauf, Sie kennenzulernen.","en":"I look forward to meeting you."}],"model":"Liebe Frau Meier\n\nIch habe im Gemeindeblatt den Artikel über den Quartierverein gelesen. Ich heisse Carla, komme aus Portugal und wohne seit einem Jahr im Rosenberg-Quartier. Ich interessiere mich sehr für Ihre Arbeit, weil ich gern neue Leute kennenlernen möchte. Am liebsten würde ich beim Sommerfest helfen – ich koche gern und könnte portugiesische Spezialitäten machen. Ausserdem hätte ich Lust, beim Mittagstisch mitzuhelfen. Können Sie mir sagen, wann das nächste Treffen stattfindet? Ich freue mich darauf, Sie kennenzulernen.\n\nHerzliche Grüsse\nCarla Ferreira","audio":"535a6c411300","taskS":[["Sie möchten beim Quartierverein mitmachen.","You would like to get involved in the neighbourhood association.",0],["Schreiben Sie eine E-Mail an Frau Meier (80–100 Wörter).","Write an email to Ms Meier (80–100 words).",0]],"pointsEn":["Introduce yourself.","What are you interested in?","What would you like to help with?","Ask a question about the next meeting."],"modelP":[[["Liebe Frau Meier","Dear Ms Meier",0]],[["Ich habe im Gemeindeblatt den Artikel über den Quartierverein gelesen.","I read the article about the neighbourhood association in the local newsletter.",0],["Ich heisse Carla, komme aus Portugal und wohne seit einem Jahr im Rosenberg-Quartier.","My name is Carla, I'm from Portugal and I've been living in the Rosenberg neighbourhood for a year.",0],["Ich interessiere mich sehr für Ihre Arbeit, weil ich gern neue Leute kennenlernen möchte.","I'm very interested in your work because I'd like to meet new people.",0],["Am liebsten würde ich beim Sommerfest helfen – ich koche gern und könnte portugiesische Spezialitäten machen.","I'd most like to help at the summer party – I like cooking and could make Portuguese specialities.",0],["Ausserdem hätte ich Lust, beim Mittagstisch mitzuhelfen.","I'd also like to help out at the shared lunch.",0],["Können Sie mir sagen, wann das nächste Treffen stattfindet?","Could you tell me when the next meeting takes place?",0],["Ich freue mich darauf, Sie kennenzulernen.","I look forward to meeting you.",0]],[["Herzliche Grüsse","Warm regards",0],["Carla Ferreira","Carla Ferreira",1]]]},"speaking":{"task":"Sprechen Sie über Ihre Freizeit. Antworten Sie in drei bis vier Sätzen.","phrases":[{"de":"In meiner Freizeit …","en":"In my free time …","audio":null},{"de":"Ich interessiere mich für …","en":"I'm interested in …","audio":null},{"de":"Ich freue mich auf …","en":"I'm looking forward to …","audio":null},{"de":"Ich habe (keine) Lust, … zu …","en":"I (don't) feel like …","audio":null},{"de":"Ich bin Mitglied in …","en":"I'm a member of …","audio":null}],"prompts":[{"q":"Was machen Sie gern in Ihrer Freizeit?","model":"In meiner Freizeit gehe ich gern wandern, und ich singe gern. Am Wochenende treffe ich mich oft mit Freunden.","aq":"464df6622414","am":"40f2970a96fd","qS":[["Was machen Sie gern in Ihrer Freizeit?","What do you like doing in your free time?",0]],"modelS":[["In meiner Freizeit gehe ich gern wandern, und ich singe gern.","In my free time I like going hiking, and I like singing.",0],["Am Wochenende treffe ich mich oft mit Freunden.","At the weekend I often meet up with friends.",0]]},{"q":"Wofür interessieren Sie sich besonders?","model":"Ich interessiere mich besonders für Musik und für die Natur. Deshalb möchte ich in einem Chor singen und öfter in den Bergen wandern.","aq":"26c518f3485a","am":"65fdcab0dda4","qS":[["Wofür interessieren Sie sich besonders?","What are you especially interested in?",0]],"modelS":[["Ich interessiere mich besonders für Musik und für die Natur.","I'm especially interested in music and nature.",0],["Deshalb möchte ich in einem Chor singen und öfter in den Bergen wandern.","That's why I'd like to sing in a choir and go hiking in the mountains more often.",0]]},{"q":"Worauf freuen Sie sich im Moment?","model":"Ich freue mich auf den Ausflug am Samstag. Wir wandern mit dem Verein auf den Säntis.","aq":"f5dd83297aac","am":"b116c375eacf","qS":[["Worauf freuen Sie sich im Moment?","What are you looking forward to at the moment?",0]],"modelS":[["Ich freue mich auf den Ausflug am Samstag.","I'm looking forward to the trip on Saturday.",0],["Wir wandern mit dem Verein auf den Säntis.","We're hiking up the Säntis with the club.",0]]},{"q":"Sind Vereine eine gute Idee für Leute, die neu in der Schweiz sind? Warum?","model":"Ja, ich finde schon. In einem Verein lernt man schnell Leute kennen, und man kann Deutsch üben. Ausserdem lernt man viel über das Leben in der Schweiz.","aq":"69e6e94d415e","am":"232d5e4e4661","qS":[["Sind Vereine eine gute Idee für Leute, die neu in der Schweiz sind?","Are clubs a good idea for people who are new to Switzerland?",0],["Warum?","Why?",0]],"modelS":[["Ja, ich finde schon.","Yes, I think so.",0],["In einem Verein lernt man schnell Leute kennen, und man kann Deutsch üben.","In a club you quickly get to know people, and you can practise German.",0],["Ausserdem lernt man viel über das Leben in der Schweiz.","You also learn a lot about life in Switzerland.",0]]}],"taskS":[["Sprechen Sie über Ihre Freizeit.","Talk about your free time.",0],["Antworten Sie in drei bis vier Sätzen.","Answer in three to four sentences.",0]]},"en":{"title":"Free time and clubs","subtitle":"Hobbies, plans and meeting people","focus":"Verbs with prepositions, da-/wo- words, infinitive with zu"}},{"id":9,"title":"Abfall und Umwelt","subtitle":"Recycling nach Schweizer Regeln","level":"B1","theme":"Umwelt","focus":"Passiv (Präsens, Präteritum, mit Modalverb) und um … zu / damit","goals":[{"de":"Ich kann ein Merkblatt der Gemeinde über Abfall verstehen.","en":"I can understand a municipal leaflet about waste."},{"de":"Ich kann erklären, wie etwas gemacht wird (Passiv).","en":"I can explain how something is done (passive)."},{"de":"Ich kann sagen, warum man etwas macht (um … zu, damit).","en":"I can say why something is done."}],"vocab":[{"id":"9-0","de":"der Abfall","forms":"Abfälle","en":"waste, rubbish","ex":"Wohin kommt dieser Abfall?","exEn":"Where does this rubbish go?","aw":"d25745d82544","ae":"9a8bccfce9ca"},{"id":"9-1","de":"der Gebührensack","forms":"-säcke","en":"official fee-paid rubbish bag (CH)","ex":"Ohne Gebührensack wird der Abfall nicht mitgenommen.","exEn":"Without an official bag the rubbish isn't collected.","aw":"58e68ffc7997","ae":"1f6d100f6ebf"},{"id":"9-2","de":"trennen","forms":"hat getrennt","en":"to separate, sort","ex":"In der Schweiz trennt man den Abfall sehr genau.","exEn":"In Switzerland people sort their waste very carefully.","aw":"be229a78c4f5","ae":"804cb2d1d4a3"},{"id":"9-3","de":"entsorgen","forms":"hat entsorgt","en":"to dispose of","ex":"Wo kann ich alte Möbel entsorgen?","exEn":"Where can I dispose of old furniture?","aw":"7eab783482ef","ae":"e56b9a34e133"},{"id":"9-4","de":"das Altpapier","forms":"–","en":"waste paper","ex":"Das Altpapier wird einmal im Monat gesammelt.","exEn":"Waste paper is collected once a month.","aw":"6fa825704c00","ae":"c5b98b421219"},{"id":"9-5","de":"der Karton","forms":"-s","en":"cardboard","ex":"Karton und Papier kommen nicht ins gleiche Bündel.","exEn":"Cardboard and paper don't go in the same bundle.","aw":"cdc680862ac1","ae":"845f5a4345a8"},{"id":"9-6","de":"bündeln","forms":"hat gebündelt","en":"to bundle, tie up","ex":"Das Papier muss mit einer Schnur gebündelt werden.","exEn":"The paper has to be tied up with string.","aw":"fd7382ab268f","ae":"856a265ca1da"},{"id":"9-7","de":"die Sammelstelle","forms":"-n","en":"collection point","ex":"Glas bringe ich zur Sammelstelle beim Schulhaus.","exEn":"I take glass to the collection point by the school.","aw":"67d40e6afe3a","ae":"223fdbc367a5"},{"id":"9-8","de":"die PET-Flasche","forms":"-n","en":"plastic (PET) bottle","ex":"PET-Flaschen gibt man im Supermarkt zurück.","exEn":"You return PET bottles at the supermarket.","aw":"79eef320dcb9","ae":"d67b5bc41a93"},{"id":"9-9","de":"das Grüngut","forms":"–","en":"green waste (CH)","ex":"Das Grüngut wird im Sommer jede Woche abgeholt.","exEn":"Green waste is collected every week in summer.","aw":"5124b0fa7170","ae":"fe6b049ce259"},{"id":"9-10","de":"die Batterie","forms":"-n","en":"battery","ex":"Alte Batterien darf man nicht in den Abfall werfen.","exEn":"You mustn't throw old batteries in the rubbish.","aw":"a7a89038a75f","ae":"8d5b701aed17"},{"id":"9-11","de":"abholen","forms":"hat abgeholt","en":"to collect, pick up","ex":"Der Abfall wird am Dienstag abgeholt.","exEn":"The rubbish is collected on Tuesday.","aw":"2a1e2938efef","ae":"877e8be31b9d"},{"id":"9-12","de":"bereitstellen","forms":"hat bereitgestellt","en":"to put out (ready)","ex":"Stellen Sie die Säcke erst am Morgen bereit.","exEn":"Only put the bags out in the morning.","aw":"fdcc247233cd","ae":"b52792d0476e"},{"id":"9-13","de":"die Busse","forms":"-n","en":"fine (CH)","ex":"Er musste eine Busse von hundert Franken bezahlen.","exEn":"He had to pay a fine of a hundred francs.","aw":"655e2c6a862e","ae":"0fd041972b83"},{"id":"9-14","de":"die Umwelt","forms":"–","en":"environment","ex":"Recycling ist gut für die Umwelt.","exEn":"Recycling is good for the environment.","aw":"fa059f8dfe84","ae":"86e4dfa94b74"},{"id":"9-15","de":"schützen","forms":"hat geschützt","en":"to protect","ex":"Wir wollen die Natur schützen.","exEn":"We want to protect nature.","aw":"6e03f1bf2ce5","ae":"74c7e7d6cbbf"},{"id":"9-16","de":"der Abfallkalender","forms":"-","en":"waste collection calendar","ex":"Im Abfallkalender stehen alle Termine.","exEn":"All the dates are in the waste calendar.","aw":"b33c87933a6e","ae":"d23ff6eadd5a"},{"id":"9-17","de":"recyceln","forms":"hat recycelt","en":"to recycle","ex":"Aus alten Flaschen werden neue Flaschen recycelt.","exEn":"Old bottles are recycled into new ones.","aw":"4cfd98ee0210","ae":"89caf604db70"},{"id":"9-18","de":"wegwerfen","forms":"hat weggeworfen","en":"to throw away","ex":"Wirf das nicht weg, das kann man noch reparieren!","exEn":"Don't throw that away, it can still be repaired!","aw":"dce933c72304","ae":"510c56885ab8"},{"id":"9-19","de":"verboten","forms":"–","en":"forbidden, prohibited","ex":"Abfall im Wald zu entsorgen ist verboten.","exEn":"Dumping rubbish in the forest is prohibited.","aw":"29cae5fb9137","ae":"1595b26624f7"}],"swiss":[{"ch":"der Kehricht","std":"der Restmüll","en":"household rubbish"},{"ch":"der Gebührensack","std":"–","en":"official paid rubbish bag; ordinary bags are not collected"},{"ch":"die Busse","std":"das Bussgeld","en":"fine"},{"ch":"der Werkhof","std":"der Bauhof","en":"municipal depot, often with a recycling point"},{"ch":"das Schulhaus","std":"das Schulgebäude","en":"school building"}],"dialogue":{"title":"Der Sack wurde nicht abgeholt","intro":"Carla trifft ihre Nachbarin Frau Rossi im Treppenhaus. Frau Rossi hat ein Problem bemerkt.","speakers":{"F":"Carla","W":"Frau Rossi"},"lines":[{"s":"W","de":"Hallo Frau Ferreira! Haben Sie kurz Zeit? Ich möchte Ihnen etwas zeigen.","en":"Hello Ms Ferreira! Do you have a moment? I'd like to show you something.","audio":"116dd9403c55"},{"s":"F","de":"Hallo Frau Rossi. Ja, natürlich. Was ist los?","en":"Hello Ms Rossi. Yes, of course. What's up?","audio":"f9c9e79b6772"},{"s":"W","de":"Gestern stand ein Abfallsack vor dem Haus, der nicht abgeholt wurde. Ich glaube, er gehört Ihnen.","en":"Yesterday there was a rubbish bag in front of the building that wasn't collected. I think it's yours.","audio":"b62646c02d39"},{"s":"F","de":"Oh nein! Warum wurde er denn nicht abgeholt?","en":"Oh no! Why wasn't it collected?","audio":"bc97cefa8a3f"},{"s":"W","de":"Weil es kein offizieller Gebührensack war. Hier werden nur die offiziellen Säcke mitgenommen. Die kann man im Supermarkt kaufen.","en":"Because it wasn't an official fee bag. Only official bags are taken here. You can buy them at the supermarket.","audio":"2a74c88760d0"},{"s":"F","de":"Das wusste ich nicht! In Portugal wird der Abfall einfach in grosse Container geworfen.","en":"I didn't know that! In Portugal rubbish is simply thrown into big containers.","audio":"a394e8330516"},{"s":"W","de":"Hier ist es ein bisschen komplizierter. Aber keine Sorge, ich erkläre es Ihnen. Altpapier und Karton werden separat gesammelt, einmal im Monat.","en":"Here it's a bit more complicated. But don't worry, I'll explain it to you. Waste paper and cardboard are collected separately, once a month.","audio":"4bee8cf3feea"},{"s":"F","de":"Und wie wird das Papier bereitgestellt?","en":"And how is the paper put out?","audio":"2390da541e0e"},{"s":"W","de":"Es wird gebündelt, also mit einer Schnur zusammengebunden, und am Morgen an die Strasse gestellt. Die Daten stehen im Abfallkalender.","en":"It's bundled, so tied together with string, and put out on the street in the morning. The dates are in the waste calendar.","audio":"1171c68b132e"},{"s":"F","de":"Und was mache ich mit Glasflaschen?","en":"And what do I do with glass bottles?","audio":"4f57fc54b771"},{"s":"W","de":"Glas bringt man zur Sammelstelle beim Schulhaus. Aber bitte nicht am Sonntag oder am Abend, damit die Nachbarn nicht gestört werden.","en":"You take glass to the collection point by the school. But please not on Sundays or in the evening, so that the neighbours aren't disturbed.","audio":"fc9f8180c8c4"},{"s":"F","de":"Und PET-Flaschen?","en":"And PET bottles?","audio":"647e2f0e547d"},{"s":"W","de":"Die können Sie im Supermarkt zurückgeben. Dort werden auch alte Batterien angenommen.","en":"You can return those at the supermarket. Old batteries are accepted there too.","audio":"b6cf261aafc1"},{"s":"F","de":"Warum ist das alles so genau geregelt?","en":"Why is all this so precisely regulated?","audio":"97a0f0c99006"},{"s":"W","de":"Um Rohstoffe zu sparen und die Umwelt zu schützen. Und die Gebührensäcke sind teuer, damit die Leute weniger Abfall produzieren.","en":"To save raw materials and protect the environment. And the fee bags are expensive so that people produce less rubbish.","audio":"bc569050ee22"},{"s":"F","de":"Das macht Sinn. Bekommt man eigentlich eine Busse, wenn man es falsch macht?","en":"That makes sense. Do you actually get a fine if you do it wrong?","audio":"5cdd95dbaa4e"},{"s":"W","de":"Das kann passieren. Aber beim ersten Mal wird man meistens nur informiert.","en":"That can happen. But the first time you're usually just informed.","audio":"17589a3a44e5"},{"s":"F","de":"Vielen Dank, Frau Rossi! Ich kaufe heute noch Gebührensäcke.","en":"Thank you so much, Ms Rossi! I'll buy fee bags today.","audio":"2f91edd4558e"},{"s":"W","de":"Gern geschehen. Den Abfallkalender lege ich Ihnen in den Briefkasten.","en":"You're welcome. I'll put the waste calendar in your letterbox.","audio":"1c86fe113880"}],"questions":[{"type":"tf","q":"Carlas Abfallsack wurde nicht abgeholt.","a":true,"why":"","qEn":"Carla's rubbish bag wasn't collected."},{"type":"mc","q":"Warum wurde der Sack nicht abgeholt?","options":["Er war zu schwer.","Es war kein offizieller Gebührensack.","Er stand am falschen Tag vor dem Haus."],"a":1,"qEn":"Why wasn't the bag collected?","optionsEn":["It was too heavy.","It wasn't an official fee bag.","It was outside the building on the wrong day."]},{"type":"mc","q":"Wie wird das Altpapier bereitgestellt?","options":["in einem Gebührensack","gebündelt an der Strasse","in einem Container im Keller"],"a":1,"qEn":"How is waste paper put out?","optionsEn":["in a fee bag","bundled by the street","in a container in the basement"]},{"type":"tf","q":"Glas darf man am Sonntag zur Sammelstelle bringen.","a":false,"why":"Nicht am Sonntag und nicht am Abend.","qEn":"You're allowed to take glass to the collection point on Sundays.","whyEn":"Not on Sundays and not in the evening."},{"type":"mc","q":"Warum sind die Gebührensäcke teuer?","options":["damit die Leute weniger Abfall produzieren","damit die Gemeinde mehr Geld hat","um die Säcke zu recyceln"],"a":0,"qEn":"Why are the fee bags expensive?","optionsEn":["so that people produce less rubbish","so that the municipality has more money","to recycle the bags"]}],"titleEn":"The bag wasn't collected","introS":[["Carla trifft ihre Nachbarin Frau Rossi im Treppenhaus.","Carla meets her neighbour Ms Rossi in the stairwell.",0],["Frau Rossi hat ein Problem bemerkt.","Ms Rossi has noticed a problem.",0]]},"grammar":{"title":"Das Passiv und um … zu / damit","summary":"Im Passiv ist die Handlung wichtig, nicht die Person.","sections":[{"h":"Aktiv oder Passiv?","text":"**Aktiv:** Wer macht etwas? *Die Müllabfuhr holt den Abfall ab.*\n**Passiv:** Was passiert? *Der Abfall ==wird== ==abgeholt==.* – Wer es macht, ist nicht wichtig oder nicht bekannt. (Wenn nötig: **von** + Dativ: *von der Müllabfuhr*.)","hEn":"Active or passive?","textP":[[["**Aktiv:** Wer macht etwas?","Active: who does something?",0],["*Die Müllabfuhr holt den Abfall ab.*","The refuse collectors pick up the rubbish.",0],["**Passiv:** Was passiert?","Passive: what happens?",1],["*Der Abfall ==wird== ==abgeholt==.* – Wer es macht, ist nicht wichtig oder nicht bekannt. (Wenn nötig: **von** + Dativ: *von der Müllabfuhr*.)","The rubbish is collected. – Who does it isn't important or isn't known. (If needed: von + dative: by the refuse collectors.)",0]]]},{"h":"Passiv Präsens – werden + Partizip II","table":[["Person","werden","Beispiel"],["ich","werde","Ich werde informiert."],["du","wirst","Du wirst abgeholt."],["er/sie/es","wird","Der Abfall wird abgeholt."],["wir","werden","Wir werden eingeladen."],["ihr","werdet","Ihr werdet gefragt."],["sie/Sie","werden","Die Flaschen werden recycelt."]],"examples":[{"de":"Papier und Karton ==werden== separat ==gesammelt==.","en":"Paper and cardboard are collected separately.","audio":"0cf1eda61ce7"},{"de":"Hier ==wird== viel ==recycelt==.","en":"A lot is recycled here.","audio":"e4dcfe1dc4f7"}],"hEn":"Present passive – werden + past participle"},{"h":"Passiv Präteritum – wurde + Partizip II","text":"Für die Vergangenheit benutzt man im Passiv meistens das **Präteritum**: *ich wurde, du wurdest, er/sie/es wurde, wir wurden, ihr wurdet, sie wurden.*","examples":[{"de":"Der Sack ==wurde== nicht ==abgeholt==.","en":"The bag wasn't collected.","audio":"526c92457a8b"},{"de":"Die Sammelstelle ==wurde== letztes Jahr ==gebaut==.","en":"The collection point was built last year.","audio":"4be690822640"}],"hEn":"Simple past passive – wurde + past participle","textP":[[["Für die Vergangenheit benutzt man im Passiv meistens das **Präteritum**: *ich wurde, du wurdest, er/sie/es wurde, wir wurden, ihr wurdet, sie wurden.*","For the past, the passive is usually used in the simple past: ich wurde, du wurdest, er/sie/es wurde, wir wurden, ihr wurdet, sie wurden.",0]]]},{"h":"Passiv mit Modalverb","text":"Modalverb (Position 2) … **Partizip II + werden** (am Ende).","examples":[{"de":"Das Papier ==muss== ==gebündelt werden==.","en":"The paper has to be bundled.","audio":"36661d04b4f8"},{"de":"Batterien ==dürfen== nicht in den Abfall ==geworfen werden==.","en":"Batteries must not be thrown in the rubbish.","audio":"e52e6336d116"}],"hEn":"Passive with a modal verb","textP":[[["Modalverb (Position 2) … **Partizip II + werden** (am Ende).","Modal verb (position 2) … past participle + werden (at the end).",0]]]},{"h":"Ziel und Zweck – um … zu oder damit?","text":"**um … zu + Infinitiv:** nur wenn das Subjekt in beiden Teilen **gleich** ist.\n**damit + Nebensatz:** immer möglich, und **nötig**, wenn die Subjekte **verschieden** sind.","examples":[{"de":"Ich trenne den Abfall, ==um== die Umwelt ==zu schützen==. (ich … ich)","en":"I sort my waste to protect the environment.","audio":"d9e030536004"},{"de":"Die Säcke sind teuer, ==damit== die Leute weniger Abfall ==produzieren==. (die Säcke … die Leute)","en":"The bags are expensive so that people produce less rubbish.","audio":"e1d992db3b39"}],"hEn":"Aim and purpose – um … zu or damit?","textP":[[["**um … zu + Infinitiv:** nur wenn das Subjekt in beiden Teilen **gleich** ist.","um … zu + infinitive: only when the subject is the same in both parts.",0],["**damit + Nebensatz:** immer möglich, und **nötig**, wenn die Subjekte **verschieden** sind.","damit + subordinate clause: always possible, and necessary when the subjects are different.",1]]]}],"tip":"„werden\" hat drei Aufgaben: Vollverb (Es wird kalt.), Futur (Ich werde morgen kommen.) und Passiv (Der Abfall wird abgeholt.). Beim Passiv steht immer ein Partizip II am Ende.","titleEn":"The passive and um … zu / damit","summaryS":[["Im Passiv ist die Handlung wichtig, nicht die Person.","In the passive the action is important, not the person.",0]],"tipP":[[["„werden\" hat drei Aufgaben: Vollverb (Es wird kalt.), Futur (Ich werde morgen kommen.) und Passiv (Der Abfall wird abgeholt.).","\"werden\" has three jobs: main verb (It's getting cold.), future (I'll come tomorrow.) and passive (The rubbish is collected.).",0],["Beim Passiv steht immer ein Partizip II am Ende.","In the passive there is always a past participle at the end.",0]]]},"exercises":[{"type":"choice","title":"Welche Form von werden?","items":[{"q":"Der Abfall ___ jeden Dienstag abgeholt.","options":["wird","werden","wirst"],"a":0,"full":"Der Abfall wird jeden Dienstag abgeholt.","audio":"1d3df9a9cbbf","en":"The rubbish is collected every Tuesday."},{"q":"Die Flaschen ___ im Supermarkt zurückgegeben.","options":["werden","wird","werdet"],"a":0,"full":"Die Flaschen werden im Supermarkt zurückgegeben.","audio":"b93e6ff14bf2","en":"The bottles are returned at the supermarket."},{"q":"Gestern ___ mein Velo gestohlen.","options":["wurde","wird","werden"],"a":0,"full":"Gestern wurde mein Velo gestohlen.","audio":"8767a8be328b","en":"My bike was stolen yesterday."},{"q":"Das Papier muss gebündelt ___.","options":["werden","wird","worden"],"a":0,"full":"Das Papier muss gebündelt werden.","audio":"36661d04b4f8","en":"The paper has to be bundled."},{"q":"In der Schweiz ___ sehr viel recycelt.","options":["wird","werden","ist"],"a":0,"full":"In der Schweiz wird sehr viel recycelt.","audio":"fbb772a4d4c5","en":"A great deal is recycled in Switzerland."},{"q":"Letztes Jahr ___ zwei neue Sammelstellen gebaut.","options":["wurden","wurde","werden"],"a":0,"full":"Letztes Jahr wurden zwei neue Sammelstellen gebaut.","audio":"e62a4609ed64","en":"Last year two new collection points were built."},{"q":"Batterien dürfen nicht in den Abfall geworfen ___.","options":["werden","wird","worden"],"a":0,"full":"Batterien dürfen nicht in den Abfall geworfen werden.","audio":"e52e6336d116","en":"Batteries must not be thrown in the rubbish."},{"q":"Wann ___ das Altpapier abgeholt?","options":["wird","werden","wirst"],"a":0,"full":"Wann wird das Altpapier abgeholt?","audio":"7d6391cb9663","en":"When is the waste paper collected?"}],"titleEn":"Which form of werden?"},{"type":"gap","title":"Ergänzen Sie das Partizip II","items":[{"q":"Der Abfall wird jeden Dienstag ___. (abholen)","a":["abgeholt"],"full":"Der Abfall wird jeden Dienstag abgeholt.","audio":"1d3df9a9cbbf","en":"The rubbish is collected every Tuesday."},{"q":"Glas wird nach Farben ___. (trennen)","a":["getrennt"],"full":"Glas wird nach Farben getrennt.","audio":"8d6e3c414e53","en":"Glass is sorted by colour."},{"q":"Die Säcke werden im Supermarkt ___. (verkaufen)","a":["verkauft"],"full":"Die Säcke werden im Supermarkt verkauft.","audio":"cb2ecaca556b","en":"The bags are sold at the supermarket."},{"q":"Das Altpapier muss ___ werden. (bündeln)","a":["gebündelt"],"full":"Das Altpapier muss gebündelt werden.","audio":"059240b4b4ec","en":"The waste paper has to be bundled."},{"q":"PET-Flaschen werden zu neuen Flaschen ___. (recyceln)","a":["recycelt"],"full":"PET-Flaschen werden zu neuen Flaschen recycelt.","audio":"6fa752e96ea9","en":"PET bottles are recycled into new bottles."},{"q":"Hier darf kein Abfall ___ werden. (wegwerfen)","a":["weggeworfen"],"full":"Hier darf kein Abfall weggeworfen werden.","audio":"977f216e1cf1","en":"No rubbish may be thrown away here."}],"titleEn":"Fill in the past participle"},{"type":"choice","title":"um … zu oder damit?","items":[{"q":"Ich trenne den Abfall, ___ die Umwelt zu schützen.","options":["um","damit"],"a":0,"full":"Ich trenne den Abfall, um die Umwelt zu schützen.","audio":"d9e030536004","en":"I sort my rubbish to protect the environment."},{"q":"Wir kaufen Gebührensäcke, ___ der Abfall abgeholt wird.","options":["damit","um"],"a":0,"full":"Wir kaufen Gebührensäcke, damit der Abfall abgeholt wird.","audio":"ea487fb8a2cc","en":"We buy fee bags so that the rubbish gets collected."},{"q":"Frau Rossi erklärt alles, ___ Carla keine Busse bekommt.","options":["damit","um"],"a":0,"full":"Frau Rossi erklärt alles, damit Carla keine Busse bekommt.","audio":"d81ca66544b9","en":"Ms Rossi explains everything so that Carla doesn't get a fine."},{"q":"Ich gehe in den Supermarkt, ___ die PET-Flaschen zurückzugeben.","options":["um","damit"],"a":0,"full":"Ich gehe in den Supermarkt, um die PET-Flaschen zurückzugeben.","audio":"c64f9c207f67","en":"I'm going to the supermarket to return the PET bottles."},{"q":"Die Säcke sind teuer, ___ die Leute weniger Abfall produzieren.","options":["damit","um"],"a":0,"full":"Die Säcke sind teuer, damit die Leute weniger Abfall produzieren.","audio":"e1d992db3b39","en":"The bags are expensive so that people produce less rubbish."},{"q":"Er steht früh auf, ___ das Altpapier an die Strasse zu stellen.","options":["um","damit"],"a":0,"full":"Er steht früh auf, um das Altpapier an die Strasse zu stellen.","audio":"c831027ab797","en":"He gets up early to put the waste paper out on the street."}],"titleEn":"um … zu or damit?"},{"type":"order","title":"Bilden Sie Sätze","items":[{"a":["Der Abfall wird jeden Dienstag abgeholt.","Jeden Dienstag wird der Abfall abgeholt."],"tokens":["Der","Abfall","wird","jeden","Dienstag","abgeholt."],"audio":"1d3df9a9cbbf","en":"The rubbish is collected every Tuesday."},{"a":["Das Altpapier muss gebündelt werden."],"tokens":["Das","Altpapier","muss","gebündelt","werden."],"audio":"059240b4b4ec","en":"The waste paper has to be bundled."},{"a":["Mein Sack wurde gestern nicht abgeholt.","Gestern wurde mein Sack nicht abgeholt."],"tokens":["Mein","Sack","wurde","gestern","nicht","abgeholt."],"audio":"024eaa4bcc1e","en":"My bag wasn't collected yesterday."},{"a":["Ich trenne den Abfall, um die Umwelt zu schützen."],"tokens":["Ich","trenne","den","Abfall,","um","die","Umwelt","zu","schützen."],"audio":"d9e030536004","en":"I sort my rubbish to protect the environment."},{"a":["Sie bringt das Glas zur Sammelstelle, damit es recycelt wird."],"tokens":["Sie","bringt","das","Glas","zur","Sammelstelle,","damit","es","recycelt","wird."],"audio":"8ef77e278a6e","en":"She takes the glass to the collection point so that it gets recycled."}],"titleEn":"Make sentences"},{"type":"dictation","title":"Diktat – hören und schreiben","items":[{"a":"Der Abfall wird am Dienstag abgeholt.","audio":"48996b4b169b","en":"The rubbish is collected on Tuesday."},{"a":"Das Altpapier muss gebündelt werden.","audio":"0d74a49e0f48","en":"The waste paper has to be bundled."},{"a":"Warum wurde mein Sack nicht abgeholt?","audio":"7602e2066b18","en":"Why wasn't my bag collected?"},{"a":"Wir trennen den Abfall, um die Umwelt zu schützen.","audio":"5cdff0dbdac8","en":"We sort our rubbish to protect the environment."}],"titleEn":"Dictation – listen and write"}],"reading":{"title":"Abfall richtig entsorgen – Merkblatt für Neuzuzüger","kind":"Merkblatt","paras":[{"t":"**Kehricht:** Der normale Abfall wird jeden Dienstag abgeholt. Es werden nur offizielle Gebührensäcke mitgenommen. Die Säcke können in allen Supermärkten der Gemeinde gekauft werden. Bitte stellen Sie die Säcke erst am Dienstagmorgen vor 7 Uhr an die Strasse, damit sie nicht von Tieren geöffnet werden.","audio":"399e504830b1","s":[["**Kehricht:** Der normale Abfall wird jeden Dienstag abgeholt.","Household rubbish: normal rubbish is collected every Tuesday.",0],["Es werden nur offizielle Gebührensäcke mitgenommen.","Only official fee bags are taken.",0],["Die Säcke können in allen Supermärkten der Gemeinde gekauft werden.","The bags can be bought in all supermarkets in the municipality.",0],["Bitte stellen Sie die Säcke erst am Dienstagmorgen vor 7 Uhr an die Strasse, damit sie nicht von Tieren geöffnet werden.","Please don't put the bags out on the street until Tuesday morning before 7 a.m., so that they aren't torn open by animals.",0]]},{"t":"**Altpapier und Karton:** Papier und Karton werden jeden ersten Mittwoch im Monat gesammelt. Sie müssen gebündelt werden – Papier in Taschen oder Schachteln wird nicht mitgenommen.","audio":"c750b0aa718f","s":[["**Altpapier und Karton:** Papier und Karton werden jeden ersten Mittwoch im Monat gesammelt.","Waste paper and cardboard: paper and cardboard are collected on the first Wednesday of every month.",0],["Sie müssen gebündelt werden – Papier in Taschen oder Schachteln wird nicht mitgenommen.","They have to be bundled – paper in bags or boxes is not taken.",0]]},{"t":"**Glas und Metall:** Diese Materialien werden an der Sammelstelle beim Werkhof angenommen. Glas wird dort nach Farben getrennt: weiss, braun und grün. Einwurfzeiten: Montag bis Samstag, 8 bis 19 Uhr.","audio":"b7d7cae34bdf","s":[["**Glas und Metall:** Diese Materialien werden an der Sammelstelle beim Werkhof angenommen.","Glass and metal: these materials are accepted at the collection point at the municipal depot.",0],["Glas wird dort nach Farben getrennt: weiss, braun und grün.","There, glass is sorted by colour: white, brown and green.",0],["Einwurfzeiten: Montag bis Samstag, 8 bis 19 Uhr.","Drop-off times: Monday to Saturday, 8 a.m. to 7 p.m.",0]]},{"t":"**PET und Batterien:** PET-Flaschen und Batterien können in allen Verkaufsstellen zurückgegeben werden.","audio":"996fc979c276","s":[["**PET und Batterien:** PET-Flaschen und Batterien können in allen Verkaufsstellen zurückgegeben werden.","PET and batteries: PET bottles and batteries can be returned at any shop that sells them.",0]]},{"t":"**Grüngut:** Garten- und Küchenabfälle werden in der grünen Tonne gesammelt. Die Tonne wird im Sommer jede Woche und im Winter alle zwei Wochen geleert.","audio":"32549485de5b","s":[["**Grüngut:** Garten- und Küchenabfälle werden in der grünen Tonne gesammelt.","Green waste: garden and kitchen waste are collected in the green bin.",0],["Die Tonne wird im Sommer jede Woche und im Winter alle zwei Wochen geleert.","The bin is emptied every week in summer and every two weeks in winter.",0]]},{"t":"**Wichtig:** Wer Abfall illegal entsorgt, zum Beispiel im Wald oder in fremden Containern, muss mit einer Busse rechnen. Bei Fragen hilft Ihnen die Gemeindeverwaltung gern weiter.","audio":"c3dd730e06b2","s":[["**Wichtig:** Wer Abfall illegal entsorgt, zum Beispiel im Wald oder in fremden Containern, muss mit einer Busse rechnen.","Important: anyone who dumps rubbish illegally, for example in the forest or in other people's containers, can expect a fine.",0],["Bei Fragen hilft Ihnen die Gemeindeverwaltung gern weiter.","If you have questions, the municipal administration will be happy to help.",0]]}],"glossary":[{"de":"der Kehricht (CH)","en":"household rubbish"},{"de":"die Schachtel","en":"box"},{"de":"der Werkhof (CH)","en":"municipal depot"},{"de":"die Einwurfzeiten","en":"times when you may drop items in"},{"de":"die Verkaufsstelle","en":"shop, point of sale"},{"de":"leeren","en":"to empty"}],"questions":[{"type":"tf","q":"Der normale Abfall wird jeden Dienstag abgeholt.","a":true,"why":"","qEn":"Normal rubbish is collected every Tuesday."},{"type":"mc","q":"Wann soll man die Gebührensäcke an die Strasse stellen?","options":["am Montagabend","am Dienstagmorgen vor 7 Uhr","am Dienstagmittag"],"a":1,"qEn":"When should you put the fee bags out on the street?","optionsEn":["on Monday evening","on Tuesday morning before 7 a.m.","on Tuesday at midday"]},{"type":"tf","q":"Altpapier in einer Tasche wird auch mitgenommen.","a":false,"why":"Es muss gebündelt werden.","qEn":"Waste paper in a bag is also collected.","whyEn":"It has to be bundled."},{"type":"mc","q":"Wo kann man Batterien zurückgeben?","options":["nur beim Werkhof","in allen Verkaufsstellen","in der grünen Tonne"],"a":1,"qEn":"Where can you return batteries?","optionsEn":["only at the municipal depot","at all shops that sell them","in the green bin"]},{"type":"mc","q":"Was passiert, wenn man Abfall im Wald entsorgt?","options":["Man muss mit einer Busse rechnen.","Nichts.","Der Abfall wird gratis abgeholt."],"a":0,"qEn":"What happens if you dump rubbish in the forest?","optionsEn":["You can expect a fine.","Nothing.","The rubbish is collected for free."]}],"titleEn":"Disposing of waste correctly – information sheet for newcomers"},"writing":{"task":"Ein Freund zieht bald in die Schweiz. Er fragt Sie, wie das mit dem Abfall funktioniert. Schreiben Sie ihm eine E-Mail (80–100 Wörter).","points":["Was ist anders als in Ihrem Heimatland?","Wie wird der Abfall getrennt? (Passiv)","Geben Sie einen Tipp.","Was denken Sie über die Regeln?"],"phrases":[{"de":"Das ist ganz anders als in …","en":"That's quite different from …"},{"de":"Der Abfall wird …","en":"The rubbish is …"},{"de":"Mein Tipp – …","en":"My tip – …"},{"de":"Ich finde die Regeln gut / streng, weil …","en":"I think the rules are good / strict because …"}],"model":"Hallo Pedro\n\nDu hast mich gefragt, wie das mit dem Abfall in der Schweiz funktioniert. Das ist ganz anders als in Portugal! Der normale Abfall wird nur in offiziellen Gebührensäcken mitgenommen – die kannst du im Supermarkt kaufen. Papier und Karton werden separat gesammelt und müssen gebündelt werden. Glas bringst du zur Sammelstelle, und PET-Flaschen gibst du im Supermarkt zurück. Mein Tipp: Hol dir sofort den Abfallkalender, damit du keine Busse bekommst! Am Anfang ist es kompliziert, aber ich finde die Regeln gut, weil so viel recycelt wird.\n\nBis bald!\nCarla","audio":"27b62db24d0e","taskS":[["Ein Freund zieht bald in die Schweiz.","A friend is moving to Switzerland soon.",0],["Er fragt Sie, wie das mit dem Abfall funktioniert.","He asks you how rubbish works.",0],["Schreiben Sie ihm eine E-Mail (80–100 Wörter).","Write him an email (80–100 words).",0]],"pointsEn":["What is different from your home country?","How is the rubbish sorted? (passive)","Give a tip.","What do you think of the rules?"],"modelP":[[["Hallo Pedro","Hi Pedro",0]],[["Du hast mich gefragt, wie das mit dem Abfall in der Schweiz funktioniert.","You asked me how rubbish works in Switzerland.",0],["Das ist ganz anders als in Portugal!","It's completely different from Portugal!",0],["Der normale Abfall wird nur in offiziellen Gebührensäcken mitgenommen – die kannst du im Supermarkt kaufen.","Normal rubbish is only collected in official fee bags – you can buy them at the supermarket.",0],["Papier und Karton werden separat gesammelt und müssen gebündelt werden.","Paper and cardboard are collected separately and have to be bundled.",0],["Glas bringst du zur Sammelstelle, und PET-Flaschen gibst du im Supermarkt zurück.","You take glass to the collection point, and you return PET bottles at the supermarket.",0],["Mein Tipp: Hol dir sofort den Abfallkalender, damit du keine Busse bekommst!","My tip: get the waste calendar straight away so you don't get a fine!",0],["Am Anfang ist es kompliziert, aber ich finde die Regeln gut, weil so viel recycelt wird.","At first it's complicated, but I think the rules are good because so much gets recycled.",0]],[["Bis bald!","See you soon!",0],["Carla","Carla",1]]]},"speaking":{"task":"Vergleichen Sie und sagen Sie Ihre Meinung. Antworten Sie in drei bis vier Sätzen.","phrases":[{"de":"Bei uns wird …","en":"In my country … is …","audio":null},{"de":"Im Vergleich zu …","en":"Compared with …","audio":null},{"de":"Ich finde es gut / nicht so gut, dass …","en":"I think it's good / not so good that …","audio":null},{"de":"Meiner Meinung nach …","en":"In my opinion …","audio":null},{"de":"um … zu / damit …","en":"in order to / so that …","audio":null}],"prompts":[{"q":"Wie wird der Abfall in Ihrem Heimatland entsorgt?","model":"In Portugal wird der Abfall meistens in grosse Container auf der Strasse geworfen. Glas und Papier werden auch getrennt, aber nicht so genau wie hier.","aq":"d91e89ec2496","am":"02cef98cd31d","qS":[["Wie wird der Abfall in Ihrem Heimatland entsorgt?","How is rubbish disposed of in your home country?",0]],"modelS":[["In Portugal wird der Abfall meistens in grosse Container auf der Strasse geworfen.","In Portugal rubbish is mostly thrown into big containers on the street.",0],["Glas und Papier werden auch getrennt, aber nicht so genau wie hier.","Glass and paper are also separated, but not as carefully as here.",0]]},{"q":"Was finden Sie an den Schweizer Regeln gut, und was ist schwierig?","model":"Ich finde gut, dass so viel recycelt wird. Schwierig ist, dass man so viele Regeln und Termine kennen muss.","aq":"e74609755337","am":"aaac9e27e984","qS":[["Was finden Sie an den Schweizer Regeln gut, und was ist schwierig?","What do you like about the Swiss rules, and what is difficult?",0]],"modelS":[["Ich finde gut, dass so viel recycelt wird.","I think it's good that so much is recycled.",0],["Schwierig ist, dass man so viele Regeln und Termine kennen muss.","What's difficult is that you have to know so many rules and dates.",0]]},{"q":"Was machen Sie persönlich, um die Umwelt zu schützen?","model":"Ich fahre mit dem Velo oder mit dem Zug, und ich trenne meinen Abfall. Ausserdem versuche ich, möglichst wenig Plastik zu kaufen.","aq":"6146378c20c1","am":"ab9f716e142c","qS":[["Was machen Sie persönlich, um die Umwelt zu schützen?","What do you personally do to protect the environment?",0]],"modelS":[["Ich fahre mit dem Velo oder mit dem Zug, und ich trenne meinen Abfall.","I travel by bike or by train, and I sort my rubbish.",0],["Ausserdem versuche ich, möglichst wenig Plastik zu kaufen.","I also try to buy as little plastic as possible.",0]]},{"q":"Sind Gebührensäcke Ihrer Meinung nach eine gute Idee?","model":"Ja, ich finde sie gut, weil die Leute dann weniger Abfall produzieren. Aber für Familien mit wenig Geld sind sie vielleicht zu teuer.","aq":"81f4a4766061","am":"4d2f75a235a0","qS":[["Sind Gebührensäcke Ihrer Meinung nach eine gute Idee?","In your opinion, are fee bags a good idea?",0]],"modelS":[["Ja, ich finde sie gut, weil die Leute dann weniger Abfall produzieren.","Yes, I think they're good, because people then produce less rubbish.",0],["Aber für Familien mit wenig Geld sind sie vielleicht zu teuer.","But for families with little money they might be too expensive.",0]]}],"taskS":[["Vergleichen Sie und sagen Sie Ihre Meinung.","Compare and give your opinion.",0],["Antworten Sie in drei bis vier Sätzen.","Answer in three to four sentences.",0]]},"en":{"title":"Waste and the environment","subtitle":"Recycling by Swiss rules","focus":"Passive (present, simple past, with a modal verb) and um … zu / damit"}},{"id":10,"title":"Ein Unfall mit dem Velo","subtitle":"Erzählen, was passiert ist, und einen Unfall melden","level":"B1","theme":"Notfall und Versicherung","focus":"Präteritum, Plusquamperfekt und temporale Nebensätze (als, wenn, bevor, nachdem, während)","goals":[{"de":"Ich kann einen Unfall telefonisch melden und Fragen dazu beantworten.","en":"I can report an accident by phone and answer questions about it."},{"de":"Ich kann einen kurzen schriftlichen Bericht über ein Ereignis verstehen und schreiben.","en":"I can understand and write a short written report about an event."},{"de":"Ich kann Ereignisse zeitlich ordnen (als, bevor, nachdem, während).","en":"I can put events in time order."}],"vocab":[{"id":"10-0","de":"der Unfall","forms":"Unfälle","en":"accident","ex":"Wann ist der Unfall passiert?","exEn":"When did the accident happen?","aw":"802447c9914e","ae":"ca72e940f08d"},{"id":"10-1","de":"passieren","forms":"ist passiert","en":"to happen","ex":"Zum Glück ist nichts Schlimmes passiert.","exEn":"Luckily nothing serious happened.","aw":"088d8a93de88","ae":"82ab1306c9a9"},{"id":"10-2","de":"stürzen","forms":"ist gestürzt","en":"to fall (over)","ex":"Sie ist mit dem Velo gestürzt.","exEn":"She fell off her bike.","aw":"bd7bc3e67525","ae":"fbc7cacd8cc2"},{"id":"10-3","de":"sich verletzen","forms":"hat sich verletzt","en":"to injure yourself","ex":"Hast du dich verletzt?","exEn":"Did you hurt yourself?","aw":"e3c92f6be2c1","ae":"7942128d2727"},{"id":"10-4","de":"die Verletzung","forms":"-en","en":"injury","ex":"Die Verletzung ist nicht gefährlich.","exEn":"The injury isn't dangerous.","aw":"d1276e6b82d1","ae":"7e4fee5168ed"},{"id":"10-5","de":"bremsen","forms":"hat gebremst","en":"to brake","ex":"Ich habe zu spät gebremst.","exEn":"I braked too late.","aw":"1017b68e1644","ae":"9a6264f77ef3"},{"id":"10-6","de":"ausweichen","forms":"ist ausgewichen","en":"to swerve, get out of the way","ex":"Er ist dem Auto im letzten Moment ausgewichen.","exEn":"He swerved around the car at the last moment.","aw":"140319501dfb","ae":"199346db83f8"},{"id":"10-7","de":"der Zeuge","forms":"-n","en":"witness","ex":"Gab es Zeugen?","exEn":"Were there any witnesses?","aw":"04fb55c0e9ef","ae":"ebe0ae8f89e0"},{"id":"10-8","de":"die Versicherung","forms":"-en","en":"insurance","ex":"Die Versicherung übernimmt die Kosten.","exEn":"The insurance covers the costs.","aw":"fb5f9f42f0d3","ae":"e32886d5a317"},{"id":"10-9","de":"der Schaden","forms":"Schäden","en":"damage","ex":"Am Auto gibt es keinen grossen Schaden.","exEn":"There's no major damage to the car.","aw":"45f89a06748a","ae":"f5be18ec39eb"},{"id":"10-10","de":"melden","forms":"hat gemeldet","en":"to report","ex":"Sie müssen den Unfall innerhalb von drei Tagen melden.","exEn":"You have to report the accident within three days.","aw":"944374aa6e3f","ae":"913db6295c4d"},{"id":"10-11","de":"die Unfallmeldung","forms":"-en","en":"accident report form","ex":"Füllen Sie bitte die Unfallmeldung aus.","exEn":"Please fill in the accident report.","aw":"1303a200cd2d","ae":"14cc142070ef"},{"id":"10-12","de":"die Ambulanz","forms":"-en","en":"ambulance (CH)","ex":"Die Ambulanz war nach zehn Minuten da.","exEn":"The ambulance was there after ten minutes.","aw":"0db1f053ee09","ae":"0bd479d3bdec"},{"id":"10-13","de":"die Behandlung","forms":"-en","en":"(medical) treatment","ex":"Die Behandlung dauert ungefähr sechs Wochen.","exEn":"The treatment takes about six weeks.","aw":"f1f05afa134a","ae":"ca61643f556a"},{"id":"10-14","de":"gebrochen","forms":"–","en":"broken (bone)","ex":"Der Arm ist zum Glück nicht gebrochen.","exEn":"Luckily the arm isn't broken.","aw":"fb094926fbbe","ae":"b4e1c48ef2b4"},{"id":"10-15","de":"das Handgelenk","forms":"-e","en":"wrist","ex":"Mein Handgelenk tut sehr weh.","exEn":"My wrist hurts a lot.","aw":"211295cd2f95","ae":"a240612be9e7"},{"id":"10-16","de":"die Kreuzung","forms":"-en","en":"crossroads, junction","ex":"An dieser Kreuzung passieren oft Unfälle.","exEn":"Accidents often happen at this junction.","aw":"eec2ee13ef42","ae":"0531766316e2"},{"id":"10-17","de":"der Fussgängerstreifen","forms":"-","en":"zebra crossing (CH)","ex":"Bitte über den Fussgängerstreifen gehen!","exEn":"Please use the zebra crossing!","aw":"166d00f776c2","ae":"875e93176eaf"},{"id":"10-18","de":"der Velohelm","forms":"-e","en":"bike helmet (CH)","ex":"Ohne Velohelm fahre ich nie.","exEn":"I never ride without a helmet.","aw":"778a2784c56e","ae":"074f525ec052"},{"id":"10-19","de":"vorsichtig","forms":"–","en":"careful","ex":"Fahr bitte vorsichtig, die Strasse ist nass!","exEn":"Please ride carefully, the road is wet!","aw":"5a9a8b8b0b6f","ae":"22acfaa661d3"}],"swiss":[{"ch":"die Ambulanz","std":"der Rettungswagen","en":"ambulance"},{"ch":"der Fussgängerstreifen","std":"der Zebrastreifen","en":"zebra crossing"},{"ch":"der Velostreifen","std":"der Radweg","en":"cycle lane"},{"ch":"die Unfallversicherung","std":"–","en":"if you work at least 8 hours a week, your employer's insurance also covers accidents in your free time"}],"dialogue":{"title":"Einen Unfall melden","intro":"Carla hatte einen Unfall mit dem Velo. Sie ruft die Unfallversicherung ihres Arbeitgebers an.","speakers":{"F":"Carla","M":"Herr Huber"},"lines":[{"s":"M","de":"Unfallabteilung, Huber, guten Tag. Wie kann ich Ihnen helfen?","en":"Accident department, Huber speaking, hello. How can I help you?","audio":"5776526dd9ca"},{"s":"F","de":"Guten Tag, hier ist Carla Ferreira. Ich möchte einen Unfall melden. Mein Arbeitgeber hat gesagt, dass ich Sie anrufen soll.","en":"Hello, this is Carla Ferreira. I'd like to report an accident. My employer told me to call you.","audio":"a8631f9f778b"},{"s":"M","de":"Das tut mir leid. Wann ist der Unfall passiert?","en":"I'm sorry to hear that. When did the accident happen?","audio":"a9d87b6f5799"},{"s":"F","de":"Letzten Donnerstag, am Abend. Ich war mit dem Velo auf dem Heimweg von der Arbeit.","en":"Last Thursday, in the evening. I was cycling home from work.","audio":"03267c887c79"},{"s":"M","de":"Können Sie mir erzählen, was genau passiert ist?","en":"Can you tell me what exactly happened?","audio":"19acc9308788"},{"s":"F","de":"Ja. Als ich zu einer Kreuzung gekommen bin, ist plötzlich ein Lieferwagen aus einer Einfahrt gefahren. Ich habe sofort gebremst, aber die Strasse war nass, weil es vorher stark geregnet hatte.","en":"Yes. When I got to a junction, a van suddenly pulled out of a driveway. I braked immediately, but the road was wet because it had rained heavily before.","audio":"25f51a7fec29"},{"s":"M","de":"Und dann?","en":"And then?","audio":"a85e1fdd406a"},{"s":"F","de":"Ich wollte ausweichen, und dabei bin ich gestürzt. Ich bin auf die rechte Hand gefallen.","en":"I tried to swerve, and I fell. I landed on my right hand.","audio":"1fe558f96086"},{"s":"M","de":"Haben Sie sich schwer verletzt?","en":"Were you badly hurt?","audio":"8f5c7d06e48c"},{"s":"F","de":"Das Handgelenk ist gebrochen. Nachdem mich die Ambulanz ins Spital gebracht hatte, wurde es geröntgt und eingegipst. Jetzt habe ich sechs Wochen einen Gips.","en":"My wrist is broken. After the ambulance had taken me to hospital, it was X-rayed and put in a cast. Now I have a cast for six weeks.","audio":"a7b86ecd584c"},{"s":"M","de":"Das klingt schmerzhaft. Haben Sie einen Velohelm getragen?","en":"That sounds painful. Were you wearing a bike helmet?","audio":"7a55e49eae15"},{"s":"F","de":"Ja, zum Glück. Der Helm ist kaputt, aber mein Kopf nicht!","en":"Yes, luckily. The helmet is broken, but my head isn't!","audio":"eda33910db2a"},{"s":"M","de":"Sehr gut. Gab es Zeugen?","en":"Very good. Were there any witnesses?","audio":"0c47f144717c"},{"s":"F","de":"Ja, eine Frau hat alles gesehen, während sie am Fussgängerstreifen gewartet hat. Sie hat mir ihre Telefonnummer gegeben.","en":"Yes, a woman saw everything while she was waiting at the zebra crossing. She gave me her phone number.","audio":"8e41f3bf3390"},{"s":"M","de":"Perfekt. Und hat der Fahrer angehalten?","en":"Perfect. And did the driver stop?","audio":"e23b4179e610"},{"s":"F","de":"Ja, er ist sofort ausgestiegen und hat mir geholfen. Bevor die Ambulanz kam, hat er auch die Polizei angerufen.","en":"Yes, he got out straight away and helped me. Before the ambulance came, he also called the police.","audio":"faa9a6fc8fb7"},{"s":"M","de":"Gut. Bitte füllen Sie die Unfallmeldung online aus und schicken Sie uns den Arztbericht. Die Kosten für die Behandlung übernehmen wir.","en":"Good. Please fill in the accident report online and send us the medical report. We'll cover the treatment costs.","audio":"cc55c0ea5828"},{"s":"F","de":"Und was ist mit meinem Velo? Es hat einen grossen Schaden.","en":"And what about my bike? It's badly damaged.","audio":"37fba6240c90"},{"s":"M","de":"Das müssen Sie mit der Versicherung des Fahrers klären. Für Sachschäden sind wir leider nicht zuständig.","en":"You'll need to sort that out with the driver's insurance. Unfortunately we're not responsible for property damage.","audio":"5f5b2509ec4d"},{"s":"F","de":"Verstehe. Vielen Dank für Ihre Hilfe.","en":"I understand. Thank you for your help.","audio":"265eff93df66"},{"s":"M","de":"Gern geschehen. Ich wünsche Ihnen gute Besserung!","en":"You're welcome. I wish you a speedy recovery!","audio":"d30f42674311"}],"questions":[{"type":"tf","q":"Der Unfall ist am Morgen passiert.","a":false,"why":"Er ist am Abend auf dem Heimweg passiert.","qEn":"The accident happened in the morning.","whyEn":"It happened in the evening on the way home."},{"type":"mc","q":"Warum ist Carla gestürzt?","options":["Sie ist zu schnell gefahren.","Sie wollte einem Lieferwagen ausweichen.","Sie hat den Velohelm vergessen."],"a":1,"qEn":"Why did Carla fall?","optionsEn":["She was riding too fast.","She wanted to swerve around a van.","She forgot her bike helmet."]},{"type":"mc","q":"Was hat sich Carla verletzt?","options":["den Kopf","das Knie","das Handgelenk"],"a":2,"qEn":"What did Carla injure?","optionsEn":["her head","her knee","her wrist"]},{"type":"tf","q":"Eine Zeugin hat den Unfall gesehen.","a":true,"why":"","qEn":"A witness saw the accident."},{"type":"mc","q":"Wer bezahlt den Schaden am Velo?","options":["die Unfallversicherung von Carla","Das muss Carla mit der Versicherung des Fahrers klären.","die Polizei"],"a":1,"qEn":"Who pays for the damage to the bike?","optionsEn":["Carla's accident insurance","Carla has to sort that out with the driver's insurance.","the police"]}],"titleEn":"Reporting an accident","introS":[["Carla hatte einen Unfall mit dem Velo.","Carla had an accident on her bike.",0],["Sie ruft die Unfallversicherung ihres Arbeitgebers an.","She calls her employer's accident insurance.",0]]},"grammar":{"title":"Erzählen – Präteritum, Plusquamperfekt und temporale Nebensätze","summary":"In geschriebenen Texten erzählt man im Präteritum. Temporale Konnektoren ordnen die Ereignisse.","sections":[{"h":"Das Präteritum","text":"In Berichten, Geschichten und Zeitungstexten benutzt man das **Präteritum**. Regelmässige Verben bekommen **-te**. Unregelmässige Verben ändern den Vokal und haben bei *ich* und *er/sie/es* **keine Endung**.","table":[["Person","bremsen (regelmässig)","fahren (unregelmässig)"],["ich","bremste","fuhr"],["du","bremstest","fuhrst"],["er/sie/es","bremste","fuhr"],["wir","bremsten","fuhren"],["ihr","bremstet","fuhrt"],["sie/Sie","bremsten","fuhren"]],"hEn":"The simple past","textP":[[["In Berichten, Geschichten und Zeitungstexten benutzt man das **Präteritum**.","In reports, stories and newspaper texts the simple past is used.",0],["Regelmässige Verben bekommen **-te**.","Regular verbs take -te.",0],["Unregelmässige Verben ändern den Vokal und haben bei *ich* und *er/sie/es* **keine Endung**.","Irregular verbs change their vowel and have no ending with ich and er/sie/es.",0]]]},{"h":"Wichtige unregelmässige Verben","table":[["Infinitiv","Präteritum","Infinitiv","Präteritum"],["kommen","kam","sehen","sah"],["gehen","ging","fallen","fiel"],["geben","gab","rufen","rief"],["stehen","stand","helfen","half"],["bringen","brachte","denken","dachte"],["wissen","wusste","tragen","trug"]],"hEn":"Important irregular verbs"},{"h":"als oder wenn?","text":"**als** – ein einziges Mal in der Vergangenheit (oder eine Zeitperiode: *als ich ein Kind war*).\n**wenn** – immer wieder (*jedes Mal, wenn …*) und in der Gegenwart oder Zukunft.","examples":[{"de":"==Als== ich zur Kreuzung kam, fuhr plötzlich ein Auto los.","en":"When I got to the junction, a car suddenly pulled out.","audio":"a699481e3801"},{"de":"==Wenn== es regnet, fahre ich immer langsam.","en":"Whenever it rains, I always ride slowly.","audio":"2bff3c2082a3"}],"hEn":"als or wenn?","textP":[[["**als** – ein einziges Mal in der Vergangenheit (oder eine Zeitperiode: *als ich ein Kind war*).","als – a single time in the past (or a period of time: when I was a child).",0],["**wenn** – immer wieder (*jedes Mal, wenn …*) und in der Gegenwart oder Zukunft.","wenn – again and again (every time …) and in the present or future.",1]]]},{"h":"bevor, nachdem, während","table":[["Konnektor","Bedeutung","Beispiel"],["bevor","zuerst der Hauptsatz, dann der Nebensatz","Bevor ich losfahre, setze ich den Helm auf."],["nachdem","zuerst der Nebensatz, dann der Hauptsatz","Nachdem der Arzt mich untersucht hatte, bekam ich einen Gips."],["während","gleichzeitig","Während sie wartete, sah sie den Unfall."]],"hEn":"bevor, nachdem, während"},{"h":"Das Plusquamperfekt – die Vergangenheit vor der Vergangenheit","text":"**hatte / war + Partizip II**. Man benutzt es für etwas, das **vor** einem anderen Ereignis in der Vergangenheit passiert ist – besonders nach **nachdem**.","examples":[{"de":"Die Strasse war nass, weil es vorher ==geregnet hatte==.","en":"The road was wet because it had rained before.","audio":"51186118ac2d"},{"de":"Nachdem die Ambulanz ==gekommen war==, ging alles sehr schnell.","en":"After the ambulance had arrived, everything happened very quickly.","audio":"51838fc43ae8"}],"hEn":"The past perfect – the past before the past","textP":[[["**hatte / war + Partizip II**.","hatte / war + past participle.",0],["Man benutzt es für etwas, das **vor** einem anderen Ereignis in der Vergangenheit passiert ist – besonders nach **nachdem**.","You use it for something that happened before another event in the past – especially after nachdem.",0]]]}],"tip":"Im Gespräch benutzt man meistens das Perfekt – in der Schweiz fast immer. Aber bei sein, haben und den Modalverben benutzt man auch mündlich das Präteritum: war, hatte, wollte, konnte.","titleEn":"Telling a story – simple past, past perfect and time clauses","summaryS":[["In geschriebenen Texten erzählt man im Präteritum.","In written texts, stories are told in the simple past.",0],["Temporale Konnektoren ordnen die Ereignisse.","Time connectors put the events in order.",0]],"tipP":[[["Im Gespräch benutzt man meistens das Perfekt – in der Schweiz fast immer.","In conversation people mostly use the perfect tense – in Switzerland almost always.",0],["Aber bei sein, haben und den Modalverben benutzt man auch mündlich das Präteritum: war, hatte, wollte, konnte.","But with sein, haben and the modal verbs, people also use the simple past when speaking: war, hatte, wollte, konnte.",0]]]},"exercises":[{"type":"choice","title":"Welcher Konnektor passt?","items":[{"q":"___ ich zur Kreuzung kam, fuhr plötzlich ein Auto los.","options":["Als","Wenn","Bevor"],"a":0,"full":"Als ich zur Kreuzung kam, fuhr plötzlich ein Auto los.","audio":"a699481e3801","en":"When I got to the junction, a car suddenly pulled out."},{"q":"___ es regnet, fahre ich immer mit dem Bus.","options":["Wenn","Als","Nachdem"],"a":0,"full":"Wenn es regnet, fahre ich immer mit dem Bus.","audio":"ff5bc030a6f5","en":"When it rains, I always take the bus."},{"q":"___ ich losfahre, setze ich immer den Helm auf.","options":["Bevor","Nachdem","Als"],"a":0,"full":"Bevor ich losfahre, setze ich immer den Helm auf.","audio":"fe96f3232ac4","en":"Before I set off, I always put my helmet on."},{"q":"___ der Arzt die Hand geröntgt hatte, bekam ich einen Gips.","options":["Nachdem","Bevor","Während"],"a":0,"full":"Nachdem der Arzt die Hand geröntgt hatte, bekam ich einen Gips.","audio":"6c485595cb41","en":"After the doctor had X-rayed my hand, I got a cast."},{"q":"___ die Frau wartete, sah sie den Unfall.","options":["Während","Bevor","Nachdem"],"a":0,"full":"Während die Frau wartete, sah sie den Unfall.","audio":"693852d17ffd","en":"While the woman was waiting, she saw the accident."},{"q":"___ ich ein Kind war, fuhr ich jeden Tag mit dem Velo zur Schule.","options":["Als","Wenn","Während"],"a":0,"full":"Als ich ein Kind war, fuhr ich jeden Tag mit dem Velo zur Schule.","audio":"b4d9bcd509b6","en":"When I was a child, I cycled to school every day."},{"q":"Jedes Mal, ___ ich an diese Kreuzung komme, bin ich jetzt sehr vorsichtig.","options":["wenn","als","bevor"],"a":0,"full":"Jedes Mal, wenn ich an diese Kreuzung komme, bin ich jetzt sehr vorsichtig.","audio":"94af4a242bea","en":"Every time I come to this junction, I'm now very careful."},{"q":"___ ich den Gips habe, fahre ich mit dem Bus zur Arbeit.","options":["Seit","Als","Bevor"],"a":0,"full":"Seit ich den Gips habe, fahre ich mit dem Bus zur Arbeit.","audio":"d641c46d5e2d","en":"Since I've had the cast, I've been taking the bus to work."}],"titleEn":"Which connector fits?"},{"type":"gap","title":"Präteritum – schreiben Sie die richtige Form","items":[{"q":"Gestern ___ ich mit dem Velo zur Arbeit. (fahren)","a":["fuhr"],"full":"Gestern fuhr ich mit dem Velo zur Arbeit.","audio":"3effe1916bea","en":"Yesterday I cycled to work."},{"q":"Plötzlich ___ ein Auto aus der Einfahrt. (kommen)","a":["kam"],"full":"Plötzlich kam ein Auto aus der Einfahrt.","audio":"86e1e8aa6f7f","en":"Suddenly a car came out of the driveway."},{"q":"Ich ___ sofort. (bremsen)","a":["bremste"],"full":"Ich bremste sofort.","audio":"a416d904556c","en":"I braked immediately."},{"q":"Eine Frau ___ den Unfall. (sehen)","a":["sah"],"full":"Eine Frau sah den Unfall.","audio":"d822b5d7102b","en":"A woman saw the accident."},{"q":"Der Fahrer ___ die Polizei. (rufen)","a":["rief"],"full":"Der Fahrer rief die Polizei.","audio":"07d856c3e0c5","en":"The driver called the police."},{"q":"Wir ___ zwei Stunden im Spital. (warten)","a":["warteten"],"full":"Wir warteten zwei Stunden im Spital.","audio":"ccf1cbd5c7b7","en":"We waited two hours at the hospital."},{"q":"Ich ___ auf die rechte Hand. (fallen)","a":["fiel"],"full":"Ich fiel auf die rechte Hand.","audio":"8eb63290517d","en":"I fell on my right hand."},{"q":"Zum Glück ___ ich einen Helm. (tragen)","a":["trug"],"full":"Zum Glück trug ich einen Helm.","audio":"635450131137","en":"Luckily I was wearing a helmet."}],"titleEn":"Simple past – write the correct form"},{"type":"gap","title":"Plusquamperfekt nach „nachdem\"","items":[{"q":"Nachdem es stark ___ hatte, war die Strasse nass. (regnen)","a":["geregnet"],"full":"Nachdem es stark geregnet hatte, war die Strasse nass.","audio":"8a9ad0ddc4fa","en":"After it had rained heavily, the road was wet."},{"q":"Nachdem die Ambulanz ___ war, ging alles sehr schnell. (kommen)","a":["gekommen"],"full":"Nachdem die Ambulanz gekommen war, ging alles sehr schnell.","audio":"51838fc43ae8","en":"After the ambulance had arrived, everything happened very quickly."},{"q":"Nachdem ich die Unfallmeldung ___ hatte, rief ich meine Chefin an. (ausfüllen)","a":["ausgefüllt"],"full":"Nachdem ich die Unfallmeldung ausgefüllt hatte, rief ich meine Chefin an.","audio":"173cf19fbb84","en":"After I had filled in the accident report, I called my boss."},{"q":"Nachdem wir im Spital ___ waren, fuhren wir nach Hause. (sein)","a":["gewesen"],"full":"Nachdem wir im Spital gewesen waren, fuhren wir nach Hause.","audio":"18523eca2581","en":"After we had been to the hospital, we drove home."},{"q":"Nachdem der Arzt mich ___ hatte, bekam ich einen Gips. (untersuchen)","a":["untersucht"],"full":"Nachdem der Arzt mich untersucht hatte, bekam ich einen Gips.","audio":"6d6c9b397de5","en":"After the doctor had examined me, I got a cast."}],"titleEn":"Past perfect after \"nachdem\""},{"type":"order","title":"Bilden Sie Sätze","items":[{"a":["Als ich zur Kreuzung kam, fuhr ein Auto aus der Einfahrt."],"tokens":["Als","ich","zur","Kreuzung","kam,","fuhr","ein","Auto","aus","der","Einfahrt."],"audio":"b3f948a737b6","en":"When I got to the junction, a car came out of the driveway."},{"a":["Bevor ich losfahre, setze ich den Helm auf.","Ich setze den Helm auf, bevor ich losfahre."],"tokens":["Bevor","ich","losfahre,","setze","ich","den","Helm","auf."],"audio":"cdf3d1c0c208","en":"Before I set off, I put my helmet on."},{"a":["Nachdem der Arzt mich untersucht hatte, bekam ich einen Gips."],"tokens":["Nachdem","der","Arzt","mich","untersucht","hatte,","bekam","ich","einen","Gips."],"audio":"6d6c9b397de5","en":"After the doctor had examined me, I got a cast."},{"a":["Während sie wartete, sah sie den Unfall.","Sie sah den Unfall, während sie wartete."],"tokens":["Während","sie","wartete,","sah","sie","den","Unfall."],"audio":"409c4f360aa4","en":"While she was waiting, she saw the accident."},{"a":["Wenn es regnet, fahre ich immer langsam.","Ich fahre immer langsam, wenn es regnet."],"tokens":["Wenn","es","regnet,","fahre","ich","immer","langsam."],"audio":"2bff3c2082a3","en":"When it rains, I always ride slowly."}],"titleEn":"Make sentences"},{"type":"match","title":"Infinitiv und Präteritum","items":[{"l":"kommen","r":"kam"},{"l":"fahren","r":"fuhr"},{"l":"sehen","r":"sah"},{"l":"fallen","r":"fiel"},{"l":"rufen","r":"rief"},{"l":"geben","r":"gab"},{"l":"wissen","r":"wusste"},{"l":"helfen","r":"half"}],"titleEn":"Infinitive and simple past"},{"type":"dictation","title":"Diktat – hören und schreiben","items":[{"a":"Als ich zur Kreuzung kam, fuhr plötzlich ein Auto los.","audio":"2904dce2631b","en":"When I got to the junction, a car suddenly pulled out."},{"a":"Ich wollte ausweichen und bin gestürzt.","audio":"796e6f603c96","en":"I tried to swerve and fell."},{"a":"Nachdem der Arzt mich untersucht hatte, bekam ich einen Gips.","audio":"84594c0bb960","en":"After the doctor had examined me, I got a cast."},{"a":"Gab es Zeugen?","audio":"ae6430d24b3c","en":"Were there any witnesses?"}],"titleEn":"Dictation – listen and write"}],"reading":{"title":"Unfallmeldung – Schilderung des Unfalls","kind":"Bericht","paras":[{"t":"Am Donnerstagabend fuhr ich gegen 18 Uhr mit dem Velo von der Arbeit nach Hause. Vorher hatte es stark geregnet, und die Strasse war noch nass. Ich fuhr auf dem Velostreifen in Richtung Zentrum.","audio":"1fc7541ce318","s":[["Am Donnerstagabend fuhr ich gegen 18 Uhr mit dem Velo von der Arbeit nach Hause.","On Thursday evening, at around 6 p.m., I was cycling home from work.",0],["Vorher hatte es stark geregnet, und die Strasse war noch nass.","It had rained heavily before, and the road was still wet.",0],["Ich fuhr auf dem Velostreifen in Richtung Zentrum.","I was riding in the cycle lane towards the town centre.",0]]},{"t":"Als ich zur Kreuzung mit der Bahnhofstrasse kam, fuhr plötzlich ein grauer Lieferwagen rückwärts aus einer Einfahrt. Der Fahrer hatte mich nicht gesehen. Ich bremste sofort und versuchte, nach links auszuweichen. Dabei rutschte mein Hinterrad weg, und ich stürzte auf die rechte Hand.","audio":"5b57e2b4d5e7","s":[["Als ich zur Kreuzung mit der Bahnhofstrasse kam, fuhr plötzlich ein grauer Lieferwagen rückwärts aus einer Einfahrt.","When I got to the junction with Bahnhofstrasse, a grey van suddenly reversed out of a driveway.",0],["Der Fahrer hatte mich nicht gesehen.","The driver hadn't seen me.",0],["Ich bremste sofort und versuchte, nach links auszuweichen.","I braked immediately and tried to swerve to the left.",0],["Dabei rutschte mein Hinterrad weg, und ich stürzte auf die rechte Hand.","My back wheel slipped away, and I fell on my right hand.",0]]},{"t":"Der Fahrer stieg sofort aus und half mir. Eine Fussgängerin, die am Fussgängerstreifen gewartet hatte, hatte den Unfall beobachtet. Sie gab mir ihre Kontaktdaten. Bevor die Ambulanz kam, rief der Fahrer auch die Polizei.","audio":"dd6c4352078b","s":[["Der Fahrer stieg sofort aus und half mir.","The driver got out straight away and helped me.",0],["Eine Fussgängerin, die am Fussgängerstreifen gewartet hatte, hatte den Unfall beobachtet.","A pedestrian who had been waiting at the zebra crossing had seen the accident.",0],["Sie gab mir ihre Kontaktdaten.","She gave me her contact details.",0],["Bevor die Ambulanz kam, rief der Fahrer auch die Polizei.","Before the ambulance came, the driver also called the police.",0]]},{"t":"Im Spital stellte man fest, dass mein rechtes Handgelenk gebrochen war. Ich bin für sechs Wochen krankgeschrieben. Mein Velo wurde stark beschädigt, und mein Velohelm ist ebenfalls kaputt.","audio":"7636c9f08284","s":[["Im Spital stellte man fest, dass mein rechtes Handgelenk gebrochen war.","At the hospital they found that my right wrist was broken.",0],["Ich bin für sechs Wochen krankgeschrieben.","I'm signed off sick for six weeks.",0],["Mein Velo wurde stark beschädigt, und mein Velohelm ist ebenfalls kaputt.","My bike was badly damaged, and my bike helmet is also broken.",0]]},{"t":"Carla Ferreira","audio":"40f9135d1b44","s":[["Carla Ferreira","Carla Ferreira",0]]}],"glossary":[{"de":"gegen 18 Uhr","en":"around 6 p.m."},{"de":"rückwärts","en":"backwards, in reverse"},{"de":"wegrutschen","en":"to slip away"},{"de":"beobachten","en":"to observe"},{"de":"feststellen","en":"to find, establish"},{"de":"beschädigt","en":"damaged"}],"questions":[{"type":"tf","q":"Die Strasse war nass, weil es vorher geregnet hatte.","a":true,"why":"","qEn":"The road was wet because it had rained before."},{"type":"mc","q":"Was machte der Lieferwagen?","options":["Er fuhr zu schnell.","Er fuhr rückwärts aus einer Einfahrt.","Er hielt am Fussgängerstreifen."],"a":1,"qEn":"What did the van do?","optionsEn":["It was going too fast.","It reversed out of a driveway.","It stopped at the zebra crossing."]},{"type":"tf","q":"Der Fahrer fuhr nach dem Unfall einfach weiter.","a":false,"why":"Er stieg sofort aus und half.","qEn":"After the accident the driver just drove on.","whyEn":"He got out straight away and helped."},{"type":"mc","q":"Wer hat den Unfall beobachtet?","options":["ein Polizist","eine Fussgängerin","ein anderer Velofahrer"],"a":1,"qEn":"Who saw the accident?","optionsEn":["a police officer","a pedestrian","another cyclist"]},{"type":"mc","q":"Was ist kaputt?","options":["nur das Velo","das Velo und der Helm","der Lieferwagen"],"a":1,"qEn":"What is broken?","optionsEn":["only the bike","the bike and the helmet","the van"]}],"titleEn":"Accident report – description of the accident"},"writing":{"task":"Sie hatten einen kleinen Unfall. Schreiben Sie einer Freundin eine E-Mail und erzählen Sie, was passiert ist (80–100 Wörter).","points":["Wann und wo ist es passiert?","Was ist passiert? (als, nachdem, bevor …)","Wie geht es Ihnen jetzt?","Was können Sie im Moment nicht machen?"],"phrases":[{"de":"Stell dir vor, …","en":"Imagine …"},{"de":"Als ich …, …","en":"When I …"},{"de":"Zuerst … dann … danach …","en":"First … then … after that …"},{"de":"Zum Glück … / Leider …","en":"Luckily … / Unfortunately …"},{"de":"Im Moment kann ich nicht …","en":"At the moment I can't …"}],"model":"Liebe Sofia\n\nStell dir vor, letzte Woche hatte ich einen Unfall mit dem Velo! Als ich am Donnerstagabend nach Hause fuhr, kam plötzlich ein Lieferwagen aus einer Einfahrt. Ich bremste, aber die Strasse war nass, und ich stürzte. Nachdem mich die Ambulanz ins Spital gebracht hatte, wurde mein Handgelenk geröntgt – es ist gebrochen. Jetzt habe ich sechs Wochen einen Gips. Zum Glück hatte ich einen Helm! Im Moment kann ich nicht Velo fahren und nur mit der linken Hand schreiben – deshalb ist diese E-Mail so kurz. Wie geht es dir?\n\nLiebe Grüsse\nCarla","audio":"c1c67a947a44","taskS":[["Sie hatten einen kleinen Unfall.","You had a minor accident.",0],["Schreiben Sie einer Freundin eine E-Mail und erzählen Sie, was passiert ist (80–100 Wörter).","Write an email to a friend and tell her what happened (80–100 words).",0]],"pointsEn":["When and where did it happen?","What happened? (als, nachdem, bevor …)","How are you now?","What can't you do at the moment?"],"modelP":[[["Liebe Sofia","Dear Sofia",0]],[["Stell dir vor, letzte Woche hatte ich einen Unfall mit dem Velo!","Guess what, last week I had an accident on my bike!",0],["Als ich am Donnerstagabend nach Hause fuhr, kam plötzlich ein Lieferwagen aus einer Einfahrt.","When I was cycling home on Thursday evening, a van suddenly came out of a driveway.",0],["Ich bremste, aber die Strasse war nass, und ich stürzte.","I braked, but the road was wet, and I fell.",0],["Nachdem mich die Ambulanz ins Spital gebracht hatte, wurde mein Handgelenk geröntgt – es ist gebrochen.","After the ambulance had taken me to hospital, my wrist was X-rayed – it's broken.",0],["Jetzt habe ich sechs Wochen einen Gips.","Now I have a cast for six weeks.",0],["Zum Glück hatte ich einen Helm!","Luckily I was wearing a helmet!",0],["Im Moment kann ich nicht Velo fahren und nur mit der linken Hand schreiben – deshalb ist diese E-Mail so kurz.","At the moment I can't ride my bike and can only write with my left hand – that's why this email is so short.",0],["Wie geht es dir?","How are you?",0]],[["Liebe Grüsse","Love",0],["Carla","Carla",1]]]},"speaking":{"task":"Erzählen Sie von Erlebnissen. Benutzen Sie als, bevor, nachdem oder während.","phrases":[{"de":"Als ich …, …","en":"When I …","audio":null},{"de":"Bevor ich …, …","en":"Before I …","audio":null},{"de":"Nachdem ich … hatte / war, …","en":"After I had …","audio":null},{"de":"Zum Glück … / Leider …","en":"Luckily … / Unfortunately …","audio":null},{"de":"Am Ende …","en":"In the end …","audio":null}],"prompts":[{"q":"Erzählen Sie von einem Erlebnis, bei dem etwas schiefgegangen ist.","model":"Als ich in die Schweiz gekommen bin, habe ich am ersten Tag meinen Koffer im Zug vergessen. Zum Glück hat ihn jemand gefunden und beim Fundbüro abgegeben.","aq":"8bbd05d975e1","am":"ea8dbe8a99b3","qS":[["Erzählen Sie von einem Erlebnis, bei dem etwas schiefgegangen ist.","Tell us about an experience when something went wrong.",0]],"modelS":[["Als ich in die Schweiz gekommen bin, habe ich am ersten Tag meinen Koffer im Zug vergessen.","When I came to Switzerland, I left my suitcase on the train on the first day.",0],["Zum Glück hat ihn jemand gefunden und beim Fundbüro abgegeben.","Luckily someone found it and handed it in at the lost property office.",0]]},{"q":"Was machen Sie, bevor Sie morgens aus dem Haus gehen?","model":"Bevor ich aus dem Haus gehe, trinke ich einen Kaffee und schaue, wie das Wetter wird. Wenn es regnet, fahre ich mit dem Bus und nicht mit dem Velo.","aq":"71fefbc9ac72","am":"92c18aacdae5","qS":[["Was machen Sie, bevor Sie morgens aus dem Haus gehen?","What do you do before you leave the house in the morning?",0]],"modelS":[["Bevor ich aus dem Haus gehe, trinke ich einen Kaffee und schaue, wie das Wetter wird.","Before I leave the house, I drink a coffee and check what the weather will be like.",0],["Wenn es regnet, fahre ich mit dem Bus und nicht mit dem Velo.","When it rains, I take the bus and not my bike.",0]]},{"q":"Was haben Sie gemacht, nachdem Sie in der Schweiz angekommen waren?","model":"Nachdem ich angekommen war, habe ich mich zuerst bei der Gemeinde angemeldet. Danach habe ich eine Krankenkasse gesucht und ein Bankkonto eröffnet.","aq":"f8cc40c1cd6f","am":"1eed680df30f","qS":[["Was haben Sie gemacht, nachdem Sie in der Schweiz angekommen waren?","What did you do after you had arrived in Switzerland?",0]],"modelS":[["Nachdem ich angekommen war, habe ich mich zuerst bei der Gemeinde angemeldet.","After I had arrived, I first registered with the municipality.",0],["Danach habe ich eine Krankenkasse gesucht und ein Bankkonto eröffnet.","Then I looked for health insurance and opened a bank account.",0]]},{"q":"Was hat Ihnen am meisten geholfen, als Sie neu hier waren?","model":"Als ich neu hier war, haben mir meine Nachbarn und meine Kollegen am meisten geholfen. Sie haben mir viel erklärt, zum Beispiel, wie man den Abfall trennt.","aq":"d25062503db9","am":"9f4be9cd7704","qS":[["Was hat Ihnen am meisten geholfen, als Sie neu hier waren?","What helped you most when you were new here?",0]],"modelS":[["Als ich neu hier war, haben mir meine Nachbarn und meine Kollegen am meisten geholfen.","When I was new here, my neighbours and colleagues helped me most.",0],["Sie haben mir viel erklärt, zum Beispiel, wie man den Abfall trennt.","They explained a lot to me, for example how to sort your rubbish.",0]]}],"taskS":[["Erzählen Sie von Erlebnissen.","Talk about things that have happened to you.",0],["Benutzen Sie als, bevor, nachdem oder während.","Use als, bevor, nachdem or während.",0]]},"en":{"title":"A bike accident","subtitle":"Telling what happened and reporting an accident","focus":"Simple past, past perfect and time clauses (als, wenn, bevor, nachdem, während)"}}],"audioMissing":0};
